import type { ExperienceSource, GameSave, PlayerAttributeBlock, PlayerExperienceLogEntry, PlayerState } from './types';
import { getLevelGrowthForProfession } from './professions';
import { createId, nowIso } from './save';
import { createEmptyAttributeBlock, ensurePlayerState, getPlayerStats, restorePlayerVitals } from './player';

export const MAX_PLAYER_LEVEL = 9999;

export interface LevelProgress {
  level: number;
  current: number;
  required: number;
  percent: number;
  totalExperience: number;
  atMaxLevel: boolean;
}

export interface ExperienceGainResult {
  save: GameSave;
  rawAmount: number;
  finalAmount: number;
  levelsGained: number;
  levelBefore: number;
  levelAfter: number;
  message: string;
}

export function getNextLevelExperience(level: number): number {
  if (level >= MAX_PLAYER_LEVEL) return Number.POSITIVE_INFINITY;
  const safeLevel = Math.max(1, Math.floor(level));
  const stageMultiplier = 1 + Math.floor(safeLevel / 1000) * 0.35;
  return Math.floor((35 + 15 * safeLevel ** 1.25 + 2 * safeLevel ** 2) * stageMultiplier);
}

function getExperienceMultiplier(playerLevel: number, source?: ExperienceSource): number {
  if (source?.kind !== 'monster' || typeof source.level !== 'number') return 1;
  const levelDiff = playerLevel - source.level;
  if (levelDiff > 20) return 0.05;
  if (levelDiff >= 11) return 0.2;
  if (levelDiff >= 6) return 0.6;
  const overLevelDiff = source.level - playerLevel;
  if (overLevelDiff >= 6) return 1.4;
  if (overLevelDiff >= 3) return 1.2;
  return 1;
}

export function getLevelProgress(save: GameSave): LevelProgress | null {
  const player = save.playerState;
  if (!player) return null;
  const required = getNextLevelExperience(player.level);
  const atMaxLevel = player.level >= MAX_PLAYER_LEVEL;
  return {
    level: player.level,
    current: atMaxLevel ? 0 : player.experience,
    required: atMaxLevel ? 0 : required,
    percent: atMaxLevel ? 100 : Math.min(100, Number(((player.experience / required) * 100).toFixed(2))),
    totalExperience: player.totalExperience,
    atMaxLevel,
  };
}

export function canLevelUp(player: PlayerState): boolean {
  return player.level < MAX_PLAYER_LEVEL && player.experience >= getNextLevelExperience(player.level);
}

function addAttributes(left: PlayerAttributeBlock, right: Partial<PlayerAttributeBlock>): PlayerAttributeBlock {
  const next = { ...left };
  Object.entries(right).forEach(([key, value]) => {
    const attributeKey = key as keyof PlayerAttributeBlock;
    next[attributeKey] += value || 0;
  });
  return next;
}

function addLevelGrowth(player: PlayerState): PlayerState {
  const growth = getLevelGrowthForProfession(player.professions.active);
  const levelGrowth = addAttributes(addAttributes(player.levelGrowth, growth.primary), growth.secondary);
  const gainedProfessionPoint = (player.level + 1) % 5 === 0 ? 1 : 0;
  return {
    ...player,
    level: player.level + 1,
    levelGrowth,
    vitalGrowth: {
      hp: player.vitalGrowth.hp + growth.hp,
      mp: player.vitalGrowth.mp + growth.mp,
    },
    unspentAttributePoints: player.unspentAttributePoints + 1,
    unspentProfessionPoints: player.unspentProfessionPoints + gainedProfessionPoint,
  };
}

export function applyLevelUps(save: GameSave): ExperienceGainResult {
  const nextSave = ensurePlayerState(save);
  let player = nextSave.playerState!;
  const levelBefore = player.level;
  let levelsGained = 0;

  while (canLevelUp(player)) {
    player = {
      ...player,
      experience: player.experience - getNextLevelExperience(player.level),
    };
    player = addLevelGrowth(player);
    levelsGained += 1;
  }

  const leveledSave: GameSave = {
    ...nextSave,
    playerState: {
      ...player,
      lastLevelUpSummary:
        levelsGained > 0
          ? `等级 ${levelBefore} -> ${player.level}，获得 ${levelsGained} 点自由属性点。`
          : nextSave.playerState?.lastLevelUpSummary,
    },
  };
  const restored = levelsGained > 0 ? restorePlayerVitals(leveledSave) : leveledSave;

  return {
    save: restored,
    rawAmount: 0,
    finalAmount: 0,
    levelsGained,
    levelBefore,
    levelAfter: restored.playerState?.level || levelBefore,
    message: levelsGained > 0 ? `升级到 Lv.${restored.playerState?.level}` : '经验已结算。',
  };
}

export function addExperience(save: GameSave, amount: number, source?: ExperienceSource): ExperienceGainResult {
  const nextSave = ensurePlayerState(save);
  const player = nextSave.playerState!;
  if (player.level >= MAX_PLAYER_LEVEL) {
    return {
      save: nextSave,
      rawAmount: amount,
      finalAmount: 0,
      levelsGained: 0,
      levelBefore: player.level,
      levelAfter: player.level,
      message: '已经达到等级上限。',
    };
  }

  const rawAmount = Math.max(0, Math.floor(amount));
  const finalAmount = Math.floor(rawAmount * getExperienceMultiplier(player.level, source));
  const levelBefore = player.level;
  const withExperience: GameSave = {
    ...nextSave,
    playerState: {
      ...player,
      experience: player.experience + finalAmount,
      totalExperience: player.totalExperience + finalAmount,
    },
  };
  const leveled = applyLevelUps(withExperience);
  const afterPlayer = leveled.save.playerState!;
  const log: PlayerExperienceLogEntry = {
    id: createId('exp'),
    amount: finalAmount,
    sourceKind: source?.kind || 'system',
    sourceId: source?.id,
    label: source?.label || '未命名经验来源',
    levelBefore,
    levelAfter: afterPlayer.level,
    createdAtIso: nowIso(),
  };
  const saveWithLog: GameSave = {
    ...leveled.save,
    playerState: {
      ...afterPlayer,
      experienceLog: [log, ...afterPlayer.experienceLog].slice(0, 20),
    },
  };
  const stats = getPlayerStats(saveWithLog);
  const message =
    leveled.levelsGained > 0
      ? `获得 ${finalAmount} 经验，升到 Lv.${afterPlayer.level}。`
      : `获得 ${finalAmount} 经验。距离下一级还需要 ${Math.max(0, (stats ? getNextLevelExperience(afterPlayer.level) : 0) - afterPlayer.experience)} 经验。`;

  return {
    save: saveWithLog,
    rawAmount,
    finalAmount,
    levelsGained: leveled.levelsGained,
    levelBefore,
    levelAfter: afterPlayer.level,
    message,
  };
}

export function getExperienceRewardPreview(amount: number, playerLevel: number, source?: ExperienceSource): number {
  return Math.floor(Math.max(0, amount) * getExperienceMultiplier(playerLevel, source));
}

export function createEmptyLevelGrowth(): PlayerAttributeBlock {
  return createEmptyAttributeBlock();
}
