import {
  DEFAULT_API_PROFILE_ID,
  type ApiProfile,
  type ApiProfileState,
  type ApiTaskKind,
} from './types';

const API_TASKS: ApiTaskKind[] = [
  'opening',
  'main_narration',
  'story_summary',
  'npc_generation',
  'scene_expansion',
  'combat_transcript',
  'companion_intent',
  'laimu_decision',
  'achievement_generation',
  'worldbook_organize',
];

const PRESET_REQUIRED_TASKS = new Set<ApiTaskKind>(['opening', 'main_narration', 'story_summary', 'combat_transcript']);
const RAW_ONLY_TASKS = new Set<ApiTaskKind>([
  'npc_generation',
  'scene_expansion',
  'companion_intent',
  'laimu_decision',
  'achievement_generation',
  'worldbook_organize',
]);

export function createDefaultApiState(nowIso: string): ApiProfileState {
  const defaultProfile: ApiProfile = {
    id: DEFAULT_API_PROFILE_ID,
    name: '随酒馆当前接口',
    mode: 'tavern_default',
    method: 'generate',
    modelOptions: [],
    createdAtIso: nowIso,
    updatedAtIso: nowIso,
  };

  return {
    profiles: [defaultProfile],
    taskRoutes: Object.fromEntries(API_TASKS.map(task => [task, DEFAULT_API_PROFILE_ID])) as Record<ApiTaskKind, string>,
    presetOptions: [],
  };
}

function createApiId(): string {
  const randomId =
    typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
      ? crypto.randomUUID()
      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  return `api-${randomId}`;
}

export function ensureApiState(api: ApiProfileState, nowIso: string): ApiProfileState {
  if (api.profiles.some(profile => profile.id === DEFAULT_API_PROFILE_ID)) return api;
  const fallback = createDefaultApiState(nowIso).profiles[0];
  return {
    ...api,
    profiles: [fallback, ...api.profiles],
    taskRoutes: {
      ...createDefaultApiState(nowIso).taskRoutes,
      ...api.taskRoutes,
    },
  };
}

export function createCustomApiProfile(nowIso: string): ApiProfile {
  return {
    id: createApiId(),
    name: '新的自定义接口',
    mode: 'custom',
    method: 'generate',
    customApi: {
      apiurl: '',
      key: '',
      source: 'openai',
      model: undefined,
      max_tokens: 'same_as_preset',
      temperature: 'same_as_preset',
    },
    modelOptions: [],
    createdAtIso: nowIso,
    updatedAtIso: nowIso,
  };
}

export function cloneProfileFromCurrentTavern(api: ApiProfileState, nowIso: string): ApiProfileState {
  let loadedPresetName: string | undefined;
  try {
    loadedPresetName = typeof getLoadedPresetName === 'function' ? getLoadedPresetName() : undefined;
  } catch {
    loadedPresetName = undefined;
  }

  return updateApiProfile(
    api,
    {
      id: createApiId(),
      name: loadedPresetName ? `酒馆当前预设: ${loadedPresetName}` : '酒馆当前预设副本',
      mode: 'tavern_default',
      method: 'generate',
      presetName: loadedPresetName,
      modelOptions: [],
      createdAtIso: nowIso,
      updatedAtIso: nowIso,
    },
    nowIso,
  );
}

export function updateApiProfile(api: ApiProfileState, profile: ApiProfile, nowIso: string): ApiProfileState {
  const nextProfile = { ...profile, updatedAtIso: nowIso };
  const exists = api.profiles.some(item => item.id === nextProfile.id);
  return {
    ...api,
    profiles: exists ? api.profiles.map(item => (item.id === nextProfile.id ? nextProfile : item)) : [...api.profiles, nextProfile],
  };
}

export function deleteApiProfile(api: ApiProfileState, profileId: string): ApiProfileState {
  if (profileId === DEFAULT_API_PROFILE_ID) return api;
  return {
    ...api,
    profiles: api.profiles.filter(profile => profile.id !== profileId),
    taskRoutes: Object.fromEntries(
      API_TASKS.map(task => [task, api.taskRoutes[task] === profileId ? DEFAULT_API_PROFILE_ID : api.taskRoutes[task] || DEFAULT_API_PROFILE_ID]),
    ) as Record<ApiTaskKind, string>,
  };
}

export function selectApiProfileForTask(api: ApiProfileState, taskKind: ApiTaskKind, profileId: string): ApiProfileState {
  const safeProfileId = api.profiles.some(profile => profile.id === profileId) ? profileId : DEFAULT_API_PROFILE_ID;
  return {
    ...api,
    taskRoutes: {
      ...api.taskRoutes,
      [taskKind]: safeProfileId,
    },
  };
}

export function refreshPresetOptions(api: ApiProfileState, nowIso: string): ApiProfileState {
  try {
    return {
      ...api,
      presetOptions: typeof getPresetNames === 'function' ? getPresetNames() : [],
      loadedPresetName: typeof getLoadedPresetName === 'function' ? getLoadedPresetName() : undefined,
      lastPresetRefreshIso: nowIso,
      lastError: undefined,
    };
  } catch (error) {
    return {
      ...api,
      lastError: error instanceof Error ? error.message : String(error),
    };
  }
}

export async function refreshModelOptions(api: ApiProfileState, profileId: string, nowIso: string): Promise<ApiProfileState> {
  const profile = api.profiles.find(item => item.id === profileId);
  if (!profile || profile.mode !== 'custom' || !profile.customApi?.apiurl) return api;

  try {
    const modelOptions = await getModelList({
      apiurl: profile.customApi.apiurl,
      key: profile.customApi.key || undefined,
    });
    return updateApiProfile(
      {
        ...api,
        lastModelRefreshIso: nowIso,
        lastError: undefined,
      },
      {
        ...profile,
        modelOptions,
        customApi: {
          ...profile.customApi,
          model: profile.customApi.model && modelOptions.includes(profile.customApi.model) ? profile.customApi.model : modelOptions[0],
        },
      },
      nowIso,
    );
  } catch (error) {
    return {
      ...api,
      lastError: error instanceof Error ? error.message : String(error),
    };
  }
}

export interface GenerateWithProfileRequest {
  userInput?: string;
  systemPrompt?: string;
  historyPrompts?: { role: 'system' | 'assistant' | 'user'; content: string }[];
  worldbookScanText?: string;
  maxChatHistory?: 'all' | number;
}

export async function generateWithProfile(
  api: ApiProfileState,
  taskKind: ApiTaskKind,
  request: GenerateWithProfileRequest,
): Promise<string> {
  const profileId = api.taskRoutes[taskKind] || DEFAULT_API_PROFILE_ID;
  const profile = api.profiles.find(item => item.id === profileId) || api.profiles[0];
  const generationId =
    typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
      ? `gen-${taskKind}-${crypto.randomUUID()}`
      : `gen-${taskKind}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  const rolePrompt = request.systemPrompt ? [{ role: 'system' as const, content: request.systemPrompt }] : [];
  const historyPrompts = request.historyPrompts;
  const baseConfig = {
    generation_id: generationId,
    user_input: request.userInput,
    should_stream: false,
    should_silence: false,
    max_chat_history: request.maxChatHistory ?? 0,
  };

  const custom_api =
    profile.mode === 'custom' && profile.customApi?.apiurl && profile.customApi.model
      ? {
          apiurl: profile.customApi.apiurl,
          key: profile.customApi.key || undefined,
          model: profile.customApi.model,
          source: profile.customApi.source || 'openai',
          max_tokens: profile.customApi.max_tokens,
          temperature: profile.customApi.temperature,
          frequency_penalty: profile.customApi.frequency_penalty,
          presence_penalty: profile.customApi.presence_penalty,
          top_p: profile.customApi.top_p,
          top_k: profile.customApi.top_k,
        }
      : undefined;

  const shouldUsePreset = PRESET_REQUIRED_TASKS.has(taskKind) || (profile.method === 'generate' && !RAW_ONLY_TASKS.has(taskKind));

  if (shouldUsePreset) {
    const injects: Omit<InjectionPrompt, 'id'>[] = [];
    if (request.systemPrompt) {
      injects.push({ role: 'system', content: request.systemPrompt, position: 'in_chat', depth: 0, should_scan: false });
    }
    if (request.worldbookScanText) {
      injects.push({ role: 'system', content: request.worldbookScanText, position: 'none', depth: 0, should_scan: true });
    }
    return generate({
      ...baseConfig,
      custom_api,
      injects: injects.length ? injects : undefined,
      overrides: historyPrompts
        ? {
            chat_history: {
              with_depth_entries: true,
              prompts: historyPrompts,
            },
          }
        : undefined,
    });
  }

  return generateRaw({
    ...baseConfig,
    custom_api,
    ordered_prompts: [...rolePrompt, ...(historyPrompts || []), 'user_input'],
    injects: request.worldbookScanText
      ? [{ role: 'system', content: request.worldbookScanText, position: 'none', depth: 0, should_scan: true }]
      : undefined,
  });
}

export async function testApiProfile(api: ApiProfileState, profileId: string, nowIso: string): Promise<ApiProfileState> {
  const profile = api.profiles.find(item => item.id === profileId);
  if (!profile) return api;

  try {
    const text = await generateWithProfile(
      {
        ...api,
        taskRoutes: { ...api.taskRoutes, worldbook_organize: profileId },
      },
      'worldbook_organize',
      {
        systemPrompt: '请只回复“8bit API OK”。',
        userInput: '测试接口是否可用。',
        maxChatHistory: 0,
      },
    );
    return updateApiProfile(api, { ...profile, lastTestResult: text.trim().slice(0, 120) }, nowIso);
  } catch (error) {
    return updateApiProfile(api, { ...profile, lastTestResult: error instanceof Error ? error.message : String(error) }, nowIso);
  }
}
