CE,mBAAoB,CACpB,yBAA0B,CAC1B,eAAgB,CAChB,kBACF,CAEA,4CACE,yBAA0B,CAC1B,eACF,CAEA,wCACE,WAAY,CACZ,eAAgB,CAChB,oBAAqB,CACrB,yBAA0B,CAC1B,iBAAkB,CAClB,sBAAuB,CACvB,kBACF,CAEA,iEAEE,YAAa,CACb,cAAe,CACf,OACF,CAEA,uEAEE,eAAgB,CAChB,gBAAiB,CACjB,iCAAqC,CACrC,UAAW,CACX,wBAAyB,CACzB,eAAgB,CAChB,kBAAmB,CACnB,4DACF,CAEA,oCACE,MAAO,CACP,eACF,CAEA,qHAEE,wBACF,CAEA,2FAEE,UAAW,CACX,yBACF,CAEA,6BACE,iBAAkB,CAClB,MAAO,CACP,OAAQ,CACR,8BAAiC,CACjC,iCAAoC,CACpC,eAAgB,CAChB,gCAAmC,CACnC,2BAA+B,CAC/B,yBACF,CAEA,+BACE,YACF,CAEA,oCAAqB,oBAAuB,CAC5C,mCAAoB,kBAAqB,CACzC,sCAAuB,oBAAuB,CAC9C,sCAAuB,UAAa,CAEpC,oCACE,WAAY,CACZ,YAAa,CACb,kBAAmB,CACnB,oBAAqB,CACrB,QAAS,CACT,iBAAkB,CAClB,YACF,CAEA,2CACE,yBACF,CAEA,sCACE,oBAAqB,CACrB,wBAAyB,CACzB,eACF,CAEA,iCACE,qBAAuB,CACvB,WAAY,CACZ,kDACF,CAEA,wCACE,KAAO,uBAA0B,CACjC,GAAK,4BAA+B,CACtC,CAEA,iCACE,QAAW,uBAA0B,CACrC,IAAM,0BAA6B,CACrC,CAEA,mCACE,QAAW,uBAA0B,CACrC,IAAM,0BAA6B,CACrC,CAEA,yBACE,gCACE,sBAAuB,CACvB,OACF,CAEA,+BACE,yBAA0B,CAC1B,oBAAqB,CACrB,iBAAkB,CAClB,oBAAqB,CACrB,eACF,CAEA,8BACE,sBAAuB,CACvB,cACF,CAEA,uCACE,eACF,CAEA,kCACE,iBAAkB,CAClB,QAAS,CACT,SAAU,CACV,UAAW,CACX,mBACF,CACF","sourcesContent":["<script setup lang=\"ts\">\nimport { SKILL_DEFINITIONS } from '../../core/skills';\nimport { useGameStore, type SkillId } from '../../stores/gameStore';\nimport type { CombatActorState } from '../../core/types';\nimport { backgrounds, monsters as monsterSprites, fx, ui as uiAssets } from '../../assets';\nimport { getChibiCharacterPortrait, getPlayerChibiPortrait } from '../../visualAssets';\n\nconst game = useGameStore();\nconst selectedTargetId = ref('');\nconst selectedAllyTargetId = ref('player');\nconst battleSpeed = ref<1 | 2 | 4>(1);\n\ntype CombatEffectKind = 'slash' | 'magic' | 'heal';\n\nconst effectUrls: Record<CombatEffectKind, string> = {\n  slash: fx.slash,\n  magic: fx.magic,\n  heal: fx.heal,\n};\n\nconst speedOptions: (1 | 2 | 4)[] = [1, 2, 4];\nconst activeEffect = ref<{ key: number; kind: CombatEffectKind; actorId?: string; targetId?: string } | null>(null);\nlet effectTimer: ReturnType<typeof window.setTimeout> | null = null;\n\nconst combat = computed(() => game.combat);\nconst party = computed(() => combat.value?.actors.filter(actor => actor.side === 'party') || []);\nconst enemies = computed(() => combat.value?.actors.filter(actor => actor.side === 'enemy') || []);\nconst livingParty = computed(() => party.value.filter(actor => actor.alive && actor.currentHp > 0));\nconst livingEnemies = computed(() => enemies.value.filter(actor => actor.alive && actor.currentHp > 0));\nconst pendingActor = computed(() => combat.value?.actors.find(actor => actor.id === combat.value?.pendingActorId) || null);\nconst canAct = computed(() => Boolean(combat.value?.active && combat.value.phase === 'awaiting_player' && pendingActor.value?.side === 'party'));\nconst activeActorName = computed(() => pendingActor.value?.name || '等待速度条');\nconst battleBg = computed(() => {\n  const locationId = combat.value?.locationId || game.currentLocation?.id || '';\n  return locationId.includes('cave') ? backgrounds.battleCave : backgrounds.battleField;\n});\nconst actionSkills = computed(() => {\n  const ids = pendingActor.value?.skillIds || [];\n  return ids\n    .map(skillId => SKILL_DEFINITIONS.find(skill => skill.id === skillId))\n    .filter((skill): skill is (typeof SKILL_DEFINITIONS)[number] => Boolean(skill));\n});\nconst timelineActors = computed(() =>\n  [...party.value, ...enemies.value]\n    .filter(actor => actor.alive)\n    .sort((left, right) => right.gauge - left.gauge || right.speed - left.speed),\n);\n\nwatch(\n  livingParty,\n  partyNow => {\n    if (!partyNow.length) {\n      selectedAllyTargetId.value = '';\n      return;\n    }\n    if (!partyNow.some(actor => actor.id === selectedAllyTargetId.value)) {\n      selectedAllyTargetId.value = partyNow.find(actor => actor.id === 'player')?.id || partyNow[0].id;\n    }\n  },\n  { immediate: true },\n);\n\nwatch(\n  livingEnemies,\n  enemiesNow => {\n    if (!enemiesNow.length) {\n      selectedTargetId.value = '';\n      return;\n    }\n    if (!enemiesNow.some(enemy => enemy.id === selectedTargetId.value)) selectedTargetId.value = enemiesNow[0].id;\n  },\n  { immediate: true },\n);\n\nfunction hpPercent(current: number, max: number) {\n  if (!max) return 0;\n  return Math.max(0, Math.min(100, (current / max) * 100));\n}\n\nfunction gaugePercent(gauge: number) {\n  return Math.max(0, Math.min(100, (gauge / 10000) * 100));\n}\n\nfunction actorPortrait(actor: CombatActorState): string | undefined {\n  if (actor.id === 'player') return getPlayerChibiPortrait(game.creation.gender);\n  if (actor.side === 'party') return getChibiCharacterPortrait(actor.id);\n  if (actor.monsterId) return monsterSprites[actor.monsterId];\n  return undefined;\n}\n\nfunction playCombatEffect(kind: CombatEffectKind, actorId?: string, targetId?: string) {\n  const key = Date.now();\n  if (effectTimer) window.clearTimeout(effectTimer);\n  activeEffect.value = { key, kind, actorId, targetId };\n  effectTimer = window.setTimeout(() => {\n    if (activeEffect.value?.key === key) activeEffect.value = null;\n  }, Math.max(220, 620 / battleSpeed.value));\n}\n\nfunction findSkill(skillId: SkillId) {\n  return SKILL_DEFINITIONS.find(item => item.id === skillId);\n}\n\nfunction effectForSkill(skillId: SkillId): CombatEffectKind | null {\n  const skill = findSkill(skillId);\n  if (!skill) return 'slash';\n  if (['cleric_heal', 'cleric_purify', 'companion_small_heal', 'companion_supply_patch'].includes(skill.id)) return 'heal';\n  if (['mage_spark', 'mage_focus', 'companion_focus_bolt', 'companion_echo_pulse'].includes(skill.id)) return 'magic';\n  if (['hero_strike', 'warrior_break', 'thief_quick_stab', 'thief_mark', 'companion_power_strike', 'companion_quick_cut', 'companion_weaken', 'companion_guard_call'].includes(skill.id)) return 'slash';\n  if (skill.tags.some(tag => ['治疗', '净化'].includes(tag))) return 'heal';\n  if (skill.tags.some(tag => ['魔法', '火', '法师勇者'].includes(tag))) return 'magic';\n  if (skill.tags.some(tag => ['物理', '破防', '快速行动', '战士勇者', '盗贼勇者'].includes(tag))) return 'slash';\n  return null;\n}\n\nfunction skillTargetsAlly(skillId: SkillId): boolean {\n  const skill = findSkill(skillId);\n  if (!skill) return false;\n  return skill.tags.some(tag => ['治疗', '净化', '防御', '护卫', '蓄力'].includes(tag));\n}\n\nfunction selectedTargetForSkill(skillId: SkillId): string {\n  return skillTargetsAlly(skillId) ? selectedAllyTargetId.value || pendingActor.value?.id || '' : selectedTargetId.value;\n}\n\nfunction shouldShowEffect(actorId: string): boolean {\n  if (!activeEffect.value) return false;\n  return (activeEffect.value.targetId || activeEffect.value.actorId) === actorId;\n}\n\nasync function submitAttack() {\n  if (!selectedTargetId.value || !pendingActor.value) return;\n  playCombatEffect('slash', pendingActor.value.id, selectedTargetId.value);\n  await game.submitCombatCommand({ kind: 'attack', actorId: pendingActor.value.id, targetId: selectedTargetId.value });\n}\n\nasync function submitGuard() {\n  if (!pendingActor.value) return;\n  await game.submitCombatCommand({ kind: 'guard', actorId: pendingActor.value.id });\n}\n\nasync function submitEscape() {\n  if (!pendingActor.value) return;\n  await game.submitCombatCommand({ kind: 'escape', actorId: pendingActor.value.id });\n}\n\nasync function submitSkill(skillId: SkillId) {\n  if (!pendingActor.value) return;\n  const targetId = selectedTargetForSkill(skillId);\n  if (!targetId) return;\n  const effect = effectForSkill(skillId);\n  if (effect) playCombatEffect(effect, pendingActor.value.id, targetId);\n  await game.submitCombatCommand({ kind: 'skill', actorId: pendingActor.value.id, skillId, targetId });\n}\n</script>\n\n<template>\n  <section\n    class=\"combat-screen\"\n    aria-label=\"战斗\"\n    :style=\"{\n      '--battle-bar-duration': `${420 / battleSpeed}ms`,\n      '--battle-idle-duration': `${1700 / battleSpeed}ms`,\n      '--battle-effect-duration': `${520 / battleSpeed}ms`,\n    }\"\n  >\n    <div class=\"battle-bg\" :style=\"{ backgroundImage: `url(${battleBg})` }\"></div>\n    <div class=\"battle-vignette\"></div>\n\n    <header class=\"battle-header\">\n      <div>\n        <span>战斗</span>\n        <strong>{{ combat?.active ? '速度条遭遇战' : '遭遇战' }}</strong>\n      </div>\n      <div class=\"battle-header-actions\">\n        <div class=\"battle-speed-group\" aria-label=\"战斗速度\">\n          <button\n            v-for=\"speed in speedOptions\"\n            :key=\"speed\"\n            type=\"button\"\n            :class=\"{ active: battleSpeed === speed }\"\n            @click=\"battleSpeed = speed\"\n          >\n            {{ speed }}倍\n          </button>\n        </div>\n        <button class=\"action-btn primary\" :disabled=\"game.isBusy || !game.canStartEncounter\" @click=\"game.startEncounter\">\n          遭遇\n        </button>\n      </div>\n    </header>\n\n    <template v-if=\"combat?.active\">\n      <div class=\"battle-timeline\">\n        <div\n          v-for=\"actor in timelineActors\"\n          :key=\"actor.id\"\n          class=\"timeline-row\"\n          :class=\"{ active: actor.id === combat.pendingActorId, enemy: actor.side === 'enemy' }\"\n        >\n          <span>{{ actor.name }}</span>\n          <i><b :style=\"{ width: gaugePercent(actor.gauge) + '%' }\"></b></i>\n        </div>\n      </div>\n\n      <div class=\"battle-field\">\n        <div class=\"battle-side party-side\">\n          <button\n            v-for=\"actor in party\"\n            :key=\"actor.id\"\n            type=\"button\"\n            class=\"battle-actor party-actor\"\n            :class=\"{ active: actor.id === combat.pendingActorId, selectedAlly: selectedAllyTargetId === actor.id, defeated: !actor.alive }\"\n            :disabled=\"!actor.alive\"\n            @click=\"actor.alive && (selectedAllyTargetId = actor.id)\"\n          >\n            <div class=\"actor-sprite-wrap\">\n              <img v-if=\"ac