const INITIAL_UNLOCKED_LOCATION_IDS = ['reality_origin', 'initial_grassland', 'aruma_village', 'aruma_church', 'northern_path'];

export function parseMiniMapGrid(rawGrid: string, source: MiniMapGridSource = 'manual'): MiniMapGrid {
  const rows = rawGrid
    .split(/\r?\n/)
    .map(row => row.trim())
    .filter(Boolean);
  if (!rows.length) throw Error('地图网格不能为空。');
  const width = rows[0].length;
  if (width < 2) throw Error('地图网格宽度太小。');
  if (!rows.every(row => row.length === width)) throw Error('地图网格必须每一行等宽。');
  const allowedCodes = new Set(Object.keys(TILE_DEFINITIONS));
  const illegal = rows.join('').split('').find(code => !allowedCodes.has(code));
  if (illegal) throw Error(`地图网格存在未知地块: ${illegal}`);
  return {
    rows,
    width,
    height: rows.length,
    source,
    updatedAtIso: nowIso(),
  };
}

export function getLocationDefinition(locationId: string): LocationDefinition | undefined {
  return LOCATION_DEFINITIONS.find(location => location.id === locationId);
}

export function createInitialMapState(): MapState {
  return {
    currentLocationId: 'reality_origin',
    unlockedLocationIds: INITIAL_UNLOCKED_LOCATION_IDS,
    visitedLocationIds: ['reality_origin'],
    gridOverrides: {},
  };
}

export function normalizeMapState(raw: unknown): MapState {
  const fallback = createInitialMapState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<MapState>;
  return {
    currentLocationId: candidate.currentLocationId || fallback.currentLocationId,
    unlockedLocationIds: Array.from(new Set([...(candidate.unlockedLocationIds || fallback.unlockedLocationIds)])),
    visitedLocationIds: Array.from(new Set([...(candidate.visitedLocationIds || fallback.visitedLocationIds)])),
    gridOverrides: candidate.gridOverrides || {},
    lastImport: candidate.lastImport,
  };
}

export function getCurrentLocation(save: GameSave): LocationDefinition {
  return getLocationDefinition(save.map.currentLocationId) || LOCATION_DEFINITIONS[0];
}

export function getLocationMiniMap(save: GameSave, locationId = save.map.currentLocationId): MiniMapGrid {
  const override = save.map.gridOverrides[locationId];
  if (override) return override;
  const location = getLocationDefinition(locationId) || LOCATION_DEFINITIONS[0];
  return parseMiniMapGrid(location.defaultGrid, 'static');
}

export function getAvailableTravelTargets(save: GameSave): LocationDefinition[] {
  const current = getCurrentLocation(save);
  return current.connections
    .filter(locationId => save.map.unlockedLocationIds.includes(locationId))
    .map(locationId => getLocationDefinition(locationId))
    .filter((location): location is LocationDefinition => Boolean(location));
}

export function unlockLocation(save: GameSave, locationId: string): GameSave {
  if (!getLocationDefinition(locationId)) throw Error('未知地点。');
  if (save.map.unlockedLocationIds.includes(locationId)) return save;
  return {
    ...save,
    map: {
      ...save.map,
      unlockedLocationIds: [...save.map.unlockedLocationIds, locationId],
    },
  };
}

export function travelToLocation(save: GameSave, locationId: string): GameSave {
  const current = getCurrentLocation(save);
  const target = getLocationDefinition(locationId);
  if (!target) throw Error('未知地点。');
  if (!save.map.unlockedLocationIds.includes(locationId)) throw Error('地点尚未解锁。');
  if (!current.connections.includes(locationId)) throw Error('当前地点无法直接到达目标地点。');
  return {
    ...save,
    map: {
      ...save.map,
      currentLocationId: locationId,
      visitedLocationIds: Array.from(new Set([...save.map.visitedLocationIds, locationId])),
    },
  };
}

export function getMapHint(save: GameSave): string {
  return getCurrentLocation(save).mapHint;
}

export function updateLocationMiniMapFromGrid(
  save: GameSave,
  locationId: string,
  rawGrid: string,
  source: MiniMapGridSource = 'api_generated',
): GameSave {
  if (!getLocationDefinition(locationId)) throw Error('未知地点。');
  const parsed = parseMiniMapGrid(rawGrid, source);
  return {
    ...save,
    map: {
      ...save.map,
      gridOverrides: {
        ...save.map.gridOverrides,
        [locationId]: parsed,
      },
      lastImport: {
        locationId,
        source,
        updatedAtIso: parsed.updatedAtIso,
      },
    },
  };
}

function extractMiniMapGrid(rawText: string, fallback: string): string {
  const mapBlock = rawText.match(/<map_grid\b[^>]*>([\s\S]*?)<\/map_grid>/i)?.[1];
  const contentBlock = rawText.match(/<content\b[^>]*>([\s\S]*?)<\/content>/i)?.[1];
  const source = (mapBlock || contentBlock || rawText)
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);
  const allowed = new Set(Object.keys(TILE_DEFINITIONS));
  const rows = source
    .map(line => line.replace(/`/g, '').replace(/\s+/g, ''))
    .filter(line => line.length >= 2 && line.split('').every(code => allowed.has(code)));
  if (!rows.length) return fallback;
  const width = rows[0].length;
  const sameWidthRows = rows.filter(row => row.length === width).slice(0, 10);
  return sameWidthRows.length >= 2 ? sameWidthRows.join('\n') : fallback;
}

