export async function generateLocationMiniMapFromApi(save: GameSave, locationId = save.map.currentLocationId): Promise<GameSave> {
  const location = getLocationDefinition(locationId);
  if (!location) throw Error('未知地点。');
  try {
    const rawText = await generateWithProfile(save.api, 'scene_expansion', {
      systemPrompt: buildMiniMapPrompt(save, location),
      userInput: `生成 ${location.name} 的可解析小地图字符网格。`,
      worldbookScanText: [
        '[8bit:runtime]',
        '[8bit:v1_0]',
        `[8bit:location:${location.id}]`,
        `v1_0_loc_${location.id}`,
        location.name,
        location.region,
      ].join('\n'),
      maxChatHistory: 0,
    });
    const rawGrid = extractMiniMapGrid(rawText, location.defaultGrid);
    return updateLocationMiniMapFromGrid(save, location.id, rawGrid, 'api_generated');
  } catch {
    return updateLocationMiniMapFromGrid(save, location.id, location.defaultGrid, 'static');
  }
}
