import type {
  AchievementCategory,
  AchievementDraft,
  AchievementRarity,
  AchievementRecord,
  AchievementState,
  GameSave,
} from './types';

export interface AchievementDefinition {
  id: string;
  title: string;
  description: string;
  category: AchievementCategory;
  rarity: AchievementRarity;
  hidden?: boolean;
  conditionText: string;
  isUnlocked(save: GameSave): boolean;
}

export interface AchievementView {
  id: string;
  title: string;
  description: string;
  category: AchievementCategory;
  rarity: AchievementRarity;
  hidden: boolean;
  conditionText: string;
  record?: AchievementRecord;
  unlocked: boolean;
}

