function safeCategory(value: string | undefined): AchievementCategory {
  return CATEGORY_VALUES.includes(value as AchievementCategory) ? (value as AchievementCategory) : 'story';
}

function safeRarity(value: string | undefined): AchievementRarity {
  return RARITY_VALUES.includes(value as AchievementRarity) ? (value as AchievementRarity) : 'bronze';
}

export function createInitialAchievementState(): AchievementState {
  return {
    unlocked: [],
    drafts: [],
  };
}

export function normalizeAchievementState(raw: unknown): AchievementState {
  if (!raw || typeof raw !== 'object') return createInitialAchievementState();
  const candidate = raw as Partial<AchievementState>;
  return {
    unlocked: (candidate.unlocked || []).map(record => ({
      id: record.id || createId('ach'),
      title: record.title || '未命名成就',
      description: record.description || '',
      category: safeCategory(record.category),
      rarity: safeRarity(record.rarity),
      source: record.source === 'ai' ? 'ai' : 'static',
      sourceId: record.sourceId,
      unlockedAtIso: record.unlockedAtIso || nowIso(),
    })),
    drafts: (candidate.drafts || []).map(draft => ({
      id: draft.id || createId('ach-draft'),
      title: draft.title || '未命名成就',
      description: draft.description || '',
      category: safeCategory(draft.category),
      rarity: safeRarity(draft.rarity),
      rawText: draft.rawText || '',
      situationSummary: draft.situationSummary || '',
      status: draft.status || 'pending',
      createdAtIso: draft.createdAtIso || nowIso(),
    })).slice(0, 20),
    lastGeneratedAtIso: candidate.lastGeneratedAtIso,
    lastError: candidate.lastError,
  };
}

function getUnlockedIds(save: GameSave): Set<string> {
  return new Set(save.achievements.unlocked.map(record => record.sourceId || record.id));
}

function createStaticRecord(definition: AchievementDefinition): AchievementRecord {
  return {
    id: createId('ach'),
    title: definition.title,
    description: definition.description,
    category: definition.category,
    rarity: definition.rarity,
    source: 'static',
    sourceId: definition.id,
    unlockedAtIso: nowIso(),
  };
}

export function syncStaticAchievements(save: GameSave): GameSave {
  const unlockedIds = getUnlockedIds(save);
  const newRecords = ACHIEVEMENT_DEFINITIONS
    .filter(definition => !unlockedIds.has(definition.id) && definition.isUnlocked(save))
    .map(createStaticRecord);
  if (!newRecords.length) return save;
  return {
    ...save,
    achievements: {
      ...save.achievements,
      unlocked: [...newRecords, ...save.achievements.unlocked],
    },
  };
}

export function getAchievementViews(save: GameSave): AchievementView[] {
  const recordBySourceId = new Map(save.achievements.unlocked.map(record => [record.sourceId || record.id, record]));
  return ACHIEVEMENT_DEFINITIONS.map(definition => {
    const record = recordBySourceId.get(definition.id);
    return {
      id: definition.id,
      title: record?.title || definition.title,
      description: record?.description || definition.description,
      category: definition.category,
      rarity: definition.rarity,
      hidden: Boolean(definition.hidden),
      conditionText: definition.conditionText,
      record,
      unlocked: Boolean(record),
    };
  });
}

export function getUnlockedAchievementRecords(save: GameSave): AchievementRecord[] {
  return [...save.achievements.unlocked].sort((a, b) => b.unlockedAtIso.localeCompare(a.unlockedAtIso));
}

function extractField(rawText: string, key: string): string | undefined {
  const pattern = new RegExp(`^\\s*${key}\\s*[:：]\\s*(.+)$`, 'im');
  return rawText.match(pattern)?.[1]?.trim();
}

export function parseAchievementDraft(rawText: string, situationSummary: string): AchievementDraft {
  const title = extractField(rawText, 'title') || extractField(rawText, '标题') || '未命名成就';
  const description = extractField(rawText, 'description') || extractField(rawText, '描述') || rawText.trim().slice(0, 160);
  const category = safeCategory((extractField(rawText, 'category') || extractField(rawText, '分类'))?.toLowerCase());
  const rarity = safeRarity((extractField(rawText, 'rarity') || extractField(rawText, '稀有度'))?.toLowerCase());
  return {
    id: createId('ach-draft'),
    title: title.slice(0, 40),
    description: description.slice(0, 180),
    category,
    rarity,
    rawText,
    situationSummary,
    status: 'pending',
    createdAtIso: nowIso(),
  };
}

export function buildAchievementPrompt(save: GameSave, situationSummary?: string): string {
  const summary = situationSummary || buildSituationSummary(save);
  const unlocked = getUnlockedAchievementRecords(save)
    .slice(0, 8)
    .map(record => `- ${record.title}: ${record.description}`)
    .join('\n');
  return [
    '你正在为互动游戏《8bit的幻想》生成一个成就草案。',
    '成就只是一段纪念性记录，不发放经验、金币、道具、职业点、地图解锁或任何数值奖励。',
    '不要伪造玩家没有完成的行为，不要把奖励写进成就，不要擅自补完莱姆详细人设、最终决战或大结局。',
    '如果当前局势不足以产生有意义成就，请生成一个低调的阶段性成就。',
    '输出格式必须固定为四行：',
    'title: 成就标题',
    'category: story/combat/exploration/collection/npc/system 之一',
    'rarity: bronze/silver/gold/secret 之一',
    'description: 80 字以内中文描述',
    '',
    '权威局势摘要：',
    summary,
    '',
    '已解锁成就：',
    unlocked || '- 无',
  ].join('\n');
}

export async function generateAchievementDraft(save: GameSave): Promise<GameSave> {
  const situationSummary = buildSituationSummary(save);
  const rawText = await generateWithProfile(save.api, 'achievement_generation', {
    systemPrompt: buildAchievementPrompt(save, situationSummary),
    userInput: '请根据当前局势生成一个成就草案。',
    maxChatHistory: 0,
  });
  const draft = parseAchievementDraft(rawText, situationSummary);
  return recordMessage(
    {
      ...save,
      achievements: {
        ...save.achievements,
        drafts: [draft, ...save.achievements.drafts].slice(0, 20),
        lastGeneratedAtIso: draft.createdAtIso,
        lastError: undefined,
      },
    },
    'assistant',
    rawText,
  );
}

export function confirmAchievementDraft(save: GameSave, draftId: string): GameSave {
  const draft = save.achievements.drafts.find(item => item.id === draftId);
  if (!draft || draft.status !== 'pending') return save;
  const record: AchievementRecord = {
    id: createId('ach'),
    title: draft.title,
    description: draft.description,
    category: draft.category,
    rarity: draft.rarity,
    source: 'ai',
    sourceId: draft.id,
    unlockedAtIso: nowIso(),
  };
  return {
    ...save,
    achievements: {
      ...save.achievements,
      unlocked: [record, ...save.achievements.unlocked],
      drafts: save.achievements.drafts.map(item => (item.id === draftId ? { ...item, status: 'accepted' } : item)),
    },
  };
}

export function rejectAchievementDraft(save: GameSave, draftId: string): GameSave {
  return {
    ...save,
    achievements: {
      ...save.achievements,
      drafts: save.achievements.drafts.map(item => (item.id === draftId ? { ...item, status: 'rejected' } : item)),
    },
  };
}
