import { PLAYER_GENDER_LABELS, type GameSave } from './types';
import { generateWithProfile } from './apiProfiles';
import { extractContentBlock } from './narration';
import { createId, nowIso, recordMessage } from './save';

export function buildOpeningPrompt(save: GameSave): string {
  const player = save.player;
  return [
    '你正在为互动游戏《8bit的幻想》生成开场白。',
    '玩家刚刚在前端创建了现实身份。请根据身份写出最合理的开场白：现实中的一天、意外捡到 8bit 风格手表、手表锁在右手腕、8bit 时代感音乐响起、穿越前的瞬间。',
    '气质：王道、热血、8bit 浪漫、成年人儿时的手柄与幻想被重新点亮。',
    '限制：不要写莱姆的详细人设，不要写最终决战，不要替玩家做长期选择，不要结算属性和战斗。',
    '称呼规则：开场白必须尊重玩家用户名与性别，避免把用户名写错、改名或替换成泛称。',
    '输出要求：中文，800 字以内；正文必须完整包在 <content></content> 内。标签外只允许末尾时间戳；前端只会读取 <content> 内的文字。',
    '末尾附一行时间戳，格式为 [TIME: reality +0m]。',
    '',
    '玩家现实身份：',
    `用户名：${player?.username || '{{user}}'}`,
    `性别：${player ? PLAYER_GENDER_LABELS[player.gender] : '未填写'}`,
    '详细人设：',
    player?.profileText || '',
  ].join('\n');
}

export async function generateOpeningFromProfile(save: GameSave): Promise<GameSave> {
  if (!save.player?.username.trim() || !save.player?.profileText.trim()) {
    return {
      ...save,
      opening: {
        ...save.opening,
        status: 'failed',
        error: '还没有完整创建现实身份。',
      },
    };
  }

  const generationId = createId('opening');
  const generatingSave: GameSave = {
    ...save,
    opening: {
      ...save.opening,
      status: 'generating',
      error: undefined,
      generationId,
    },
  };

  try {
    const rawText = await generateWithProfile(generatingSave.api, 'opening', {
      systemPrompt: buildOpeningPrompt(generatingSave),
      userInput: '请生成《8bit的幻想》的开场白。',
      maxChatHistory: 0,
    });
    const contentText = extractContentBlock(rawText);
    return recordMessage(
      {
        ...generatingSave,
        stage: 'opening_drafted',
        opening: {
          status: 'drafted',
          text: contentText,
          generatedAtIso: nowIso(),
          generationId,
        },
      },
      'assistant',
      contentText,
    );
  } catch (error) {
    return {
      ...generatingSave,
      opening: {
        ...generatingSave.opening,
        status: 'failed',
        error: error instanceof Error ? error.message : String(error),
      },
    };
  }
}
