interface FixedQuestInput {
  id: string;
  kind: Exclude<QuestKind, 'main'>;
  chapter: string;
  chapterId: string;
  name: string;
  summary: string;
  giver?: string;
  locationId?: string;
  hidden?: boolean;
  prerequisites?: string[];
  availability?: QuestAvailabilityCondition[];
  objectives: QuestObjectiveDefinition[];
  rewardCategoryIds: string[];
  poolRewardHint: string;
  completionFlagId: string;
  recommendedLevelBand?: string;
  requiredAnchorIds?: string[];
  aiSummary?: string;
}

function fixedQuest(input: FixedQuestInput): QuestDefinition {
  return {
    id: input.id,
    kind: input.kind,
    chapter: input.chapter,
    name: input.name,
    summary: input.summary,
    giver: input.giver,
    locationId: input.locationId,
    hidden: input.hidden,
    prerequisites: input.prerequisites,
    availability: input.availability,
    contentPackId: V1_0_CONTENT_PACK_ID,
    chapterId: input.chapterId,
    sourceFileId: 'v1_0_fixed_pack',
    recommendedLevelBand: input.recommendedLevelBand || '1-30',
    triggerPolicy: 'fixed_v1_0_package',
    requiredAnchorIds: input.requiredAnchorIds,
    completionFlagId: input.completionFlagId,
    syncStatus: 'implemented_v1_0',
    objectives: input.objectives,
    rewards: {
      rewardCategoryIds: input.rewardCategoryIds,
      poolRewardHint: input.poolRewardHint,
      flags: [input.completionFlagId],
    },
    aiSummary:
      input.aiSummary ||
      `${input.name} 是 v1.0 固定任务封包支线。你只能描写线索、对白和气氛，完成与奖励只以本轮已经确认的任务结果为准。`,
  };
}

