const QUEST_BY_ID = new Map(QUEST_DEFINITIONS.map(quest => [quest.id, quest]));

function nowIso(): string {
  return new Date().toISOString();
}

function createQuestLogId(): string {
  return `quest-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

function getItemCount(save: GameSave, itemId: string): number {
  return save.inventory.items.find(item => item.itemId === itemId)?.count || 0;
}

function isQuestCompleted(state: QuestState, questId: string): boolean {
  return state.records[questId]?.status === 'completed';
}

function createObjectiveState(objective: QuestObjectiveDefinition): QuestObjectiveState {
  return {
    objectiveId: objective.id,
    current: 0,
    required: Math.max(1, objective.count || 1),
    completed: false,
  };
}

function createQuestRecord(definition: QuestDefinition, status: QuestStatus): QuestRecord {
  const acceptedAtIso = status === 'active' ? nowIso() : undefined;
  return {
    questId: definition.id,
    status,
    objectiveStates: definition.objectives.map(createObjectiveState),
    acceptedAtIso,
  };
}

function normalizeQuestRecord(record: QuestRecord): QuestRecord | null {
  const definition = QUEST_BY_ID.get(record.questId);
  if (!definition) return null;
  const byId = new Map((record.objectiveStates || []).map(objective => [objective.objectiveId, objective]));
  return {
    questId: record.questId,
    status: record.status || 'available',
    objectiveStates: definition.objectives.map(objective => {
      const existing = byId.get(objective.id);
      const required = Math.max(1, objective.count || existing?.required || 1);
      const current = Math.max(0, Math.floor(existing?.current || 0));
      return {
        objectiveId: objective.id,
        current,
        required,
        completed: Boolean(existing?.completed) || current >= required,
      };
    }),
    acceptedAtIso: record.acceptedAtIso,
    completedAtIso: record.completedAtIso,
  };
}

export function createInitialQuestState(): QuestState {
  return {
    activeMainQuestId: 'mq_000_profile',
    records: {
      mq_000_profile: createQuestRecord(QUEST_BY_ID.get('mq_000_profile')!, 'active'),
    },
    flags: [],
    log: [],
  };
}

export function normalizeQuestState(raw: unknown): QuestState {
  const fallback = createInitialQuestState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<QuestState>;
  const records = Object.values(candidate.records || {}).reduce<Record<string, QuestRecord>>((result, record) => {
    const normalized = normalizeQuestRecord(record);
    if (normalized) result[normalized.questId] = normalized;
    return result;
  }, {});
  if (!Object.keys(records).length) records.mq_000_profile = createQuestRecord(QUEST_BY_ID.get('mq_000_profile')!, 'active');
  return {
    activeMainQuestId: candidate.activeMainQuestId || getCurrentMainQuestId({ ...fallback, records }),
    records,
    flags: Array.from(new Set(candidate.flags || [])),
    log: (candidate.log || []).slice(0, 30),
  };
}

export function getQuestDefinition(questId: string): QuestDefinition | undefined {
  return QUEST_BY_ID.get(questId);
}

function questAvailabilityMet(save: GameSave, state: QuestState, definition: QuestDefinition): boolean {
  if (definition.prerequisites?.some(questId => !isQuestCompleted(state, questId))) return false;
  if (!definition.availability?.length) return true;
  return definition.availability.every(condition => {
    if (condition.stage && save.stage !== condition.stage) return false;
    if (condition.visitedLocationId && !save.map.visitedLocationIds.includes(condition.visitedLocationId)) return false;
    if (condition.currentLocationId && save.map.currentLocationId !== condition.currentLocationId) return false;
    if (condition.itemId && getItemCount(save, condition.itemId) < Math.max(1, condition.itemCount || 1)) return false;
    if (condition.flag && !state.flags.includes(condition.flag)) return false;
    return true;
  });
}

function getCurrentMainQuestId(state: QuestState): string | undefined {
  return MAIN_QUEST_IDS.find(questId => {
    const record = state.records[questId];
    return record && record.status !== 'completed' && record.status !== 'failed';
  });
}

function addQuestLog(state: QuestState, questId: string, text: string): QuestState {
  return {
    ...state,
    log: [{ id: createQuestLogId(), questId, text, createdAtIso: nowIso() }, ...state.log].slice(0, 30),
  };
}

function refreshQuestAvailability(save: GameSave, state: QuestState): QuestState {
  let next = { ...state, records: { ...state.records } };
  QUEST_DEFINITIONS.forEach(definition => {
    if (next.records[definition.id]) return;
    if (!questAvailabilityMet(save, next, definition)) return;
    next.records[definition.id] = createQuestRecord(definition, definition.autoAccept ? 'active' : 'available');
  });
  next = refreshStaticObjectives(save, next);
  const activeMainQuestId = getCurrentMainQuestId(next);
  return {
    ...next,
    activeMainQuestId,
  };
}

function refreshRecordReady(record: QuestRecord): QuestRecord {
  if (record.status !== 'active') return record;
  const allCompleted = record.objectiveStates.every(objective => objective.completed);
  return allCompleted ? { ...record, status: 'ready' } : record;
}

function refreshStaticObjectives(save: GameSave, state: QuestState): QuestState {
  const records = { ...state.records };
  Object.values(records).forEach(record => {
    if (record.status !== 'active') return;
    const definition = QUEST_BY_ID.get(record.questId);
    if (!definition) return;
    const objectiveStates = record.objectiveStates.map(objectiveState => {
      const objective = definition.objectives.find(item => item.id === objectiveState.objectiveId);
      return objective ? progressObjective(save, objective, objectiveState, { kind: 'sync' }) : objectiveState;
    });
    records[record.questId] = refreshRecordReady({ ...record, objectiveStates });
  });
  return { ...state, records };
}

function completeObjective(objectiveState: QuestObjectiveState, amount = 1): QuestObjectiveState {
  const current = Math.min(objectiveState.required, objectiveState.current + amount);
  return {
    ...objectiveState,
    current,
    completed: current >= objectiveState.required,
  };
}

function progressObjective(
  save: GameSave,
  objective: QuestObjectiveDefinition,
  objectiveState: QuestObjectiveState,
  event: QuestEventInput,
): QuestObjectiveState {
  if (objectiveState.completed) return objectiveState;

  if (objective.kind === 'profile' && (event.kind === 'profile_created' || save.player)) return completeObjective(objectiveState);
  if (objective.kind === 'opening' && (event.kind === 'opening_generated' || save.opening.status === 'drafted')) return completeObjective(objectiveState);
  if (objective.kind === 'watch_lock' && (event.kind === 'watch_locked' || save.stage === 'eight_bit_ready')) return completeObjective(objectiveState);
  if (objective.kind === 'travel' && objective.targetId) {
    if (event.kind === 'travel' && event.locationId === objective.targetId) return completeObjective(objectiveState);
    if (save.map.visitedLocationIds.includes(objective.targetId)) return completeObjective(objectiveState);
  }
  if (objective.kind === 'combat' && event.kind === 'combat_victory') {
    const defeated = (event.monsterIds || []).filter(monsterId => !objective.targetId || objective.targetId === 'any' || monsterId === objective.targetId).length;
    if (defeated > 0) return completeObjective(objectiveState, defeated);
  }
  if (objective.kind === 'collect' && objective.targetId) {
    const current = Math.min(objectiveState.required, getItemCount(save, objective.targetId));
    return { ...objectiveState, current, completed: current >= objectiveState.required };
  }
  if (objective.kind === 'talk' && event.kind === 'talk' && event.npcId === objective.targetId) return completeObjective(objectiveState);
  if (objective.kind === 'anchor' && objective.targetId) {
    if (event.kind === 'anchor_set' && event.locationId === objective.targetId) return completeObjective(objectiveState);
    if (save.watch.anchorLocationId === objective.targetId) return completeObjective(objectiveState);
  }
  if (objective.kind === 'event' && event.kind === 'event' && event.targetId === objective.targetId) return completeObjective(objectiveState);

  return objectiveState;
}

export function refreshQuestState(save: GameSave): GameSave {
  const questSave = {
    ...save,
    quests: normalizeQuestState(save.quests),
  };
  return {
    ...questSave,
    quests: refreshQuestAvailability(questSave, questSave.quests),
  };
}

export function applyQuestEvent(save: GameSave, event: QuestEventInput): GameSave {
  const refreshed = refreshQuestState(save);
  const records = { ...refreshed.quests.records };
  Object.values(records).forEach(record => {
    if (record.status !== 'active') return;
    const definition = QUEST_BY_ID.get(record.questId);
    if (!definition) return;
    const objectiveStates = record.objectiveStates.map(objectiveState => {
      const objective = definition.objectives.find(item => item.id === objectiveState.objectiveId);
      return objective ? progressObjective(refreshed, objective, objectiveState, event) : objectiveState;
    });
    records[record.questId] = refreshRecordReady({ ...record, objectiveStates });
  });
  const nextSave = {
    ...refreshed,
    quests: {
      ...refreshed.quests,
      records,
    },
  };
  return refreshQuestState(nextSave);
}

export function acceptQuest(save: GameSave, questId: string): GameSave {
  const refreshed = refreshQuestState(save);
  const record = refreshed.quests.records[questId];
  if (!record || record.status !== 'available') throw Error('该任务当前不能接取。');
  const definition = QUEST_BY_ID.get(questId);
  if (!definition) throw Error('未知任务。');
  return refreshQuestState({
    ...refreshed,
    quests: addQuestLog(
      {
        ...refreshed.quests,
        records: {
          ...refreshed.quests.records,
          [questId]: {
            ...record,
            status: 'active',
            acceptedAtIso: nowIso(),
          },
        },
      },
      questId,
      `已接取任务：${definition.name}`,
    ),
  });
}

export function turnInQuest(save: GameSave, questId: string): { save: GameSave; definition: QuestDefinition } {
  const refreshed = refreshQuestState(save);
  const record = refreshed.quests.records[questId];
  const definition = QUEST_BY_ID.get(questId);
  if (!record || !definition) throw Error('未知任务。');
  if (record.status !== 'ready') throw Error('任务目标尚未完成。');
  const completedState = addQuestLog(
    {
      ...refreshed.quests,
      records: {
        ...refreshed.quests.records,
        [questId]: {
          ...record,
          status: 'completed',
          completedAtIso: nowIso(),
        },
      },
      flags: Array.from(new Set([...refreshed.quests.flags, ...(definition.rewards.flags || [])])),
    },
    questId,
    `已完成任务：${definition.name}`,
  );
  const completedSave = {
    ...refreshed,
    quests: completedState,
  };
  return {
    save: refreshQuestState(completedSave),
    definition,
  };
}

function formatRewardText(reward: QuestRewardDefinition): string {
  const parts: string[] = [];
  if (reward.rewardCategoryIds?.length) {
    parts.push(reward.rewardCategoryIds.map(id => REWARD_CATEGORY_LABELS[id] || id).join('、'));
  }
  if (reward.experience) parts.push(`${reward.experience} 经验`);
  if (reward.gold) parts.push(`${reward.gold} 金币`);
  if (reward.items?.length) parts.push(reward.items.map(item => `${item.name} x${item.count}`).join('、'));
  if (reward.professionPoints) {
    const points = Object.entries(reward.professionPoints)
      .filter(([, value]) => value)
      .map(([key, value]) => `${key}+${value}`)
      .join('、');
    if (points) parts.push(points);
  }
  if (reward.professionFlags?.length) parts.push('职业条件');
  if (reward.unlockLocationIds?.length) parts.push('解锁地点');
  if (reward.anchorLocationId) parts.push('设置复活锚点');
  return parts.join(' / ') || '剧情推进';
}

function createQuestView(definition: QuestDefinition, record: QuestRecord): QuestView {
  const completed = record.objectiveStates.filter(objective => objective.completed).length;
  return {
    definition,
    record,
    progressText: `${completed} / ${record.objectiveStates.length}`,
    rewardText: formatRewardText(definition.rewards),
    canAccept: record.status === 'available',
    canTurnIn: record.status === 'ready',
  };
}

export function getQuestViews(save: GameSave): QuestView[] {
  const refreshed = refreshQuestState(save);
  return QUEST_DEFINITIONS.flatMap(definition => {
    const record = refreshed.quests.records[definition.id];
    if (!record) return [];
    return [createQuestView(definition, record)];
  });
}

export function getActiveMainQuest(save: GameSave): QuestView | null {
  const refreshed = refreshQuestState(save);
  const questId = refreshed.quests.activeMainQuestId;
  if (!questId) return null;
  const definition = QUEST_BY_ID.get(questId);
  const record = refreshed.quests.records[questId];
  return definition && record ? createQuestView(definition, record) : null;
}

export function getQuestHint(save: GameSave): string {
  const main = getActiveMainQuest(save);
  if (!main) return '当前主线已经推进到第一版停靠点。';
  const nextObjective = main.record.objectiveStates.find(objective => !objective.completed);
  const definition = main.definition.objectives.find(objective => objective.id === nextObjective?.objectiveId);
  if (!definition) return main.canTurnIn ? `可以完成主线任务：${main.definition.name}` : main.definition.summary;
  return `${main.definition.name}: ${definition.label}`;
}
