`, "",{"version":3,"sources":["webpack://./src/8bit的幻想/脚本/控制台/components/hud/MiniMapCircle.vue"],"names":[],"mappings":"AA8HA,iCACE,iBAAkB,CAClB,4BAA+B,CAC/B,6BACF,CAEA,gCACE,iBAAkB,CAClB,QAAS,CACT,QAAS,CACT,0BAA2B,CAC3B,aAAc,CACd,eAAgB,CAChB,mBAAoB,CACpB,kBAAmB,CACnB,SACF,CAEA,8BACE,UAAW,CACX,WAAY,CACZ,iBAAkB,CAClB,eAAgB,CAChB,6CACF","sourcesContent":["<script setup lang=\"ts\">\n/**\n * P5 风格圆形小地图。\n * 优先显示当前地点的 MiniMapGrid；没有网格时才退回占位节点图。\n */\nimport { TILE_DEFINITIONS } from '../../core/map';\nimport { PLACEHOLDER_MINIMAP, type MiniMapData } from '../../core/placeholders';\nimport type { MapMarker, MapTileCode, MiniMapGrid } from '../../core/types';\n\nconst props = defineProps<{\n  data?: MiniMapData;\n  grid?: MiniMapGrid | null;\n  marker?: MapMarker;\n}>();\n\nconst mapData = computed(() => props.data || PLACEHOLDER_MINIMAP);\nconst gridCells = computed(() => {\n  if (!props.grid) return [];\n  return props.grid.rows.flatMap((row, y) =>\n    row.split('').map((code, x) => ({\n      code: code as MapTileCode,\n      x,\n      y,\n    })),\n  );\n});\nconst cellWidth = computed(() => (props.grid?.width ? 100 / props.grid.width : 10));\nconst cellHeight = computed(() => (props.grid?.height ? 100 / props.grid.height : 10));\nconst resolvedMarker = computed(() => {\n  const gridMarker = gridCells.value.find(cell => cell.code === '@');\n  if (gridMarker) return { x: gridMarker.x, y: gridMarker.y };\n  if (!props.marker || !props.grid) return props.marker;\n  return {\n    x: Math.max(0, Math.min(props.grid.width - 1, props.marker.x)),\n    y: Math.max(0, Math.min(props.grid.height - 1, props.marker.y)),\n  };\n});\n\n// Convert 0-10 grid coords to SVG percentage\nfunction cx(x: number) { return (x / 10) * 100; }\nfunction cy(y: number) { return (y / 10) * 100; }\nfunction tileDef(code: MapTileCode) {\n  return TILE_DEFINITIONS[code] || TILE_DEFINITIONS['#'];\n}\n</script>\n\n<template>\n  <div class=\"minimap-circle\">\n    <!-- North indicator -->\n    <div class=\"minimap-north\">N</div>\n\n    <svg viewBox=\"0 0 100 100\" class=\"minimap-svg\">\n      <!-- Background -->\n      <circle cx=\"50\" cy=\"50\" r=\"49\" fill=\"rgba(0,0,0,0.6)\" stroke=\"var(--p5-red)\" stroke-width=\"2\" />\n\n      <clipPath id=\"mini-map-circle-clip\">\n        <circle cx=\"50\" cy=\"50\" r=\"48\" />\n      </clipPath>\n\n      <g v-if=\"grid\" clip-path=\"url(#mini-map-circle-clip)\">\n        <rect x=\"0\" y=\"0\" width=\"100\" height=\"100\" fill=\"rgba(0,0,0,0.6)\" />\n        <rect\n          v-for=\"cell in gridCells\"\n          :key=\"`${cell.x}-${cell.y}`\"\n          :x=\"cell.x * cellWidth\"\n          :y=\"cell.y * cellHeight\"\n          :width=\"cellWidth + 0.3\"\n          :height=\"cellHeight + 0.3\"\n          :fill=\"tileDef(cell.code).color\"\n          :stroke=\"tileDef(cell.code).stroke\"\n          stroke-width=\"0.35\"\n        />\n        <template v-if=\"resolvedMarker\">\n          <circle\n            :cx=\"(resolvedMarker.x + 0.5) / (grid.width || 1) * 100\"\n            :cy=\"(resolvedMarker.y + 0.5) / (grid.height || 1) * 100\"\n            r=\"5\"\n            fill=\"var(--p5-red)\"\n            opacity=\"0.92\"\n          >\n            <animate attributeName=\"r\" values=\"3;5;3\" dur=\"1.5s\" repeatCount=\"indefinite\" />\n          </circle>\n          <circle\n            :cx=\"(resolvedMarker.x + 0.5) / (grid.width || 1) * 100\"\n            :cy=\"(resolvedMarker.y + 0.5) / (grid.height || 1) * 100\"\n            r=\"2\"\n            fill=\"#fff\"\n          />\n        </template>\n      </g>\n\n      <template v-else>\n        <!-- Grid lines (subtle) -->\n        <line x1=\"50\" y1=\"5\" x2=\"50\" y2=\"95\" stroke=\"rgba(255,255,255,0.05)\" stroke-width=\"0.5\" />\n        <line x1=\"5\" y1=\"50\" x2=\"95\" y2=\"50\" stroke=\"rgba(255,255,255,0.05)\" stroke-width=\"0.5\" />\n\n        <!-- Connection lines -->\n        <line\n          v-for=\"(line, i) in mapData.lines\"\n          :key=\"`l-${i}`\"\n          :x1=\"cx(line.from.x)\" :y1=\"cy(line.from.y)\"\n          :x2=\"cx(line.to.x)\" :y2=\"cy(line.to.y)\"\n          stroke=\"rgba(255,255,255,0.25)\"\n          stroke-width=\"0.8\"\n          stroke-dasharray=\"2,2\"\n        />\n\n        <!-- Nodes -->\n        <template v-for=\"node in mapData.nodes\" :key=\"`n-${node.name}`\">\n          <template v-if=\"node.type === 'player'\">\n            <circle :cx=\"cx(node.x)\" :cy=\"cy(node.y)\" r=\"4\" fill=\"var(--p5-red)\" opacity=\"0.9\">\n              <animate attributeName=\"r\" values=\"3;5;3\" dur=\"1.5s\" repeatCount=\"indefinite\" />\n            </circle>\n            <circle :cx=\"cx(node.x)\" :cy=\"cy(node.y)\" r=\"2\" fill=\"#fff\" />\n          </template>\n          <circle v-else-if=\"node.type === 'npc'\" :cx=\"cx(node.x)\" :cy=\"cy(node.y)\" r=\"2.5\" fill=\"#fff\" />\n          <circle v-else :cx=\"cx(node.x)\" :cy=\"cy(node.y)\" r=\"2\" fill=\"none\" stroke=\"#fff\" stroke-width=\"0.8\" />\n        </template>\n      </template>\n\n      <circle cx=\"50\" cy=\"50\" r=\"49\" fill=\"none\" stroke=\"var(--p5-red)\" stroke-width=\"2\" />\n    </svg>\n  </div>\n</template>\n\n<style scoped>\n.minimap-circle {\n  position: relative;\n  width: clamp(80px, 10vw, 140px);\n  height: clamp(80px, 10vw, 140px);\n}\n\n.minimap-north {\n  position: absolute;\n  top: -2px;\n  left: 50%;\n  transform: translateX(-50%);\n  font-size: 9px;\n  font-weight: 900;\n  color: var(--p5-red);\n  letter-spacing: 1px;\n  z-index: 1;\n}\n\n.minimap-svg {\n  width: 100%;\n  height: 100%;\n  border-radius: 50%;\n  overflow: hidden;\n  filter: drop-shadow(0 2px 8px rgba(0, 0, 0, 0.5));\n}\n</style>\n"],"sourceRoot":""}]);
