export async function summarizeStoryLogs(save: GameSave, options: { force?: boolean } = {}): Promise<GameSave> {
  const pendingEntries = getUnsummarizedNarrationEntries(save);
  if (!pendingEntries.length) return save;
  if (!options.force && pendingEntries.length < 10) return save;

  const nextIndex = save.narration.summary.count + 1;
  try {
    const rawSummaryText = await generateWithProfile(save.api, 'story_summary', {
      systemPrompt: buildGrandSummaryInstruction(nextIndex),
      userInput: buildSummaryInput(save, pendingEntries),
      historyPrompts: [],
      maxChatHistory: 0,
    });
    const summaryText = extractValidatedStorySummary(rawSummaryText, nextIndex);
    const timestamp = nowIso();
    const batchId = createId('sum');
    const entryIds = new Set(pendingEntries.map(entry => entry.id));
    return {
      ...save,
      narration: {
        ...save.narration,
        entries: save.narration.entries.map(entry =>
          entryIds.has(entry.id)
            ? {
                ...entry,
                summarizedAtIso: timestamp,
                summaryBatchId: batchId,
              }
            : entry,
        ),
        summary: {
          current: summaryText,
          count: nextIndex,
          lastGeneratedAtIso: timestamp,
          lastError: undefined,
          batches: [
            ...save.narration.summary.batches,
            {
              id: batchId,
              index: nextIndex,
              entryIds: pendingEntries.map(entry => entry.id),
              entryCount: pendingEntries.length,
              createdAtIso: timestamp,
              summaryText,
            },
          ],
        },
      },
    };
  } catch (error) {
    return {
      ...save,
      narration: {
        ...save.narration,
        summary: {
          ...save.narration.summary,
          lastError: error instanceof Error ? error.message : String(error),
        },
      },
    };
  }
}

export function shouldSummarizeStory(save: GameSave): boolean {
  return getUnsummarizedNarrationEntries(save).length >= 10;
}

export async function autoSummarizeStoryIfNeeded(save: GameSave): Promise<GameSave> {
  return shouldSummarizeStory(save) ? summarizeStoryLogs(save) : save;
}
