export interface RealityActionDefinition {
  id: string;
  kind: RealityActionKind;
  locationIds: string[];
  label: string;
  summary: string;
  timeMinutes: number;
  restDelta?: number;
  focusDelta?: number;
  clueIds?: string[];
  flagIds?: string[];
}

export interface RealityLocationView extends RealityLocationDefinition {
  current: boolean;
  visited: boolean;
  unlocked: boolean;
}

export interface RealityActionView extends RealityActionDefinition {
  available: boolean;
}

export interface RealityProjectionView {
  id: string;
  name: string;
  state: string;
  rule: string;
}

export interface RealityActionResult {
  save: GameSave;
  message: string;
}

