function createRealityLogId(): string {
  const randomId =
    typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
      ? crypto.randomUUID()
      : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  return `real-${randomId}`;
}

function clampScore(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(MAX_REALITY_SCORE, Math.round(value)));
}

function normalizeStringArray(value: unknown, fallback: string[] = []): string[] {
  return Array.from(new Set(Array.isArray(value) ? value.filter(item => typeof item === 'string') : fallback));
}

function createLogEntry(kind: RealityLogEntry['kind'], locationId: string, title: string, text: string): RealityLogEntry {
  return {
    id: createRealityLogId(),
    kind,
    locationId,
    title,
    text,
    createdAtIso: nowIso(),
  };
}

function addRealityLog(state: RealityState, entry: RealityLogEntry): RealityState {
  return {
    ...state,
    log: [entry, ...state.log].slice(0, MAX_REALITY_LOG_ENTRIES),
    lastActionAtIso: entry.createdAtIso,
  };
}

function createClueRecord(clueId: string, status: RealityClueStatus = 'new'): RealityClueRecord | undefined {
  const definition = REALITY_CLUE_DEFINITIONS[clueId];
  if (!definition) return undefined;
  return {
    ...definition,
    status,
    discoveredAtIso: nowIso(),
  };
}

function addRealityClues(state: RealityState, clueIds: string[]): RealityState {
  let nextState = state;
  clueIds.forEach(clueId => {
    if (nextState.discoveredClueIds.includes(clueId)) return;
    const record = createClueRecord(clueId);
    if (!record) return;
    nextState = {
      ...nextState,
      discoveredClueIds: [...nextState.discoveredClueIds, clueId],
      clues: [record, ...nextState.clues],
    };
  });
  return nextState;
}

function addRealityFlags(state: RealityState, flagIds: string[]): RealityState {
  if (!flagIds.length) return state;
  return {
    ...state,
    flags: Array.from(new Set([...state.flags, ...flagIds])),
  };
}

function getLocationDefinition(locationId: string): RealityLocationDefinition | undefined {
  return REALITY_LOCATION_DEFINITIONS.find(location => location.id === locationId);
}

function getActionDefinition(actionId: string): RealityActionDefinition | undefined {
  return REALITY_ACTION_DEFINITIONS.find(action => action.id === actionId);
}

export function createInitialRealityState(): RealityState {
  const initialState: RealityState = {
    currentLocationId: 'room_origin',
    visitedLocationIds: ['room_origin'],
    discoveredClueIds: [],
    clues: [],
    restScore: 60,
    focusScore: 50,
    flags: [],
    realizedCompanionIds: [],
    log: [],
  };
  return addRealityClues(initialState, ['clue_identity_anchor']);
}

export function normalizeRealityState(raw: unknown): RealityState {
  const fallback = createInitialRealityState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<RealityState>;
  const currentLocationId = getLocationDefinition(candidate.currentLocationId || '') ? candidate.currentLocationId! : fallback.currentLocationId;
  const discoveredClueIds = normalizeStringArray(candidate.discoveredClueIds, fallback.discoveredClueIds);
  const clues = (candidate.clues || [])
    .filter((clue): clue is RealityClueRecord => Boolean(clue?.id && clue?.title))
    .map(clue => ({
      ...clue,
      status: clue.status === 'noted' || clue.status === 'resolved' ? clue.status : 'new',
      discoveredAtIso: clue.discoveredAtIso || nowIso(),
    }));
  const missingClues = discoveredClueIds
    .filter(clueId => !clues.some(clue => clue.id === clueId))
    .map(clueId => createClueRecord(clueId))
    .filter((clue): clue is RealityClueRecord => Boolean(clue));

  return {
    currentLocationId,
    visitedLocationIds: normalizeStringArray(candidate.visitedLocationIds, fallback.visitedLocationIds),
    discoveredClueIds,
    clues: [...clues, ...missingClues],
    restScore: clampScore(candidate.restScore ?? fallback.restScore),
    focusScore: clampScore(candidate.focusScore ?? fallback.focusScore),
    flags: normalizeStringArray(candidate.flags),
    realizedCompanionIds: normalizeStringArray(candidate.realizedCompanionIds),
    lastActionAtIso: candidate.lastActionAtIso,
    log: (candidate.log || []).filter((entry): entry is RealityLogEntry => Boolean(entry?.id && entry?.title)).slice(0, MAX_REALITY_LOG_ENTRIES),
  };
}

export function getRealityCurrentLocation(save: GameSave): RealityLocationDefinition {
  return getLocationDefinition(save.reality.currentLocationId) || REALITY_LOCATION_DEFINITIONS[0];
}

export function getRealityLocationViews(save: GameSave): RealityLocationView[] {
  const current = getRealityCurrentLocation(save);
  return REALITY_LOCATION_DEFINITIONS.map(location => {
    const unlocked = location.id === current.id || current.connectedLocationIds.includes(location.id) || save.reality.visitedLocationIds.includes(location.id);
    return {
      ...location,
      current: location.id === current.id,
      visited: save.reality.visitedLocationIds.includes(location.id),
      unlocked,
    };
  });
}

export function getRealityActionViews(save: GameSave): RealityActionView[] {
  const locationId = getRealityCurrentLocation(save).id;
  return REALITY_ACTION_DEFINITIONS.map(action => ({
    ...action,
    available: action.locationIds.includes(locationId) && save.worldMode === 'reality' && !save.combat.active,
  }));
}

export function getRealityClues(save: GameSave): RealityClueRecord[] {
  return save.reality.clues;
}

export function getRealityLog(save: GameSave): RealityLogEntry[] {
  return save.reality.log;
}

export function getRealityProjectionViews(save: GameSave): RealityProjectionView[] {
  const playerState = save.playerState?.presentationMode === 'reality' ? '现实形态' : '8bit 形态';
  const playerName = save.player ? `${save.player.username}（${PLAYER_GENDER_LABELS[save.player.gender]}）` : '{{user}}';
  const views: RealityProjectionView[] = [
    {
      id: 'player',
      name: playerName,
      state: playerState,
      rule: save.worldMode === 'reality' ? '剑与魔法沉默，保留身体、记忆与选择。' : '以 8bit 勇者形态行动。',
    },
  ];

  if (!save.reality.realizedCompanionIds.length) {
    views.push({
      id: 'companions_pending',
      name: '伙伴',
      state: '尚未带入现实',
      rule: '伙伴模块接入后，8bit 原住民进入现实会现实化，但魔法不会生效。',
    });
  }

  save.reality.realizedCompanionIds.forEach(companionId => {
    const companion = getCompanionDefinition(companionId);
    views.push({
      id: companionId,
      name: companion?.name || companionId,
      state: '现实化记录',
      rule: companion ? `${companion.professionName}的关系和记忆可以保留，但战斗数值不会在现实生效。` : '现实行动只记录关系和线索，不结算战斗数值。',
    });
  });

  return views;
}

export function getRealitySummary(save: GameSave): string {
  const location = getRealityCurrentLocation(save);
  return `${location.name} / 休息 ${save.reality.restScore} / 专注 ${save.reality.focusScore} / 线索 ${save.reality.clues.length}`;
}

export function travelRealityLocation(save: GameSave, locationId: string): RealityActionResult {
  if (save.worldMode !== 'reality') throw Error('需要回到现实世界后才能移动现实地点。');
  if (save.combat.active) throw Error('战斗中不能移动现实地点。');
  const current = getRealityCurrentLocation(save);
  const target = getLocationDefinition(locationId);
  if (!target) throw Error('未知现实地点。');
  if (target.id !== current.id && !current.connectedLocationIds.includes(target.id)) throw Error('当前现实地点无法直接到达目标地点。');

  let nextReality: RealityState = {
    ...save.reality,
    currentLocationId: target.id,
    visitedLocationIds: Array.from(new Set([...save.reality.visitedLocationIds, target.id])),
  };
  nextReality = addRealityClues(nextReality, target.defaultClueIds);
  nextReality = addRealityLog(nextReality, createLogEntry('travel', target.id, `前往${target.name}`, target.summary));

  let nextSave: GameSave = {
    ...save,
    reality: nextReality,
  };
  if (target.id !== current.id && target.travelMinutes > 0) {
    nextSave = {
      ...nextSave,
      clock: advanceStoryTimeByEvent(nextSave.clock, 'reality', target.travelMinutes, `现实移动：${current.name} -> ${target.name}`).clock,
    };
  }

  return {
    save: nextSave,
    message: `已移动到${target.name}。`,
  };
}

export function performRealityAction(save: GameSave, actionId: string): RealityActionResult {
  if (save.worldMode !== 'reality') throw Error('需要回到现实世界后才能进行现实行动。');
  if (save.combat.active) throw Error('战斗中不能进行现实行动。');
  const action = getActionDefinition(actionId);
  if (!action) throw Error('未知现实行动。');
  const location = getRealityCurrentLocation(save);
  if (!action.locationIds.includes(location.id)) throw Error('当前地点不能执行该现实行动。');

  let nextReality: RealityState = {
    ...save.reality,
    restScore: clampScore(save.reality.restScore + (action.restDelta || 0)),
    focusScore: clampScore(save.reality.focusScore + (action.focusDelta || 0)),
  };
  nextReality = addRealityClues(nextReality, action.clueIds || []);
  nextReality = addRealityFlags(nextReality, action.flagIds || []);
  nextReality = addRealityLog(nextReality, createLogEntry(action.kind, location.id, action.label, action.summary));

  const nextSave: GameSave = {
    ...save,
    reality: nextReality,
    clock: advanceStoryTimeByEvent(save.clock, 'reality', action.timeMinutes, `现实行动：${action.label}`).clock,
  };

  return {
    save: nextSave,
    message: `${action.label}已记录。`,
  };
}

export function recordRealityClue(save: GameSave, clueId: string, source = '系统同步'): GameSave {
  if (!REALITY_CLUE_DEFINITIONS[clueId]) throw Error('未知现实线索。');
  const location = getRealityCurrentLocation(save);
  const nextReality = addRealityLog(
    addRealityClues(save.reality, [clueId]),
    createLogEntry('sync', location.id, source, REALITY_CLUE_DEFINITIONS[clueId].title),
  );
  return {
    ...save,
    reality: nextReality,
  };
}

export function syncRealityFromEvent(save: GameSave, eventId: string): GameSave {
  if (eventId === 'opening_generated') return recordRealityClue(save, 'clue_watch_origin', '开场白');
  if (eventId === 'watch_locked') return recordRealityClue(save, 'clue_watch_lock', '手表锁定');
  if (eventId === 'return_reality') return recordRealityClue(save, 'clue_world_pause', '返回现实');
  return save;
}
