import { characters, chibiCharacters } from './assets';
import type { PlayerGender } from './core/types';

const formalPortraitById: Record<string, string | undefined> = {
  player: characters.heroMale,
  hero: characters.heroMale,
  lia_twin: characters.lia,
  companion_lia_twin: characters.lia,
  leon_twin: characters.leon,
  companion_leon_twin: characters.leon,
  elder_aino: characters.elderAino,
  companion_elder_aino: characters.elderAino,
  finn_mapper: characters.finnMapper,
  companion_finn_mapper: characters.finnMapper,
  sister_iria: characters.sisterIria,
  companion_sister_iria: characters.sisterIria,
  roro_child: characters.roroChild,
  companion_roro_child: characters.roroChild,
  merchant_norma: characters.merchantNorma,
  companion_merchant_norma: characters.merchantNorma,
  mentor_borro: characters.mentorBorro,
  companion_mentor_borro: characters.mentorBorro,
  old_record_echo: characters.oldRecordEcho,
  companion_old_record_echo: characters.oldRecordEcho,
  verdant_sentry: characters.verdantSentry,
  companion_verdant_sentry: characters.verdantSentry,
  tide_bell_keeper: characters.tideBellKeeper,
  companion_tide_bell_keeper: characters.tideBellKeeper,
  ember_checkpoint_smith: characters.emberCheckpointSmith,
  companion_ember_checkpoint_smith: characters.emberCheckpointSmith,
  frost_station_keeper: characters.frostStationKeeper,
  companion_frost_station_keeper: characters.frostStationKeeper,
  demon_gate_echo: characters.demonGateEcho,
};

const chibiAliasById: Record<string, string> = {
  player: 'player',
  hero: 'player',
  companion_lia_twin: 'lia_twin',
  companion_leon_twin: 'leon_twin',
};

export function getPlayerFormalPortrait(gender?: PlayerGender): string {
  return gender === 'female' ? characters.heroFemale : characters.heroMale;
}

export function getPlayerChibiPortrait(gender?: PlayerGender): string | undefined {
  return gender === 'female' ? chibiCharacters.playerFemale : chibiCharacters.playerMale;
}

export function getFormalCharacterPortrait(characterId?: string): string | undefined {
  if (!characterId) return undefined;
  return formalPortraitById[characterId];
}

export function getChibiCharacterPortrait(characterId?: string): string | undefined {
  if (!characterId) return undefined;
  const assetId = chibiAliasById[characterId] || characterId.replace(/^companion_/, '');
  return chibiCharacters[assetId];
}
