/**
 * 8bit的幻想 - 后台控制台入口
 *
 * M1 only mounts the fullscreen client shell. Gameplay authority, save migration,
 * worldbook binding, and AI generation are implemented in later milestones.
 */
import { teleportStyle } from '@util/script';
import App from './App.vue';
import './styles/global.css';
$(() => {
    const parentDoc = window.parent.document;
    const pinia = createPinia();
    let app = null;
    let iframeEl = null;
    let escapeButtonEl = null;
    let styleDestroy = null;
    let viewportDestroy = null;
    const escapeKeyTargets = [];
    function handleEscapeKey(event) {
        if (event.key !== 'Escape')
            return;
        event.preventDefault();
        unmountConsole();
    }
    function addEscapeKeyTarget(target) {
        if (!target || escapeKeyTargets.includes(target))
            return;
        target.addEventListener('keydown', handleEscapeKey, true);
        escapeKeyTargets.push(target);
    }
    function removeEscapeControls() {
        escapeKeyTargets.forEach(target => target.removeEventListener('keydown', handleEscapeKey, true));
        escapeKeyTargets.length = 0;
        if (escapeButtonEl) {
            escapeButtonEl.remove();
            escapeButtonEl = null;
        }
    }
    function mountEscapeControls() {
        if (escapeButtonEl)
            return;
        const button = parentDoc.createElement('button');
        button.type = 'button';
        button.textContent = '退出幻想';
        button.title = '退出 8bit 的幻想';
        button.setAttribute('aria-label', '退出 8bit 的幻想');
        button.style.cssText = [
            'position:fixed',
            'top:14px',
            'right:14px',
            'z-index:100000',
            'height:32px',
            'padding:0 12px',
            'border:1px solid rgba(42,43,45,.34)',
            'border-radius:7px',
            'background:rgba(250,248,238,.94)',
            'color:#242322',
            'font:12px/1 "Segoe UI","Microsoft YaHei UI",system-ui,sans-serif',
            'letter-spacing:0',
            'box-shadow:0 14px 34px rgba(0,0,0,.24)',
            'cursor:pointer',
        ].join(';');
        button.addEventListener('click', unmountConsole);
        parentDoc.body.appendChild(button);
        escapeButtonEl = button;
        addEscapeKeyTarget(parentDoc);
        addEscapeKeyTarget(window.parent);
    }
    function hideMountedEscapeButton() {
        if (!escapeButtonEl)
            return;
        escapeButtonEl.hidden = true;
        escapeButtonEl.setAttribute('aria-hidden', 'true');
    }
    function unmountConsole() {
        if (viewportDestroy) {
            viewportDestroy();
            viewportDestroy = null;
        }
        if (app) {
            app.unmount();
            app = null;
        }
        if (styleDestroy) {
            styleDestroy();
            styleDestroy = null;
        }
        if (iframeEl) {
            iframeEl.remove();
            iframeEl = null;
        }
        removeEscapeControls();
    }
    function getParentViewport() {
        const visualViewport = window.parent.visualViewport;
        const fallbackWidth = parentDoc.documentElement.clientWidth || window.parent.innerWidth || window.innerWidth;
        const fallbackHeight = parentDoc.documentElement.clientHeight || window.parent.innerHeight || window.innerHeight;
        return {
            width: Math.max(320, Math.floor(visualViewport?.width || fallbackWidth)),
            height: Math.max(360, Math.floor(visualViewport?.height || fallbackHeight)),
            left: Math.floor(visualViewport?.offsetLeft || 0),
            top: Math.floor(visualViewport?.offsetTop || 0),
        };
    }
    function syncViewportToIframe() {
        if (!iframeEl)
            return;
        const viewport = getParentViewport();
        iframeEl.style.left = `${viewport.left}px`;
        iframeEl.style.top = `${viewport.top}px`;
        iframeEl.style.width = `${viewport.width}px`;
        iframeEl.style.height = `${viewport.height}px`;
        iframeEl.style.right = 'auto';
        iframeEl.style.bottom = 'auto';
        const iframeDoc = iframeEl.contentDocument;
        if (!iframeDoc)
            return;
        const root = iframeDoc.documentElement;
        root.style.setProperty('--eightbit-viewport-width', `${viewport.width}px`);
        root.style.setProperty('--eightbit-viewport-height', `${viewport.height}px`);
    }
    function bindVisualViewport() {
        if (viewportDestroy)
            viewportDestroy();
        const visualViewport = window.parent.visualViewport;
        const update = () => syncViewportToIframe();
        visualViewport?.addEventListener('resize', update);
        visualViewport?.addEventListener('scroll', update);
        window.parent.addEventListener('resize', update);
        window.parent.addEventListener('orientationchange', update);
        viewportDestroy = () => {
            visualViewport?.removeEventListener('resize', update);
            visualViewport?.removeEventListener('scroll', update);
            window.parent.removeEventListener('resize', update);
            window.parent.removeEventListener('orientationchange', update);
        };
        update();
    }
    function mountAppIntoIframe(iframe) {
        if (app || iframeEl !== iframe)
            return;
        const iframeDoc = iframe.contentDocument;
        if (!iframeDoc?.body)
            return;
        syncViewportToIframe();
        addEscapeKeyTarget(iframeDoc);
        addEscapeKeyTarget(iframe.contentWindow);
        const { destroy } = teleportStyle(iframeDoc.head);
        styleDestroy = destroy;
        app = createApp(App, { onExit: unmountConsole }).use(pinia);
        app.mount(iframeDoc.body);
        hideMountedEscapeButton();
    }
    function mountConsole() {
        if (app || iframeEl)
            return;
        mountEscapeControls();
        const iframe = document.createElement('iframe');
        iframe.setAttribute('script_id', getScriptId());
        iframe.setAttribute('frameborder', '0');
        iframe.setAttribute('title', '8bit的幻想');
        iframe.style.cssText = [
            'position:fixed',
            'left:0',
            'top:0',
            'width:100vw',
            'height:100dvh',
            'z-index:99999',
            'border:none',
            'background:#000',
        ].join(';');
        iframe.addEventListener('load', () => {
            mountAppIntoIframe(iframe);
        });
        iframeEl = iframe;
        bindVisualViewport();
        parentDoc.body.appendChild(iframe);
        window.setTimeout(() => mountAppIntoIframe(iframe), 0);
    }
    replaceScriptButtons([{ name: '进入8bit的幻想', visible: true }]);
    eventOn(getButtonEvent('进入8bit的幻想'), mountConsole);
    mountConsole();
    $(window).on('pagehide', () => {
        unmountConsole();
    });
});
