 } from '../../core/companions';\nimport { getCompanionEquipCandidates, getCompanionEquipmentSlotViews } from '../../core/equipment';\nimport { useGameStore } from '../../stores/gameStore';\nimport { useUiStore } from '../../stores/uiStore';\nimport { getChibiCharacterPortrait, getFormalCharacterPortrait, getPlayerChibiPortrait, getPlayerFormalPortrait } from '../../visualAssets';\n\nconst game = useGameStore();\nconst ui = useUiStore();\nconst activeMemberId = ref('player');\nconst activeDetailMode = ref<'profile' | 'equipment' | 'talk' | 'reality'>('profile');\n\nconst companionRows = computed(() => {\n  if (!game.save) return [];\n  return getJoinedCompanionViews(game.save).map(view => ({\n    id: view.definition.npcId,\n    actorId: view.definition.actorId,\n    name: view.definition.name,\n    title: `${view.definition.professionName} / Lv.${view.record.level}`,\n    description: view.definition.joinNarrationHint,\n    locationId: game.save?.map.currentLocationId,\n    portrait: getFormalCharacterPortrait(view.definition.npcId),\n    chibi: getChibiCharacterPortrait(view.definition.npcId),\n    realized: Boolean(game.save?.reality.realizedCompanionIds.includes(view.definition.npcId)),\n    here: true,\n    professionName: view.definition.professionName,\n    combatRole: view.definition.combatRole,\n    equipmentSummary: view.definition.equipmentSummary,\n    level: view.record.level,\n    hp: `${view.record.currentHp}/${view.maxHp}`,\n    mp: `${view.record.currentMp}/${view.maxMp}`,\n    exp: `${view.record.experience}/${view.nextLevelExperience}`,\n    expPercent: view.experiencePercent,\n  }));\n});\n\nconst candidateRows = computed(() =>\n  game.save\n    ? getRecruitableCompanionEligibilities(game.save)\n        .filter(row => !row.joined && !row.dead)\n        .map(row => ({\n          id: row.definition.npcId,\n          name: row.definition.name,\n          title: row.definition.professionName,\n          available: row.available,\n          condition: row.available ? row.definition.joinLabel : row.missing.join('；'),\n        }))\n    : [],\n);\n\nconst partyMembers = computed(() => [\n  {\n    id: 'player',\n    name: game.creation.username || '主角',\n    title: `${game.creation.genderLabel || '未记录'} / Lv.${game.playerState?.level || 1}`,\n    description: game.creation.profileText || '现实身份已经写入当前聊天世界书。',\n    portrait: getPlayerFormalPortrait(game.creation.gender),\n    chibi: getPlayerChibiPortrait(game.creation.gender),\n    realized: true,\n    here: true,\n    professionName: game.playerState?.professions.active || '勇者',\n    combatRole: 'hero',\n    equipmentSummary: '玩家装备栏',\n    level: game.playerState?.level || 1,\n    hp: `${game.playerState?.currentHp || 0}`,\n    mp: `${game.playerState?.currentMp || 0}`,\n    exp: `${game.levelProgress?.current || 0}/${game.levelProgress?.required || 0}`,\n    expPercent: game.levelProgress?.percent || 0,\n  },\n  ...companionRows.value,\n]);\n\nconst activeMember = computed(() => partyMembers.value.find(member => member.id === activeMemberId.value) || partyMembers.value[0]);\nconst activeCompanionSlots = computed(() =>\n  game.save && activeMember.value?.id !== 'player' ? getCompanionEquipmentSlotViews(game.save, activeMember.value.id) : [],\n);\nconst activeCompanionCandidates = computed(() =>\n  game.save && activeMember.value?.id !== 'player' ? getCompanionEquipCandidates(game.save, activeMember.value.id) : [],\n);\n\nwatch(\n  partyMembers,\n  members => {\n    if (!members.some(member => member.id === activeMemberId.value)) activeMemberId.value = members[0]?.id || 'player';\n  },\n  { immediate: true },\n);\n\nfunction selectMember(id: string) {\n  activeMemberId.value = id;\n  activeDetailMode.value = 'profile';\n}\n\nfunction talkToCompanion() {\n  if (!activeMember.value || activeMember.value.id === 'player') return;\n  ui.setActiveNpc(activeMember.value.id);\n}\n</script>\n\n<template>\n  <section class=\"party-panel\" aria-label=\"队伍\">\n    <header class=\"party-header\">\n      <div>\n        <div class=\"party-kicker\">队伍</div>\n        <div class=\"party-title\">队伍</div>\n        <p>队伍角色会在这里集中查看、交谈和进行现实化记录。</p>\n      </div>\n    </header>\n\n    <div class=\"party-layout\">\n      <div class=\"party-list\">\n        <button\n          v-for=\"member in partyMembers\"\n          :key=\"member.id\"\n          class=\"party-card\"\n          :class=\"{ active: activeMember?.id === member.id }\"\n          @click=\"selectMember(member.id)\"\n        >\n          <img v-if=\"member.chibi\" :src=\"member.chibi\" :alt=\"member.name\" />\n          <span v-else class=\"party-card-empty\" aria-hidden=\"true\"></span>\n          <span>\n            <strong>{{ member.name }}</strong>\n            <em>{{ member.title }}</em>\n          </span>\n          <b>{{ member.id === 'player' ? '主角' : member.realized ? '现实化' : '同行' }}</b>\n        </button>\n\n        <div v-if=\"candidateRows.length\" class=\"party-candidates\">\n          <span>入队候选</span>\n          <button\n            v-for=\"candidate in candidateRows\"\n            :key=\"candidate.id\"\n            class=\"party-candidate\"\n            :class=\"{ available: candidate.available }\"\n            @click=\"ui.setActiveNpc(candidate.id)\"\n          >\n            <strong>{{ candidate.name }} / {{ candidate.title }}</strong>\n            <em>{{ candidate.condition }}</em>\n          </button>\n        </div>\n      </div>\n\n      <div v-if=\"activeMember\" class=\"party-detail\">\n        <div class=\"party-detail-head\">\n          <img v-if=\"activeMember.portrait\" :src=\"activeMember.portrait\" :alt=\"activeMember.name\" />\n          <div v-else class=\"party-detail-empty\" aria-hidden=\"true\"></div>\n          <div>\n            <span>{{ activeMember.id === 'player' ? '主角' : '同伴' }}</span>\n            <strong>{{ activeMember.name }}</strong>\n            <em>{{ activeMember.title }}</em>\n            <p>{{ activeMember.description }}</p>\n          </div>\n        </div>\n\n        <div class=\"party-action-tabs\">\n          <button class=\"action-btn\" :class=\"{ primary: activeDetailMode === 'profile' }\" @click=\"activeDetailMode = 'profile'\">\n            资料\n          </button>\n          <button class=\"action-btn\" :class=\"{ primary: activeDetailMode === 'equipment' }\" @click=\"activeDetailMode = 'equipment'\">\n            装备\n          </button>\n          <button\n            v-if=\"activeMember.id !== 'player'\"\n            class=\"action-btn\"\n            :class=\"{ primary: activeDetailMode === 'talk' }\"\n            @click=\"activeDetailMode = 'talk'\"\n          >\n            交谈\n          </button>\n          <button\n            v-if=\"activeMember.id !== 'player'\"\n            class=\"action-btn\"\n            :class=\"{ primary: activeDetailMode === 'reality' }\"\n            @click=\"activeDetailMode = 'reality'\"\n          >\n            现实\n          </button>\n        </div>\n\n        <div v-if=\"activeMember.id === 'player'\" class=\"party-player-block\">\n          <div class=\"data-grid\" style=\"grid-template-columns:repeat(3,1fr);\">\n            <div class=\"data-card\">\n              <span class=\"data-card-label\">生命</span>\n              <strong class=\"data-card-value\">{{ game.playerState?.currentHp || 0 }}</strong>\n            </div>\n            <div class=\"data-card\">\n              <span class=\"data-card-label\">魔力</span>\n              <strong class=\"data-card-value\">{{ game.playerState?.currentMp || 0 }}</strong>\n            </div>\n            <div class=\"data-card\">\n              <span class=\"data-card-label\">经验</span>\n              <strong class=\"data-card-value gold\">{{ game.levelProgress?.current || 0 }}</strong>\n            </div>\n          </div>\n          <EquipmentPanel v-if=\"activeDetailMode === 'equipment'\" />\n          <p v-else class=\"party-note\">玩家身份、性别、现实人设和当前状态会同步给正文与世界书记忆。</p>\n        </div>\n\n        <div v-else-if=\"activeDetailMode === 'equipment'\" class=\"party-companion-equipment\">\n          <div class=\"party-slot\">\n            <span>随身定位</span>\n            <strong>{{ activeMember.equipmentSummary }}</strong>\n          </div>\n          <div v-for=\"slot in activeCompanionSlots\" :key=\"slot.slot\" class=\"party-slot\">\n            <span>{{ slot.label }}</span>\n            <strong>{{ slot.definition?.name || '空槽' }}</strong>\n            <button v-if=\"slot.itemId\" class=\"action-btn\" style=\"font-size:10px;padding:2px 8px;\" :disabled=\"game.isBusy\" @click=\"game.unequipSlot(slot.slot, activeMember.id)\">卸下</button>\n          </div>\n          <div v-if=\"activeCompanionCandidates.length\" class=\"party-companion-candidates\">\n            <button\n              v-for=\"candidate in activeCompanionCandidates\"\n              :key=\"candidate.itemId\"\n              class=\"action-btn gold\"\n              :disabled=\"game.isBusy\"\n              @click=\"game.equipItem(candidate.itemId, undefined, activeMember.id)\"\n            >\n              装备 {{ candidate.name }}\n            </button>\n          </div>\n          <p>同伴装备使用同一背包库存。装备后会影响该同伴的生命、魔力和战斗属性。</p>\n        </div>\n\n        <div v-else-if=\"activeDetailMode === 'talk'\" class=\"party-companion-actions\">\n          <button class=\"action-btn primary\" :disabled=\"!activeMember.here\" @click=\"talkToCompanion\">\n            打开交谈\n          </button>\n          <p>\n            {{ activeMember.here ? '当前地点可以直接交谈。' : '需要回到伙伴所在地点才能打开自由交谈。' }}\n            交谈会回到主页面输入栏，由正文事件管线记录。\n          </p>\n        </div>\n\n        <div v-else-if=\"activeDetailMode === 'reality'\" class=\"party-companion-actions\">\n          <button\n            class=\"action-btn gold\"\n            :disabled=\"game.isBusy || game.mode !== 'reality' || activeMember.realized\"\n            @click=\"game.projectCompanionToReality(activeMember.id)\"\n          >\n            {{ activeMember.realized ? '已带入现实' : '带入现实' }}\n          </button>\n          <p>现实化只记录关系和正文，不把魔法战斗数值带入现实；该操作需要处于现实世界。</p>\n        </div>\n\n        <div v-else class=\"party-companion-actions\">\n          <div class=\"data-grid companion-data-grid\">\n            <div class=\"data-card\">\n              <span class=\"data-card-label\">职业</span>\n              <strong class=\"data-card-value\">{{ activeMember.professionName }}</strong>\n            </div>\n            <div class=\"data-card\">\n              <span class=\"data-card-label\">生命</span>\n              <strong class=\"data-card-value\">{{ activeMember.hp }}</strong>\n            </div>\n            <div class=\"data-card\">\n              <span class=\"data-card-label\">魔力</span>\n              <strong class=\"data-card-value\">{{ activeMember.mp }}</strong>\n            </div>\n            <div class=\"data-card\">\n              <span class=\"data-card-label\">经验</span>\n              <strong class=\"data-card-value gold\">{{ activeMember.exp }}</strong>\n            </div>\n          </div>\n          <p>\n            {{ activeMember.description }}\n            当前状态：{{ activeMember.realized ? '已经建立现实化记录。' : activeMember.here ? '正在当前地点附近。' : '需要前往其所在地点。' }}\n          </p>\n        </div>\n      </div>\n    </div>\n  </section>\n</template>\n\n<style scoped>\n.party-panel {\n  display: grid;\n  gap: 16px;\n}\n\n.party-header {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.party-kicker {\n  color: var(--p5-red);\n  font-size: var(--fs-label);\n  font-weight: 900;\n  letter-spacing: 3px;\n}\n\n.party-title {\n  margin-top: 2px;\n  font-size: var(--fs-title);\n  font-weight: 900;\n}\n\n.party-header p {\n  margin-top: 2px;\n  color: var(--p5-gray-dim);\n  font-size: var(--fs-label);\n}\n\n.party-layout {\n  display: grid;\n  grid-template-columns: minmax(220px, 32%) minmax(0, 1fr);\n  gap: 16px;\n}\n\n.party-list,\n.party-detail,\n.party-player-block {\n  display: grid;\n  gap: 10px;\n}\n\n.party-card {\n  display: grid;\n  grid-temp