export interface CompanionDefinition {
  npcId: string;
  actorId: string;
  name: string;
  title: string;
  professionId: string;
  professionName: string;
  combatRole: CompanionCombatRole;
  joinFlag: string;
  joinLabel: string;
  joinCondition: string;
  joinNarrationHint: string;
  equipmentSummary: string;
  recruitable: boolean;
  requiredQuestIds?: string[];
  requiredAnyQuestIds?: string[];
  requiredFlags?: string[];
  mutuallyExclusiveWith?: string[];
  startingLevel: number;
  baseMaxHp: number;
  baseMaxMp: number;
  baseStats: CombatActorStats;
  growth: CompanionGrowthStats;
  skillIds: SkillId[];
}

export interface CompanionEligibility {
  definition: CompanionDefinition;
  available: boolean;
  joined: boolean;
  dead: boolean;
  missing: string[];
}

export interface CompanionView {
  definition: CompanionDefinition;
  record: CompanionRuntimeRecord;
  maxHp: number;
  maxMp: number;
  stats: CombatActorStats;
  nextLevelExperience: number;
  experiencePercent: number;
}

function companionStats(input: Partial<CombatActorStats> & Pick<CombatActorStats, 'physicalAttack' | 'physicalDefense' | 'magicalAttack' | 'magicalDefense' | 'speed'>): CombatActorStats {
  return {
    hit: 82,
    evasionRate: 4,
    criticalRate: 4,
    criticalDamage: 150,
    statusAccuracy: 5,
    statusResistance: 5,
    healingPower: 0,
    ...input,
  };
}

function companionGrowth(input: Partial<CompanionGrowthStats>): CompanionGrowthStats {
  return {
    maxHp: 7,
    maxMp: 2,
    physicalAttack: 2,
    physicalDefense: 1,
    magicalAttack: 1,
    magicalDefense: 1,
    speed: 1,
    hit: 0.4,
    evasionRate: 0.2,
    criticalRate: 0.15,
    statusAccuracy: 0.2,
    statusResistance: 0.2,
    healingPower: 0.4,
    ...input,
  };
}

