n\n.npc-dialogue-strip em,\n.npc-free-dialogue-panel em {\n  color: var(--p5-gray-dim);\n  font-size: var(--fs-label);\n  font-style: normal;\n}\n\n.npc-free-dialogue-panel {\n  display: grid;\n  gap: 8px;\n  padding: 12px;\n  border-left: 3px solid #62a8ff;\n  background: rgba(98, 168, 255, 0.08);\n}\n\n.npc-free-input {\n  width: 100%;\n  min-height: 88px;\n  padding: 10px 12px;\n  resize: vertical;\n  color: #fff;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.1);\n  border-left: 3px solid #62a8ff;\n}\n\n.npc-free-input:focus {\n  outline: none;\n  border-color: #62a8ff;\n}\n\n.map-contact-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\n  gap: 6px;\n}\n\n.scene-confirm-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 70;\n  display: grid;\n  place-items: center;\n  padding: clamp(16px, 3vw, 40px);\n  background: rgba(0, 0, 0, 0.64);\n  backdrop-filter: blur(8px);\n}\n\n.scene-confirm-card {\n  width: min(560px, 94vw);\n  display: grid;\n  gap: 14px;\n  padding: clamp(18px, 2.5vw, 28px);\n  background: rgba(8, 8, 12, 0.96);\n  border: 2px solid var(--p5-red);\n  border-radius: 8px;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.55);\n}\n\n.scene-confirm-card.tone-gold { border-color: var(--p5-gold); }\n.scene-confirm-card.tone-blue { border-color: #62a8ff; }\n.scene-confirm-card.tone-purple { border-color: #b578ff; }\n.scene-confirm-card.tone-orange { border-color: #ff9c42; }\n.scene-confirm-card.tone-green { border-color: var(--p5-safe); }\n.scene-confirm-card.tone-gray { border-color: var(--p5-gray-dim); }\n.scene-confirm-card.tone-white { border-color: rgba(255, 255, 255, 0.78); }\n\n.scene-confirm-head {\n  display: grid;\n  gap: 4px;\n}\n\n.scene-confirm-head span {\n  color: var(--p5-gray-dim);\n  font-size: var(--fs-label);\n  font-weight: 900;\n  letter-spacing: 3px;\n  text-transform: uppercase;\n}\n\n.scene-confirm-head strong {\n  font-size: var(--fs-title);\n  font-weight: 900;\n}\n\n.scene-confirm-body {\n  color: rgba(255, 255, 255, 0.82);\n  font-size: var(--fs-body);\n  line-height: 1.75;\n}\n\n.scene-confirm-tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 5px;\n}\n\n.scene-confirm-tags span {\n  padding: 2px 7px;\n  background: rgba(255, 255, 255, 0.06);\n  color: var(--p5-gray);\n  font-size: var(--fs-label);\n  font-family: \"Cascadia Code\", Consolas, monospace;\n}\n\n.scene-confirm-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n}\n\n/* ═══════════════════════════════════════════════════════════════\n   Menu Screen — P5 full-screen takeover\n   ═══════════════════════════════════════════════════════════════ */\n\n.menu-screen {\n  display: grid;\n  grid-template-columns: 38% 62%;\n  height: 100%;\n  background:\n    repeating-linear-gradient(-45deg, #000 0 12px, #0a0a0a 12px 14px);\n  overflow: hidden;\n}\n\n.menu-portrait {\n  display: flex;\n  align-items: flex-end;\n  justify-content: center;\n  padding-bottom: 3vh;\n  position: relative;\n  overflow: hidden;\n}\n\n.menu-portrait img {\n  max-height: 78vh;\n  width: auto;\n  object-fit: contain;\n  filter: drop-shadow(4px 4px 0 var(--p5-red));\n}\n\n.menu-portrait-info {\n  position: absolute;\n  bottom: clamp(16px, 3vh, 32px);\n  left: clamp(16px, 2vw, 32px);\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.menu-portrait-info .level {\n  font-size: var(--fs-title);\n  font-weight: 900;\n  color: var(--p5-gold);\n}\n\n.menu-right {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  overflow: hidden;\n}\n\n.menu-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: clamp(12px, 2vh, 24px) clamp(16px, 2vw, 32px);\n  border-bottom: 3px solid var(--p5-red);\n}\n\n.menu-title {\n  font-size: var(--fs-heading);\n  font-weight: 900;\n  letter-spacing: 3px;\n  transform: skewX(-4deg);\n}\n\n.menu-back-btn {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 16px;\n  background: rgba(255, 255, 255, 0.06);\n  border-radius: 4px;\n  color: #fff;\n  font-size: var(--fs-label);\n  font-weight: 700;\n  letter-spacing: 2px;\n  transition: background 150ms;\n}\n\n.menu-back-btn:hover { background: var(--p5-red); }\n\n.menu-back-btn svg {\n  width: 16px; height: 16px;\n  fill: none; stroke: currentColor; stroke-width: 2;\n}\n\n/* Menu item list */\n.menu-list {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  gap: clamp(2px, 0.4vh, 6px);\n  padding: clamp(12px, 2vw, 32px);\n  overflow-y: auto;\n}\n\n.menu-item {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: clamp(10px, 1.5vh, 18px) clamp(14px, 2vw, 24px);\n  font-size: var(--fs-menu);\n  font-weight: 800;\n  letter-spacing: 2px;\n  color: rgba(255, 255, 255, 0.4);\n  cursor: pointer;\n  overflow: hidden;\n  transform: skewX(-3deg);\n  transition: color 150ms;\n}\n\n.menu-item::before {\n  content: '';\n  position: absolute;\n  inset: 0;\n  background: var(--p5-red);\n  transform: scaleX(0);\n  transform-origin: left;\n  transition: transform 200ms cubic-bezier(0.4, 0, 0.2, 1);\n  z-index: 0;\n}\n\n.menu-item:hover::before,\n.menu-item.active::before {\n  transform: scaleX(1);\n}\n\n.menu-item:hover,\n.menu-item.active {\n  color: #fff;\n}\n\n.menu-item > * { position: relative; z-index: 1; }\n\n.menu-item .item-en {\n  font-size: clamp(10px, 0.8vw, 13px);\n  letter-spacing: 3px;\n  text-transform: uppercase;\n  opacity: 0.6;\n}\n\n/* Menu sub-page content */\n.menu-content {\n  flex: 1;\n  overflow-y: auto;\n  padding: clamp(16px, 2vw, 32px);\n}\n\n/* ═══════════════════════════════════════════════════════════════\n   Battle Screen\n   ═══════════════════════════════════════════════════════════════ */\n\n.battle-bg {\n  position: absolute;\n  inset: 0;\n  background-size: cover;\n  background-position: center bottom;\n}\n\n.battle-bg::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(180deg, rgba(0,0,0,0.2) 0%, rgba(0,0,0,0.6) 100%);\n}\n\n.battle-header {\n  position: absolute;\n  top: clamp(8px, 1.5vw, 16px);\n  left: clamp(8px, 2vw, 20px);\n  right: clamp(8px, 2vw, 20px);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: clamp(6px, 1vw, 12px) clamp(12px, 2vw, 24px);\n  background: var(--p5-red);\n  color: #fff;\n  font-size: var(--fs-title);\n  font-weight: 900;\n  letter-spacing: 2px;\n  clip-path: polygon(12px 0, 100% 0, calc(100% - 12px) 100%, 0 100%);\n  transform: skewX(-4deg);\n  z-index: 2;\n}\n\n.battle-monsters {\n  position: absolute;\n  top: 20%;\n  left: 0;\n  right: 0;\n  display: flex;\n  align-items: flex-end;\n  justify-content: center;\n  gap: clamp(12px, 2vw, 32px);\n  z-index: 2;\n}\n\n.battle-monster {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  cursor: pointer;\n  transition: transform 150ms;\n}\n\n.battle-monster:hover { transform: scale(1.05); }\n.battle-monster.selected { transform: scale(1.08); }\n.battle-monster.defeated { opacity: 0.3; filter: grayscale(1); }\n\n.battle-monster-sprite {\n  width: clamp(56px, 8vw, 120px);\n  height: clamp(56px, 8vw, 120px);\n  object-fit: contain;\n  animation: monster-bounce 1.2s ease-in-out infinite;\n}\n\n@keyframes monster-bounce {\n  0%, 100% { transform: translateY(0); }\n  50% { transform: translateY(-6px); }\n}\n\n.battle-monster-name {\n  font-size: var(--fs-label);\n  font-weight: 700;\n  text-shadow: 0 1px 3px rgba(0,0,0,0.8);\n}\n\n.battle-monster-hp {\n  width: clamp(40px, 6vw, 80px);\n  height: 4px;\n  background: rgba(255,255,255,0.15);\n  border-radius: 2px;\n  overflow: hidden;\n}\n\n.battle-monster-hp i {\n  display: block;\n  height: 100%;\n  background: var(--p5-hp);\n  transition: width 400ms ease;\n}\n\n.battle-player-bar {\n  position: absolute;\n  bottom: clamp(80px, 12vh, 140px);\n  left: clamp(12px, 2vw, 24px);\n  right: clamp(12px, 2vw, 24px);\n  display: flex;\n  align-items: center;\n  gap: clamp(12px, 2vw, 24px);\n  padding: clamp(8px, 1vw, 14px) clamp(12px, 2vw, 24px);\n  background: rgba(0, 0, 0, 0.75);\n  backdrop-filter: blur(8px);\n  border-radius: 4px;\n  z-index: 2;\n}\n\n.battle-action-bar {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  display: flex;\n  gap: clamp(3px, 0.4vw, 6px);\n  padding: clamp(6px, 1vw, 12px);\n  background: rgba(0, 0, 0, 0.92);\n  border-top: 2px solid var(--p5-red);\n  z-index: 3;\n}\n\n.battle-action-btn {\n  flex: 1;\n  padding: clamp(8px, 1.2vw, 14px);\n  background: rgba(255, 255, 255, 0.05);\n  color: #fff;\n  font-weight: 800;\n  font-size: var(--fs-body);\n  letter-spacing: 1px;\n  clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%);\n  transition: all 150ms;\n  text-align: center;\n}\n\n.battle-action-btn:hover:not(:disabled) {\n  background: var(--p5-red);\n  transform: scale(1.04);\n}\n\n.battle-action-btn:active:not(:disabled) { transform: scale(0.95); }\n.battle-action-btn.selected { background: var(--p5-red); transform: skewX(-3deg) scale(1.06); }\n\n.battle-log {\n  position: absolute;\n  bottom: clamp(50px, 8vh, 80px);\n  left: 0;\n  right: 0;\n  max-height: clamp(60px, 10vh, 100px);\n  overflow-y: auto;\n  padding: clamp(4px, 0.6vw, 8px) clamp(12px, 2vw, 24px);\n  background: rgba(0, 0, 0, 0.5);\n  font-size: var(--fs-label);\n  z-index: 2;\n}\n\n.battle-log p { margin: 2px 0; }\n.battle-log p.good { color: var(--p5-safe); }\n.battle-log p.bad { color: var(--p5-hp); }\n.battle-log p.reward { color: var(--p5-gold); }\n\n/* ═══════════════════════════════════════════════════════════════\n   Creation Screen\n   ═══════════════════════════════════════════════════════════════ */\n\n.creation-screen {\n  display: grid;\n  place-items: center;\n  height: 100%;\n  position: relative;\n}\n\n.creation-bg {\n  position: absolute;\n  inset: 0;\n  background-size: cover;\n  background-position: center;\n}\n\n.creation-b