export interface NpcTopicDefinition {
  id: string;
  label: string;
  kind: NpcTopicKind;
  summary: string;
  responseSeed: string;
  questEvent?: QuestEventInput;
  unlockFlag?: string;
  companionRecruitId?: string;
  requiredQuestStatuses?: { questId: string; statuses: QuestStatus[]; reason?: string }[];
  requiredItems?: { itemId: string; count: number; reason?: string }[];
  requiredKnownTopicIds?: string[];
}

export interface NpcTopicView extends NpcTopicDefinition {
  available: boolean;
  unavailableReason?: string;
}

export interface NpcDefinition {
  id: string;
  name: string;
  title: string;
  locationId: string;
  role: NpcRole;
  disposition: NpcDisposition;
  description: string;
  worldbookHint: string;
  topics: NpcTopicDefinition[];
}

export interface NpcView {
  definition: NpcDefinition;
  record?: NpcKnowledgeRecord;
  topics: NpcTopicView[];
  locationName: string;
  effectiveLocationId: string;
  inParty: boolean;
  known: boolean;
  talked: boolean;
}

export interface NpcTalkResult {
  save: GameSave;
  npc: NpcDefinition;
  topic: NpcTopicDefinition;
  locationId: string;
  inParty: boolean;
  companionRecruitId?: string;
  questEvent?: QuestEventInput;
}

export interface NpcContactResult {
  save: GameSave;
  npc: NpcDefinition;
  locationId: string;
  inParty: boolean;
}

