const NPC_BY_ID = new Map(NPC_DEFINITIONS.map(npc => [npc.id, npc]));

export function createInitialNpcState(): NpcState {
  return {
    knownNpcIds: [],
    records: {},
    talkLog: [],
    companions: {},
    generatedDraftLocationIds: [],
    flags: [],
  };
}

export function normalizeNpcState(raw: unknown): NpcState {
  const fallback = createInitialNpcState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<NpcState>;
  const flags = Array.from(new Set(candidate.flags || []));
  const records = Object.entries(candidate.records || {}).reduce<Record<string, NpcKnowledgeRecord>>((result, [npcId, record]) => {
    if (!NPC_BY_ID.has(npcId)) return result;
    result[npcId] = {
      npcId,
      discoveredAtIso: record.discoveredAtIso || nowIso(),
      lastTalkedAtIso: record.lastTalkedAtIso,
      talkCount: Math.max(0, Math.floor(record.talkCount || 0)),
      knownTopicIds: Array.from(new Set(record.knownTopicIds || [])),
      flags: Array.from(new Set(record.flags || [])),
    };
    return result;
  }, {});
  return {
    knownNpcIds: Array.from(new Set((candidate.knownNpcIds || []).filter(npcId => NPC_BY_ID.has(npcId)))),
    records,
    talkLog: (candidate.talkLog || []).filter(log => NPC_BY_ID.has(log.npcId)).slice(0, 30),
    companions: normalizeCompanionRecords(candidate.companions, flags),
    generatedDraftLocationIds: Array.from(new Set(candidate.generatedDraftLocationIds || [])),
    lastSceneDraft: candidate.lastSceneDraft,
    flags,
  };
}

export function getNpcDefinition(npcId: string): NpcDefinition | undefined {
  return NPC_BY_ID.get(npcId);
}

export function getLocationNpcDefinitions(locationId: string): NpcDefinition[] {
  return NPC_DEFINITIONS.filter(npc => npc.locationId === locationId);
}

function getItemCount(save: GameSave, itemId: string): number {
  return save.inventory.items.find(item => item.itemId === itemId)?.count || 0;
}

function hasActiveObjectiveForEvent(save: GameSave, targetId: string): boolean {
  return Object.values(save.quests.records).some(record => {
    if (record.status !== 'active') return false;
    const definition = getQuestDefinition(record.questId);
    return definition?.objectives.some(objective => objective.kind === 'event' && objective.targetId === targetId);
  });
}

function getTopicAvailability(save: GameSave, npc: NpcDefinition, topic: NpcTopicDefinition): Pick<NpcTopicView, 'available' | 'unavailableReason'> {
  if (topic.companionRecruitId) {
    const eligibility = canRecruitCompanion(save, topic.companionRecruitId);
    if (!eligibility.available) return { available: false, unavailableReason: eligibility.missing.join('；') };
  }

  const record = save.npc.records[npc.id];
  const knownTopicIds = record?.knownTopicIds || [];
  const missingKnownTopic = topic.requiredKnownTopicIds?.find(topicId => !knownTopicIds.includes(topicId));
  if (missingKnownTopic) return { available: false, unavailableReason: '需要先完成前置交谈。' };

  const missingQuest = topic.requiredQuestStatuses?.find(requirement => {
    const status = save.quests.records[requirement.questId]?.status;
    return !status || !requirement.statuses.includes(status);
  });
  if (missingQuest) return { available: false, unavailableReason: missingQuest.reason || '需要先推进相关任务。' };

  const missingItem = topic.requiredItems?.find(requirement => getItemCount(save, requirement.itemId) < requirement.count);
  if (missingItem) return { available: false, unavailableReason: missingItem.reason || '背包里缺少需要的物品。' };

  if (
    topic.kind === 'quest' &&
    topic.questEvent?.kind === 'event' &&
    !topic.requiredQuestStatuses?.length &&
    !hasActiveObjectiveForEvent(save, topic.questEvent.targetId)
  ) {
    return { available: false, unavailableReason: '需要先接取对应任务，才能确认这个过程。' };
  }

  return { available: true };
}

function buildTopicViews(save: GameSave, definition: NpcDefinition, includeCompanionTopics = true): NpcTopicView[] {
  return definition.topics
    .filter(topic => includeCompanionTopics || !topic.companionRecruitId)
    .filter(topic => !topic.companionRecruitId || !isCompanionJoined(save, topic.companionRecruitId))
    .map(topic => ({
      ...topic,
      ...getTopicAvailability(save, definition, topic),
    }));
}

export function getNpcViews(save: GameSave, locationId = save.map.currentLocationId): NpcView[] {
  const locationRows = getLocationNpcDefinitions(locationId).map(definition => {
    const record = save.npc.records[definition.id];
    return {
      definition,
      record,
      topics: buildTopicViews(save, definition),
      locationName: getLocationDefinition(definition.locationId)?.name || definition.locationId,
      effectiveLocationId: definition.locationId,
      inParty: isCompanionJoined(save, definition.id),
      known: save.npc.knownNpcIds.includes(definition.id),
      talked: Boolean(record?.lastTalkedAtIso),
    };
  });
  const existingIds = new Set(locationRows.map(view => view.definition.id));
  const partyRows = getJoinedCompanionViews(save)
    .filter(view => !existingIds.has(view.definition.npcId))
    .map(companion => {
      const definition = getNpcDefinition(companion.definition.npcId)!;
      const record = save.npc.records[definition.id];
      return {
        definition,
        record,
        topics: buildTopicViews(save, definition, false),
        locationName: '同行队伍',
        effectiveLocationId: locationId,
        inParty: true,
        known: true,
        talked: Boolean(record?.lastTalkedAtIso),
      };
    });
  return [...locationRows, ...partyRows];
}

function getNpcTopic(npc: NpcDefinition, topicId?: string): NpcTopicDefinition {
  const topic = topicId ? npc.topics.find(item => item.id === topicId) : npc.topics[0];
  if (!topic) throw Error('未知人物话题。');
  return topic;
}

export function contactNpc(save: GameSave, npcId: string): NpcContactResult {
  const npc = getNpcDefinition(npcId);
  if (!npc) throw Error('未知人物。');
  const inParty = isCompanionJoined(save, npc.id);
  if (!inParty && save.map.currentLocationId !== npc.locationId) throw Error('该人物不在当前位置。');
  const existing = save.npc.records[npc.id];
  const timestamp = nowIso();
  const record: NpcKnowledgeRecord = {
    npcId: npc.id,
    discoveredAtIso: existing?.discoveredAtIso || timestamp,
    lastTalkedAtIso: existing?.lastTalkedAtIso,
    talkCount: existing?.talkCount || 0,
    knownTopicIds: Array.from(new Set(existing?.knownTopicIds || [])),
    flags: Array.from(new Set(existing?.flags || [])),
  };
  return {
    save: {
      ...save,
      npc: {
        ...save.npc,
        knownNpcIds: Array.from(new Set([...save.npc.knownNpcIds, npc.id])),
        records: {
          ...save.npc.records,
          [npc.id]: record,
        },
      },
    },
    npc,
    locationId: inParty ? save.map.currentLocationId : npc.locationId,
    inParty,
  };
}

export function talkToNpc(save: GameSave, npcId: string, topicId?: string): NpcTalkResult {
  const npc = getNpcDefinition(npcId);
  if (!npc) throw Error('未知人物。');
  const inParty = isCompanionJoined(save, npc.id);
  if (!inParty && save.map.currentLocationId !== npc.locationId) throw Error('该人物不在当前位置。');
  const topic = getNpcTopic(npc, topicId);
  const availability = getTopicAvailability(save, npc, topic);
  if (!availability.available) throw Error(availability.unavailableReason || '这个话题当前还不能确认。');
  if (topic.companionRecruitId) {
    const eligibility = canRecruitCompanion(save, topic.companionRecruitId);
    if (!eligibility.available) throw Error(`暂不能邀请${eligibility.definition.name}入队：${eligibility.missing.join('；')}`);
  }
  const companionFlags = ['first_companion_lia', 'first_companion_leon'];
  if (topic.unlockFlag && companionFlags.includes(topic.unlockFlag)) {
    const selected = save.npc.flags.find(flag => companionFlags.includes(flag));
    if (selected && selected !== topic.unlockFlag) {
      throw Error('已经记录了另一位固定伙伴；第一版只允许从双胞胎中选择一位同行者。');
    }
  }
  const existing = save.npc.records[npc.id];
  const timestamp = nowIso();
  const knownTopicIds = Array.from(new Set([...(existing?.knownTopicIds || []), topic.id]));
  const record: NpcKnowledgeRecord = {
    npcId: npc.id,
    discoveredAtIso: existing?.discoveredAtIso || timestamp,
    lastTalkedAtIso: timestamp,
    talkCount: (existing?.talkCount || 0) + 1,
    knownTopicIds,
    flags: Array.from(new Set([...(existing?.flags || []), ...(topic.unlockFlag ? [topic.unlockFlag] : [])])),
  };
  const nextState: NpcState = {
    ...save.npc,
    knownNpcIds: Array.from(new Set([...save.npc.knownNpcIds, npc.id])),
    records: {
      ...save.npc.records,
      [npc.id]: record,
    },
    talkLog: [
      {
        id: createId('talk'),
        npcId: npc.id,
        npcName: npc.name,
        topicId: topic.id,
        topicLabel: topic.label,
        locationId: inParty ? save.map.currentLocationId : npc.locationId,
        summary: topic.summary,
        createdAtIso: timestamp,
      },
      ...save.npc.talkLog,
    ].slice(0, 30),
    flags: Array.from(new Set([...save.npc.flags, ...(topic.unlockFlag ? [topic.unlockFlag] : [])])),
  };
  const talkedSave: GameSave = {
    ...save,
    npc: nextState,
  };
  const recruitedSave = topic.companionRecruitId ? recruitCompanion(talkedSave, topic.companionRecruitId) : talkedSave;

  return {
    save: recruitedSave,
    npc,
    topic,
    locationId: inParty ? save.map.currentLocationId : npc.locationId,
    inParty: Boolean(topic.companionRecruitId) || inParty,
    companionRecruitId: topic.companionRecruitId,
    questEvent: topic.questEvent,
  };
}

function yamlQuote(value: string): string {
  return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

function stripCodeFence(value: string): string {
  const trimmed = stripGenerationShell(value).trim();
  const fence = trimmed.match(/^```(?:ya?ml)?\s*([\s\S]*?)\s*```$/i);
  return (fence?.[1] || trimmed).trim();
}

function stripGenerationShell(value: string): string {
  const source = String(value || '');
  const contentMatches = Array.from(source.matchAll(/<content\b[^>]*>([\s\S]*?)<\/content>/gi))
    .map(match => match[1].trim())
    .filter(Boolean);
  const body = contentMatches.length ? contentMatches.join('\n\n') : source;
  return body
    .replace(/<thinking\b[^>]*>[\s\S]*?<\/thinking>/gi, '')
    .replace(/<time\b[^>]*>[\s\S]*?<\/time>/gi, '')
    .replace(/<recap\b[^>]*>[\s\S]*?<\/recap>/gi, '')
    .replace(/<\/?content\b[^>]*>/gi, '')
    .trim();
}

function indentBlock(value: string, indent = 2): string {
  const pad = ' '.repeat(indent);
  return value
    .trim()
    .split(/\r?\n/)
    .map(line => `${pad}${line}`)
    .join('\n');
}

function normalizeNpcDraftBlock(rawText: string): string {
  const cleaned = stripCodeFence(rawText);
  if (/^\s*npcs\s*:/m.test(cleaned)) return cleaned;
  if (/^\s*-\s*name\s*:/m.test(cleaned)) return ['npcs:', indentBlock(cleaned, 2)].join('\n');
  return [
    'npcs:',
    '  - name: "未整理场景人物草案"',
    '    role: "场景草案"',
    '    location_anchor: "当前地点"',
    '    appearance: "需要用户确认前再次整理"',
    '    personality: "需要用户确认前再次整理"',
    '    voice: "需要用户确认前再次整理"',
    '    knows:',
    '      - "原始生成内容未按 YAML 列表输出，保留为待整理备注。"',
    '    talk_topics:',
    '      - label: "待整理"',
    '        use: "确认前不作为可互动话题"',
    '    story_use:',
    '      - "只能作为草案备注，不作为权威场景人物。"',
    '    limits:',
    '      - "不得宣告奖励、掉落、任务完成、地图解锁或装备变化。"',
    '    raw_notes: |-',
    indentBlock(cleaned || '空草案', 6),
  ].join('\n');
}

function extractDraftNpcNames(content: string): string[] {
  const names: string[] = [];
  content.split(/\r?\n/).forEach(line => {
    const match = line.match(/^\s*-?\s*name\s*:\s*["']?([^"'\n#]+?)["']?\s*$/);
    const name = match?.[1]?.trim();
    if (name && name.length <= 20) names.push(name);
  });
  return Array.from(new Set(names));
}

function buildSceneNpcWorldbookContent(save: GameSave, locationId: string, rawText: string): { content: string; triggerKeys: string[] } {
  const location = getLocationDefinition(locationId) || getCurrentLocation(save);
  const activeQuest = getActiveMainQuest(save);
  const npcBlock = normalizeNpcDraftBlock(rawText);
  const npcNames = extractDraftNpcNames(npcBlock);
  const content = [
    '# 8bit的幻想 / 当前存档场景人物记忆',
    '# 此条目由前端生成草案并经用户确认后写入当前聊天世界书。',
    'scene_npc_memory:',
    `  project: ${yamlQuote('8bit的幻想')}`,
    `  memory_kind: ${yamlQuote('npc')}`,
    `  scope: ${yamlQuote('current_chat_save_only')}`,
    `  source_location_id: ${yamlQuote(location.id)}`,
    `  source_location_name: ${yamlQuote(location.name)}`,
    `  source_region: ${yamlQuote(location.region)}`,
    `  related_main_quest_id: ${yamlQuote(activeQuest?.definition.id || '')}`,
    `  related_main_quest_name: ${yamlQuote(activeQuest?.definition.name || '')}`,
    '  usage:',
    '    - "这些人物是当前存档在该地点确认过的路人或局部人物，用于丰富世界和延续互动记忆。"',
    '    - "玩家位于该地点、提到这些名字，或正文与该地点相关时，可以引用他们的外貌、语气、传闻和生活细节。"',
    '    - "他们不是全项目固定人物、固定同伴、主线负责人、四天王、莱姆代理人或权威结算者。"',
    '    - "涉及经验、金币、物品、装备、地图权限、职业点、任务完成或战斗结果时，以前端事件包和存档记录为准。"',
    indentBlock(npcBlock, 2),
  ].join('\n');
  const triggerKeys = [
    `[8bit:location:${location.id}]`,
    `v1_0_loc_${location.id}`,
    location.id,
    location.name,
    location.region,
    ...npcNames,
  ];
  return { content, triggerKeys: Array.from(new Set(triggerKeys.filter(Boolean))) };
}

