export async function generateSceneNpcDraft(save: GameSave, locationId = save.map.currentLocationId): Promise<GameSave> {
  const location = getLocationDefinition(locationId);
  if (!location) throw Error('未知地点。');
  const rawContent = await generateWithProfile(save.api, 'npc_generation', {
    systemPrompt: buildSceneNpcDraftPrompt(save, locationId),
    userInput: `请为 ${location.name} 生成场景人物世界书草案。`,
    worldbookScanText: [
      '[8bit:worldbook-scan]',
      '[8bit:runtime:npc_draft]',
      `[8bit:location:${location.id}]`,
      `v1_0_loc_${location.id}`,
      location.name,
      location.region,
      ...getLocationNpcDefinitions(location.id).flatMap(npc => [`[8bit:npc:${npc.id}]`, npc.name, npc.title]),
    ].join('\n'),
    maxChatHistory: 0,
  });
  const { content, triggerKeys } = buildSceneNpcWorldbookContent(save, locationId, rawContent);
  const draftSave = createWorldbookDraft(save, {
    kind: 'npc',
    entryName: `8bit的幻想: ${location.name} 场景人物记忆`,
    content,
    triggerKeys,
    sourceLocationId: location.id,
    sourceLocationName: location.name,
  });
  const draft = draftSave.worldbookMemory.drafts[draftSave.worldbookMemory.drafts.length - 1];
  const timestamp = nowIso();
  return recordMessage(
    {
      ...draftSave,
      npc: {
        ...draftSave.npc,
        generatedDraftLocationIds: Array.from(new Set([...draftSave.npc.generatedDraftLocationIds, locationId])),
        lastSceneDraft: draft
          ? {
              draftId: draft.id,
              locationId,
              createdAtIso: timestamp,
            }
          : draftSave.npc.lastSceneDraft,
      },
    },
    'assistant',
    content,
  );
}
