import type { GameAction } from './actions';
import { getAchievementViews } from './achievements';
import { getClockDisplay } from './clock';
import { getCurrentLocation, getLocationDefinition } from './map';
import { buildSituationSummary } from './narration';
import { getActiveMainQuest, getQuestHint } from './quests';
import { getRealityCurrentLocation } from './reality';
import { GAME_CONTENT_VERSION, PLAYER_GENDER_LABELS, SAVE_SCHEMA_VERSION, V1_0_CONTENT_PACK_ID, type ApiTaskKind, type GameSave } from './types';

export type DebugCheckStatus = 'ok' | 'warn' | 'error';

export interface DebugCheck {
  id: string;
  label: string;
  status: DebugCheckStatus;
  message: string;
  detail?: string;
}

export interface DebugSummaryItem {
  label: string;
  value: string | number;
}

export interface WorldbookDebugPreview {
  name: string;
  bound: boolean;
  boundAtIso?: string;
  lastSyncAtIso?: string;
  lastError?: string;
  records: DebugSummaryItem[];
  pendingDrafts: DebugSummaryItem[];
  scanKeys: string[];
}

export interface AiInjectionDebugPreview {
  taskRoutes: DebugSummaryItem[];
  selectedWorldbookRecords: DebugSummaryItem[];
  situationSummary: string;
  orderedPromptPreview: string[];
}

export interface ApiProfileDebugRow {
  id: string;
  name: string;
  mode: string;
  method: string;
  tasks: string;
  model: string;
  lastTestResult: string;
}

export interface DraftDebugPreview {
  worldbookDrafts: DebugSummaryItem[];
  achievementDrafts: DebugSummaryItem[];
}

export interface DebugActionOption {
  id: string;
  label: string;
  description: string;
  action: GameAction;
}

export interface SaveDebugReport {
  generatedAtIso: string;
  status: DebugCheckStatus;
  checks: DebugCheck[];
  summary: DebugSummaryItem[];
  worldbook: WorldbookDebugPreview;
  aiInjection: AiInjectionDebugPreview;
  apiProfiles: ApiProfileDebugRow[];
  drafts: DraftDebugPreview;
  actionOptions: DebugActionOption[];
  buildCheck: DebugCheck;
}

const TASK_LABELS: Record<ApiTaskKind, string> = {
  opening: '开场白',
  main_narration: '主叙述',
  story_summary: '大总结',
  npc_generation: '人物生成',
  scene_expansion: '场景补全',
  combat_transcript: '战斗转写',
  companion_intent: '同伴行动',
  laimu_decision: '莱姆决策',
  achievement_generation: '成就生成',
  worldbook_organize: '世界书整理',
};

function nowDebugIso(): string {
  return new Date().toISOString();
}

function getWorstStatus(checks: DebugCheck[]): DebugCheckStatus {
  if (checks.some(check => check.status === 'error')) return 'error';
  if (checks.some(check => check.status === 'warn')) return 'warn';
  return 'ok';
}

function createCheck(id: string, label: string, status: DebugCheckStatus, message: string, detail?: string): DebugCheck {
  return { id, label, status, message, detail };
}

function compactText(text: string, length = 120): string {
  const normalized = text.replace(/\s+/g, ' ').trim();
  return normalized.length > length ? `${normalized.slice(0, length)}...` : normalized;
}

function buildHealthChecks(save: GameSave): DebugCheck[] {
  const checks: DebugCheck[] = [];
  const playerIdentityReady = Boolean(save.player?.username && save.player?.gender && save.player?.profileText);
  checks.push(
    createCheck(
      'schema',
      '存档结构',
      save.schemaVersion === SAVE_SCHEMA_VERSION ? 'ok' : 'error',
      save.schemaVersion === SAVE_SCHEMA_VERSION ? `schema v${save.schemaVersion}` : `schema 不匹配：${save.schemaVersion}`,
    ),
  );
  checks.push(createCheck('save_id', '存档 ID', save.saveId ? 'ok' : 'error', save.saveId || '缺少 saveId'));
  checks.push(
    createCheck(
      'player',
      '玩家状态',
      playerIdentityReady && save.playerState ? 'ok' : save.player || save.playerState ? 'warn' : 'warn',
      playerIdentityReady && save.playerState
        ? `现实身份齐全：${save.player!.username} / ${PLAYER_GENDER_LABELS[save.player!.gender]}`
        : '尚未完成用户名、性别、详细人设或玩家状态初始化',
    ),
  );
  checks.push(
    createCheck(
      'opening',
      '开场流程',
      save.stage === 'empty' || save.opening.status ? 'ok' : 'error',
      `stage=${save.stage} / opening=${save.opening.status}`,
    ),
  );
  checks.push(
    createCheck(
      'world_mode',
      '世界模式',
      save.worldMode === 'reality' || save.worldMode === 'eight_bit' ? 'ok' : 'error',
      save.worldMode,
    ),
  );
  checks.push(
    createCheck(
      'map_location',
      '8bit 地图',
      getLocationDefinition(save.map.currentLocationId) ? 'ok' : 'error',
      getCurrentLocation(save).name,
    ),
  );
  checks.push(createCheck('reality_location', '现实地点', getRealityCurrentLocation(save) ? 'ok' : 'error', getRealityCurrentLocation(save).name));
  checks.push(
    createCheck(
      'watch_panel',
      '手表面板',
      save.watch.unlockedPanels.includes(save.watch.activePanel) ? 'ok' : 'warn',
      `active=${save.watch.activePanel}`,
    ),
  );
  checks.push(
    createCheck(
      'combat',
      '战斗状态',
      save.combat.active && save.worldMode === 'reality' ? 'error' : 'ok',
      save.combat.active ? `战斗中 / ${save.combat.phase}` : '未在战斗',
    ),
  );
  checks.push(
    createCheck(
      'clock',
      '设定时间',
      save.clock.realityMinutesElapsed < 0 || save.clock.eightBitMinutesElapsed < 0 ? 'error' : 'ok',
      `${getClockDisplay(save.clock).reality.label} / ${getClockDisplay(save.clock).eightBit.label}`,
    ),
  );
  const missingRoute = Object.entries(save.api.taskRoutes).find(([, profileId]) => !save.api.profiles.some(profile => profile.id === profileId));
  checks.push(
    createCheck(
      'api_routes',
      '接口路由',
      missingRoute ? 'warn' : 'ok',
      missingRoute ? `${missingRoute[0]} 指向不存在的 profile` : `${save.api.profiles.length} 个 profile`,
    ),
  );
  checks.push(
    createCheck(
      'worldbook_binding',
      '世界书绑定',
      save.worldbookMemory.lastError ? 'error' : save.worldbookMemory.boundAtIso ? 'ok' : 'warn',
      save.worldbookMemory.lastError || (save.worldbookMemory.boundAtIso ? '已绑定' : '尚未记录绑定时间'),
    ),
  );
  checks.push(
    createCheck(
      'content_pack',
      '内容包',
      save.content?.enabledContentPackIds?.includes(V1_0_CONTENT_PACK_ID) && save.content.contentVersion === GAME_CONTENT_VERSION ? 'ok' : 'warn',
      save.content
        ? `${save.content.contentVersion} / ${save.content.enabledContentPackIds.join('、') || '无内容包'}`
        : '缺少内容包运行字段',
    ),
  );
  checks.push(
    createCheck(
      'drafts',
      '待处理草案',
      save.worldbookMemory.drafts.some(draft => draft.status === 'pending') || save.achievements.drafts.some(draft => draft.status === 'pending')
        ? 'warn'
        : 'ok',
      `世界书 ${save.worldbookMemory.drafts.filter(draft => draft.status === 'pending').length} / 成就 ${save.achievements.drafts.filter(draft => draft.status === 'pending').length}`,
    ),
  );
  return checks;
}

function buildWorldbookPreview(save: GameSave): WorldbookDebugPreview {
  const currentLocation = getCurrentLocation(save);
  const activeQuest = getActiveMainQuest(save);
  const scanKeys = [
    save.player ? '{{user}}现实身份' : '',
    save.player?.username || '',
    save.player ? `${save.player.username}现实身份` : '',
    currentLocation.name,
    currentLocation.region,
    activeQuest?.definition.name || '',
    save.worldMode === 'reality' ? '现实' : '8bit世界',
  ].filter(Boolean);
  return {
    name: save.worldbookMemory.worldbookName,
    bound: Boolean(save.worldbookMemory.boundAtIso),
    boundAtIso: save.worldbookMemory.boundAtIso,
    lastSyncAtIso: save.worldbookMemory.lastSyncAtIso,
    lastError: save.worldbookMemory.lastError,
    records: save.worldbookMemory.records.slice(-8).map(record => ({
      label: `${record.kind} / ${record.entryName}`,
      value: compactText(record.contentPreview, 90),
    })),
    pendingDrafts: save.worldbookMemory.drafts
      .filter(draft => draft.status === 'pending')
      .map(draft => ({ label: `${draft.kind} / ${draft.entryName}`, value: compactText(draft.content, 90) })),
    scanKeys,
  };
}

function buildAiInjectionPreview(save: GameSave): AiInjectionDebugPreview {
  const profileNameById = Object.fromEntries(save.api.profiles.map(profile => [profile.id, profile.name]));
  const selectedRecords = save.worldbookMemory.records
    .filter(record => record.kind === 'player_profile' || record.kind === 'npc' || record.kind === 'location' || record.kind === 'quest')
    .slice(-8)
    .map(record => ({ label: record.entryName, value: record.kind }));
  return {
    taskRoutes: Object.entries(save.api.taskRoutes).map(([task, profileId]) => ({
      label: TASK_LABELS[task as ApiTaskKind] || task,
      value: profileNameById[profileId] || profileId,
    })),
    selectedWorldbookRecords: selectedRecords,
    situationSummary: buildSituationSummary(save),
    orderedPromptPreview: [
      'system: 玩法权威规则与当前局势摘要',
      selectedRecords.length ? 'worldbook: 由前端挑选的相关记忆条目' : 'worldbook: 当前无可注入记忆条目',
      'user_input: 玩家本次意图',
    ],
  };
}

function buildApiProfileRows(save: GameSave): ApiProfileDebugRow[] {
  return save.api.profiles.map(profile => {
    const tasks = Object.entries(save.api.taskRoutes)
      .filter(([, profileId]) => profileId === profile.id)
      .map(([task]) => TASK_LABELS[task as ApiTaskKind] || task)
      .join('、');
    return {
      id: profile.id,
      name: profile.name,
      mode: profile.mode,
      method: profile.method,
      tasks: tasks || '未分配',
      model: profile.customApi?.model || profile.presetName || '随当前',
      lastTestResult: profile.lastTestResult || '未测试',
    };
  });
}

function buildDraftPreview(save: GameSave): DraftDebugPreview {
  return {
    worldbookDrafts: save.worldbookMemory.drafts.map(draft => ({
      label: `${draft.status} / ${draft.kind}`,
      value: draft.entryName,
    })),
    achievementDrafts: save.achievements.drafts.map(draft => ({
      label: `${draft.status} / ${draft.rarity}`,
      value: draft.title,
    })),
  };
}

function buildActionOptions(save: GameSave): DebugActionOption[] {
  const options: DebugActionOption[] = [
    {
      id: 'quest_sync',
      label: '同步任务',
      description: '重新按当前存档静态状态刷新任务。',
      action: { type: 'QUEST_SYNC' },
    },
    {
      id: 'achievement_sync',
      label: '同步成就',
      description: '重新检查固定成就是否应解锁。',
      action: { type: 'ACHIEVEMENT_SYNC' },
    },
    {
      id: 'time_zero',
      label: '校验时间戳',
      description: '用 +0m 时间戳检查时间解析与日志。',
      action: { type: 'TIME_SYNC_FROM_NARRATION', rawText: '[TIME: reality +0m]', source: 'manual' },
    },
  ];

  if (save.worldMode === 'reality' && ['room_origin', 'quiet_park'].includes(save.reality.currentLocationId)) {
    options.push({
      id: 'reality_rest',
      label: '现实休息',
      description: '执行一条现实休息行动，验证现实时间推进。',
      action: { type: 'REALITY_ACTION', actionId: 'rest_at_room' },
    });
  }

  return options;
}

function buildSummary(save: GameSave): DebugSummaryItem[] {
  const clock = getClockDisplay(save.clock);
  const activeQuest = getActiveMainQuest(save);
  return [
    { label: '玩家', value: save.player ? `${save.player.username} / ${PLAYER_GENDER_LABELS[save.player.gender]}` : '未创建' },
    { label: '阶段', value: save.stage },
    { label: '模式', value: save.worldMode },
    { label: '8bit 地点', value: getCurrentLocation(save).name },
    { label: '现实地点', value: getRealityCurrentLocation(save).name },
    { label: '现实时间', value: clock.reality.label },
    { label: '8bit 时间', value: clock.eightBit.label },
    { label: '主线', value: activeQuest?.definition.name || '无' },
    { label: '任务提示', value: getQuestHint(save) },
    { label: '内容版本', value: save.content?.contentVersion || '未记录' },
    { label: '成就', value: `${getAchievementViews(save).filter(view => view.unlocked).length}/${getAchievementViews(save).length}` },
    { label: '消息', value: save.messages.length },
  ];
}

export function buildSaveDebugReport(save: GameSave): SaveDebugReport {
  const checks = buildHealthChecks(save);
  const buildCheck = createCheck(
    'build',
    '构建检查',
    'ok',
    '开发期需运行 npm run build；本面板用于展示运行前状态，实际构建结果以终端为准。',
  );
  return {
    generatedAtIso: nowDebugIso(),
    status: getWorstStatus(checks),
    checks,
    summary: buildSummary(save),
    worldbook: buildWorldbookPreview(save),
    aiInjection: buildAiInjectionPreview(save),
    apiProfiles: buildApiProfileRows(save),
    drafts: buildDraftPreview(save),
    actionOptions: buildActionOptions(save),
    buildCheck,
  };
}
