export const useUiStore = defineStore('eight-bit-fantasy-ui', () => {
    const showDebug = ref(false);
    const shellTone = ref('reality');
    // P5-style menu system: menu is a full-screen overlay
    const menuOpen = ref(false);
    const menuPage = ref(null); // null = show menu list, string = show sub-page
    // Story collapsed (for game mode — hides story dialog)
    const storyCollapsed = ref(false);
    // Main-scene AIRP contact state
    const sceneCluesOpen = ref(false);
    const confirmEventId = ref(null);
    const activeNpcId = ref(null);
    function toggleDebug() {
        showDebug.value = !showDebug.value;
    }
    function setShellTone(tone) {
        shellTone.value = tone;
    }
    function openMenu() {
        menuOpen.value = true;
        menuPage.value = null;
    }
    function closeMenu() {
        menuOpen.value = false;
        menuPage.value = null;
    }
    function setMenuPage(page) {
        menuPage.value = page;
    }
    function backToMenuList() {
        menuPage.value = null;
    }
    function toggleStory() {
        storyCollapsed.value = !storyCollapsed.value;
    }
    function toggleSceneClues() {
        sceneCluesOpen.value = !sceneCluesOpen.value;
    }
    function closeSceneClues() {
        sceneCluesOpen.value = false;
    }
    function openConfirmEvent(eventId) {
        confirmEventId.value = eventId;
    }
    function closeConfirmEvent() {
        confirmEventId.value = null;
    }
    function setActiveNpc(npcId) {
        activeNpcId.value = npcId;
    }
    function clearActiveNpc() {
        activeNpcId.value = null;
    }
    return {
        showDebug,
        shellTone,
        menuOpen,
        menuPage,
        storyCollapsed,
        sceneCluesOpen,
        confirmEventId,
        activeNpcId,
        toggleDebug,
        setShellTone,
        openMenu,
        closeMenu,
        setMenuPage,
        backToMenuList,
        toggleStory,
        toggleSceneClues,
        closeSceneClues,
        openConfirmEvent,
        closeConfirmEvent,
        setActiveNpc,
        clearActiveNpc,
    };
});
