import type {
  GameSave,
  PlayerAttributeBlock,
  PlayerState,
  ProfessionId,
  ProfessionPointBlock,
  ProfessionPointKey,
  SkillId,
} from './types';

export interface ProfessionRequirement {
  points?: Partial<ProfessionPointBlock>;
  attributes?: Partial<PlayerAttributeBlock>;
  flags?: string[];
}

export interface ProfessionGrowth {
  hp: number;
  mp: number;
  primary: Partial<PlayerAttributeBlock>;
  secondary: Partial<PlayerAttributeBlock>;
}

export interface ProfessionDefinition {
  id: ProfessionId;
  name: string;
  role: string;
  description: string;
  recommendedAttributes: string[];
  requirements: ProfessionRequirement;
  attributeBonus: Partial<PlayerAttributeBlock>;
  growth: ProfessionGrowth;
  skillIds: SkillId[];
}

export interface ProfessionAvailability {
  definition: ProfessionDefinition;
  unlocked: boolean;
  active: boolean;
  canChange: boolean;
  missing: string[];
}

