export function createEmptyProfessionPoints(): ProfessionPointBlock {
  return {
    courage: 0,
    power: 0,
    wisdom: 0,
    dexterity: 0,
    faith: 0,
    charm: 0,
    shadow: 0,
  };
}

export function createInitialProfessionState(): PlayerState['professions'] {
  return {
    active: 'hero',
    unlocked: ['hero'],
    rankByProfession: {
      hero: 1,
      warrior_hero: 0,
      mage_hero: 0,
      thief_hero: 0,
      cleric_hero: 0,
    },
    flags: [],
  };
}

export function getProfessionDefinition(professionId: ProfessionId): ProfessionDefinition {
  return PROFESSION_DEFINITIONS.find(profession => profession.id === professionId) || PROFESSION_DEFINITIONS[0];
}

export function getActiveProfessionDefinition(player: PlayerState): ProfessionDefinition {
  return getProfessionDefinition(player.professions.active);
}

export function getProfessionAttributeBonus(player: PlayerState): PlayerAttributeBlock {
  const definition = getActiveProfessionDefinition(player);
  return {
    strength: definition.attributeBonus.strength || 0,
    constitution: definition.attributeBonus.constitution || 0,
    intelligence: definition.attributeBonus.intelligence || 0,
    spirit: definition.attributeBonus.spirit || 0,
    agility: definition.attributeBonus.agility || 0,
    technique: definition.attributeBonus.technique || 0,
    luck: definition.attributeBonus.luck || 0,
    will: definition.attributeBonus.will || 0,
  };
}

export function getLevelGrowthForProfession(professionId: ProfessionId): ProfessionGrowth {
  return getProfessionDefinition(professionId).growth;
}

function getLoadoutForProfession(professionId: ProfessionId): SkillId[] {
  const heroSkills = getProfessionDefinition('hero').skillIds;
  const professionSkills = professionId === 'hero' ? [] : getProfessionDefinition(professionId).skillIds;
  return Array.from(new Set([...heroSkills, ...professionSkills])).slice(0, 6);
}

function requirementMissing(
  player: PlayerState,
  definition: ProfessionDefinition,
  effectiveAttributes?: PlayerAttributeBlock,
): string[] {
  const missing: string[] = [];
  const points = definition.requirements.points || {};
  const attributes = definition.requirements.attributes || {};
  const flags = definition.requirements.flags || [];

  Object.entries(points).forEach(([key, value]) => {
    const pointKey = key as ProfessionPointKey;
    const required = value || 0;
    if (player.professionPoints[pointKey] < required) {
      missing.push(`${PROFESSION_POINT_LABELS[pointKey]} ${required}`);
    }
  });

  Object.entries(attributes).forEach(([key, value]) => {
    const attributeKey = key as keyof PlayerAttributeBlock;
    const required = value || 0;
    const current = effectiveAttributes?.[attributeKey] ?? player.baseAttributes[attributeKey];
    if (current < required) missing.push(`${PROFESSION_ATTRIBUTE_LABELS[attributeKey]} ${required}`);
  });

  flags.forEach(flag => {
    if (!player.professions.flags.includes(flag)) missing.push(flag);
  });

  return missing;
}

export function getAvailableProfessions(save: GameSave, effectiveAttributes?: PlayerAttributeBlock): ProfessionAvailability[] {
  const player = save.playerState;
  if (!player) {
    return PROFESSION_DEFINITIONS.map(definition => ({
      definition,
      unlocked: definition.id === 'hero',
      active: definition.id === 'hero',
      canChange: definition.id === 'hero',
      missing: definition.id === 'hero' ? [] : ['尚未创建玩家状态'],
    }));
  }

  return PROFESSION_DEFINITIONS.map(definition => {
    const unlocked = player.professions.unlocked.includes(definition.id);
    const missing = unlocked ? [] : requirementMissing(player, definition, effectiveAttributes);
    return {
      definition,
      unlocked,
      active: player.professions.active === definition.id,
      canChange: unlocked || missing.length === 0,
      missing,
    };
  });
}

export function canChangeProfession(
  save: GameSave,
  professionId: ProfessionId,
  effectiveAttributes?: PlayerAttributeBlock,
): { ok: boolean; missing: string[] } {
  if (!save.playerState) return { ok: false, missing: ['尚未创建玩家状态'] };
  if (professionId === 'hero') return { ok: true, missing: [] };

  const availability = getAvailableProfessions(save, effectiveAttributes).find(item => item.definition.id === professionId);
  if (!availability) return { ok: false, missing: ['未知职业'] };
  return { ok: availability.canChange, missing: availability.missing };
}

export function changeProfession(
  save: GameSave,
  professionId: ProfessionId,
  effectiveAttributes?: PlayerAttributeBlock,
): GameSave {
  if (!save.playerState) throw Error('尚未创建玩家状态。');
  const check = canChangeProfession(save, professionId, effectiveAttributes);
  if (!check.ok) throw Error(`转职条件未达成: ${check.missing.join('、')}`);

  const player = save.playerState;
  const unlocked = player.professions.unlocked.includes(professionId)
    ? player.professions.unlocked
    : [...player.professions.unlocked, professionId];

  return {
    ...save,
    playerState: {
      ...player,
      professions: {
        ...player.professions,
        active: professionId,
        unlocked,
        rankByProfession: {
          ...player.professions.rankByProfession,
          [professionId]: Math.max(player.professions.rankByProfession[professionId], 1),
        },
      },
      skills: {
        ...player.skills,
        loadoutSkillIds: getLoadoutForProfession(professionId),
      },
    },
  };
}

export function grantProfessionPoints(
  save: GameSave,
  points: Partial<ProfessionPointBlock>,
): GameSave {
  if (!save.playerState) throw Error('尚未创建玩家状态。');
  const nextPoints = { ...save.playerState.professionPoints };
  Object.entries(points).forEach(([key, value]) => {
    const pointKey = key as ProfessionPointKey;
    nextPoints[pointKey] = Math.max(0, nextPoints[pointKey] + Math.floor(value || 0));
  });

  return {
    ...save,
    playerState: {
      ...save.playerState,
      professionPoints: nextPoints,
    },
  };
}

export function grantProfessionFlag(save: GameSave, flag: string): GameSave {
  if (!save.playerState) throw Error('尚未创建玩家状态。');
  if (!flag.trim()) throw Error('职业条件标记不能为空。');
  if (save.playerState.professions.flags.includes(flag)) return save;
  return {
    ...save,
    playerState: {
      ...save.playerState,
      professions: {
        ...save.playerState.professions,
        flags: [...save.playerState.professions.flags, flag],
      },
    },
  };
}

export function resetProfessionPoints(save: GameSave): GameSave {
  if (!save.playerState) throw Error('尚未创建玩家状态。');
  return {
    ...save,
    playerState: {
      ...save.playerState,
      professions: {
        ...save.playerState.professions,
        active: 'hero',
      },
      skills: {
        ...save.playerState.skills,
        loadoutSkillIds: getLoadoutForProfession('hero'),
      },
    },
  };
}
