import { getItemDefinition, purchaseInventoryItem } from './inventory';
import { getNpcDefinition } from './npcs';
import type { GameSave } from './types';

export interface ShopItemDefinition {
  itemId: string;
  price: number;
  stockLabel: string;
}

export interface ShopItemView extends ShopItemDefinition {
  name: string;
  description: string;
}

const SHOP_ITEMS_BY_NPC: Record<string, ShopItemDefinition[]> = {
  merchant_norma: [
    { itemId: 'plain_bread', price: 12, stockLabel: '常备' },
    { itemId: 'small_heal_potion', price: 30, stockLabel: '常备' },
    { itemId: 'blue_drop', price: 42, stockLabel: '少量' },
    { itemId: 'antidote_herb', price: 24, stockLabel: '少量' },
  ],
};

export function getNpcShopItems(npcId?: string): ShopItemView[] {
  if (!npcId) return [];
  return (SHOP_ITEMS_BY_NPC[npcId] || [])
    .map(item => {
      const definition = getItemDefinition(item.itemId);
      if (!definition) return null;
      return {
        ...item,
        name: definition.name,
        description: definition.description,
      };
    })
    .filter((item): item is ShopItemView => Boolean(item));
}

export function buyShopItem(save: GameSave, npcId: string, itemId: string, count = 1): GameSave {
  const npc = getNpcDefinition(npcId);
  if (!npc || npc.role !== 'merchant') throw Error('该角色不是商人。');

  const shopItem = getNpcShopItems(npcId).find(item => item.itemId === itemId);
  if (!shopItem) throw Error('该商品当前不在货架上。');

  return purchaseInventoryItem(save, itemId, shopItem.price, count, `向${npc.name}购买${shopItem.name}`);
}
