export const DEDICATED_PRESET_NAME = '明月秋青_8bit';
export const DEDICATED_WORLDBOOK_NAME = '8bit的幻想_v1.0测试静态世界书';
const DEDICATED_WORLDBOOK_ALIASES = [DEDICATED_WORLDBOOK_NAME, '8bit的幻想_v1.0测试世界书'];
export const DEDICATED_RESOURCE_DIR_NAME = '专属预设和世界书';
export const DEDICATED_PRESET_FILENAME = '明月秋青_8bit.json';
export const DEDICATED_WORLDBOOK_FILENAME = '8bit的幻想_v1.0测试世界书.json';
const DEDICATED_RESOURCE_VERSION_TAG = '8bit-v1.0.9';
const DEDICATED_RESOURCE_REPO_PATH = `dist/8bit的幻想/${DEDICATED_RESOURCE_DIR_NAME}`;
const DEDICATED_RESOURCE_URL_BASES = [
  `https://testingcf.jsdelivr.net/gh/sanmingyue/tavern_dist@${DEDICATED_RESOURCE_VERSION_TAG}/${DEDICATED_RESOURCE_REPO_PATH}`,
  `https://cdn.jsdelivr.net/gh/sanmingyue/tavern_dist@${DEDICATED_RESOURCE_VERSION_TAG}/${DEDICATED_RESOURCE_REPO_PATH}`,
  `https://fastly.jsdelivr.net/gh/sanmingyue/tavern_dist@${DEDICATED_RESOURCE_VERSION_TAG}/${DEDICATED_RESOURCE_REPO_PATH}`,
  `https://gcore.jsdelivr.net/gh/sanmingyue/tavern_dist@${DEDICATED_RESOURCE_VERSION_TAG}/${DEDICATED_RESOURCE_REPO_PATH}`,
  `https://raw.githubusercontent.com/sanmingyue/tavern_dist/${DEDICATED_RESOURCE_VERSION_TAG}/${DEDICATED_RESOURCE_REPO_PATH}`,
];

interface NativeWorldbookEntry {
  uid?: number;
  displayIndex?: number;
  comment?: string;
  name?: string;
  disable?: boolean;
  constant?: boolean;
  selective?: boolean;
  vectorized?: boolean;
  key?: string[];
  selectiveLogic?: number;
  keysecondary?: string[];
  scanDepth?: number | null;
  position?: number;
  role?: number | null;
  depth?: number | null;
  order?: number;
  content?: string;
  probability?: number;
  excludeRecursion?: boolean;
  preventRecursion?: boolean;
  delayUntilRecursion?: boolean | number;
  sticky?: number | null;
  cooldown?: number | null;
  delay?: number | null;
  extra?: Record<string, unknown>;
}

interface NativeWorldbookFile {
  entries?: Record<string, NativeWorldbookEntry> | NativeWorldbookEntry[];
}

export interface DedicatedPresetInstallResult {
  name: string;
  imported: boolean;
  loaded: boolean;
}

export interface DedicatedWorldbookMergeResult {
  name: string;
  sourceEntries: number;
  overwritten: number;
  added: number;
  kept: number;
  enabledGlobally: boolean;
}

export interface DedicatedResourceInstallResult {
  preset: DedicatedPresetInstallResult;
  worldbook: DedicatedWorldbookMergeResult;
}

const SECONDARY_LOGIC: Record<number, WorldbookEntry['strategy']['keys_secondary']['logic']> = {
  0: 'and_any',
  1: 'not_all',
  2: 'not_any',
  3: 'and_all',
};

const POSITION_TYPES: Record<number, WorldbookEntry['position']['type']> = {
  0: 'before_character_definition',
  1: 'after_character_definition',
  2: 'before_author_note',
  3: 'after_author_note',
  4: 'at_depth',
  5: 'before_example_messages',
  6: 'after_example_messages',
};

const ROLE_TYPES: Record<number, WorldbookEntry['position']['role']> = {
  0: 'system',
  1: 'user',
  2: 'assistant',
};

function ensureStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) return [];
  return Array.from(new Set(value.map(item => String(item).trim()).filter(Boolean)));
}

function getDedicatedResourceUrls(filename: string): string[] {
  return DEDICATED_RESOURCE_URL_BASES.map(base => `${encodeURI(base)}/${encodeURIComponent(filename)}`);
}

async function fetchDedicatedResourceText(filename: string): Promise<string> {
  const errors: string[] = [];

  for (const url of getDedicatedResourceUrls(filename)) {
    try {
      const response = await fetch(url, { cache: 'no-cache' });
      if (response.ok) return response.text();
      errors.push(`${response.status} ${url}`);
    } catch (error) {
      errors.push(`${url} -> ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  throw Error(`读取专属资源失败：${filename}。已尝试 ${errors.join('；')}`);
}

async function getWorldbookSourceEntries(): Promise<NativeWorldbookEntry[]> {
  const rawText = await fetchDedicatedResourceText(DEDICATED_WORLDBOOK_FILENAME);
  const parsed = JSON.parse(rawText) as NativeWorldbookFile;
  const rawEntries = parsed.entries;
  if (!rawEntries) throw Error('专属世界书文件缺少 entries。');
  return Array.isArray(rawEntries) ? rawEntries : Object.values(rawEntries);
}

function getNativeEntryName(entry: NativeWorldbookEntry, index: number): string {
  const name = (entry.comment || entry.name || '').trim();
  if (name) return name;
  return `8bitF|unnamed|${index}`;
}

function getStrategyType(entry: NativeWorldbookEntry): WorldbookEntry['strategy']['type'] {
  if (entry.constant) return 'constant';
  if (entry.vectorized) return 'vectorized';
  return 'selective';
}

function delayUntilRecursion(value: NativeWorldbookEntry['delayUntilRecursion']): WorldbookEntry['recursion']['delay_until'] {
  if (typeof value === 'number') return value;
  return null;
}

function zeroableEffect(value: number | null | undefined): number | null {
  return typeof value === 'number' ? value : null;
}

function convertNativeWorldbookEntry(entry: NativeWorldbookEntry, index: number): PartialDeep<WorldbookEntry> {
  const positionType = POSITION_TYPES[entry.position ?? 0] || 'before_character_definition';
  return {
    name: getNativeEntryName(entry, index),
    enabled: entry.disable !== true,
    strategy: {
      type: getStrategyType(entry),
      keys: ensureStringArray(entry.key),
      keys_secondary: {
        logic: SECONDARY_LOGIC[entry.selectiveLogic ?? 0] || 'and_any',
        keys: ensureStringArray(entry.keysecondary),
      },
      scan_depth: typeof entry.scanDepth === 'number' ? entry.scanDepth : 'same_as_global',
    },
    position: {
      type: positionType,
      role: ROLE_TYPES[entry.role ?? 0] || 'system',
      depth: typeof entry.depth === 'number' ? entry.depth : 4,
      order: typeof entry.order === 'number' ? entry.order : index,
    },
    content: entry.content || '',
    probability: typeof entry.probability === 'number' ? entry.probability : 100,
    recursion: {
      prevent_incoming: Boolean(entry.excludeRecursion),
      prevent_outgoing: Boolean(entry.preventRecursion),
      delay_until: delayUntilRecursion(entry.delayUntilRecursion),
    },
    effect: {
      sticky: zeroableEffect(entry.sticky),
      cooldown: zeroableEffect(entry.cooldown),
      delay: zeroableEffect(entry.delay),
    },
    extra: {
      ...(entry.extra || {}),
      eightBitFantasyStatic: {
        source: 'dedicated_resource_pack',
        originalUid: entry.uid,
        originalDisplayIndex: entry.displayIndex,
      },
    },
  };
}

function resolveTargetWorldbookName(): string {
  const existing = typeof getWorldbookNames === 'function' ? getWorldbookNames() : [];
  return DEDICATED_WORLDBOOK_ALIASES.find(name => existing.includes(name)) || DEDICATED_WORLDBOOK_NAME;
}

async function getExistingWorldbookEntries(worldbookName: string): Promise<WorldbookEntry[]> {
  if (!getWorldbookNames().includes(worldbookName)) {
    await createWorldbook(worldbookName, []);
    return [];
  }
  return getWorldbook(worldbookName);
}

async function enableGlobalWorldbook(worldbookName: string): Promise<boolean> {
  const current = getGlobalWorldbookNames();
  if (current.includes(worldbookName)) return false;
  await rebindGlobalWorldbooks([...current, worldbookName]);
  return true;
}

export async function installDedicatedPreset(): Promise<DedicatedPresetInstallResult> {
  const presetRaw = await fetchDedicatedResourceText(DEDICATED_PRESET_FILENAME);
  const imported = await importRawPreset(DEDICATED_PRESET_NAME, presetRaw);
  const loaded = loadPreset(DEDICATED_PRESET_NAME);
  if (!loaded) throw Error(`专属预设已导入，但启用 ${DEDICATED_PRESET_NAME} 失败。`);
  return {
    name: DEDICATED_PRESET_NAME,
    imported,
    loaded,
  };
}

export async function mergeDedicatedWorldbook(): Promise<DedicatedWorldbookMergeResult> {
  const targetName = resolveTargetWorldbookName();
  const existingEntries = await getExistingWorldbookEntries(targetName);
  const sourceEntries = (await getWorldbookSourceEntries()).map(convertNativeWorldbookEntry);
  const sourceByName = new Map(sourceEntries.map(entry => [entry.name || '', entry]).filter(([name]) => name));

  let overwritten = 0;
  const merged = existingEntries.map(entry => {
    const next = sourceByName.get(entry.name);
    if (!next) return entry;
    overwritten += 1;
    sourceByName.delete(entry.name);
    return next;
  });

  const additions = Array.from(sourceByName.values());
  const kept = existingEntries.length - overwritten;
  await createOrReplaceWorldbook(targetName, [...merged, ...additions], { render: 'debounced' });
  const enabledGlobally = await enableGlobalWorldbook(targetName);

  return {
    name: targetName,
    sourceEntries: sourceEntries.length,
    overwritten,
    added: additions.length,
    kept,
    enabledGlobally,
  };
}

export async function installDedicatedResources(): Promise<DedicatedResourceInstallResult> {
  const preset = await installDedicatedPreset();
  const worldbook = await mergeDedicatedWorldbook();
  return { preset, worldbook };
}
