const ACTION_THRESHOLD = 10000;
const NORMAL_ACTION_COST = 10000;
const GUARD_ACTION_COST = 9000;
const ESCAPE_ACTION_COST = 10000;
const OVERFLOW_CAP = 2500;
const MAX_AUTO_STEPS = 240;

interface PlayerSkillRuntime {
  name: string;
  mpCost: number;
  damageKind: CombatDamageKind | 'support';
  multiplier: number;
  gaugeCost: number;
  statusId?: CombatStatusEffect['id'];
  statusLabel?: string;
  statusTurns?: number;
  healMultiplier?: number;
  criticalModifier?: number;
}

