function clamp(min: number, max: number, value: number): number {
  return Math.min(max, Math.max(min, value));
}

function createLog(text: string, tone: CombatLogEntry['tone'] = 'neutral'): CombatLogEntry {
  return {
    id: createId('combat-log'),
    tone,
    text,
    createdAtIso: nowIso(),
  };
}

function appendLog(combat: CombatState, text: string, tone: CombatLogEntry['tone'] = 'neutral'): CombatState {
  return {
    ...combat,
    log: [createLog(text, tone), ...combat.log].slice(0, 80),
  };
}

export function createInitialCombatState(): CombatState {
  return {
    active: false,
    phase: 'idle',
    round: 0,
    pulse: 0,
    actors: [],
    log: [],
  };
}

export function normalizeCombatState(raw: unknown): CombatState {
  const fallback = createInitialCombatState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<CombatState>;
  return {
    ...fallback,
    ...candidate,
    active: Boolean(candidate.active),
    phase: candidate.phase || fallback.phase,
    round: Math.max(0, Math.floor(candidate.round || 0)),
    pulse: Math.max(0, Math.floor(candidate.pulse || 0)),
    actors: candidate.actors || [],
    log: candidate.log || [],
  };
}

function livingActors(combat: CombatState): CombatActorState[] {
  return combat.actors.filter(actor => actor.alive && actor.currentHp > 0);
}

function partyActors(combat: CombatState): CombatActorState[] {
  return livingActors(combat).filter(actor => actor.side === 'party');
}

function enemyActors(combat: CombatState): CombatActorState[] {
  return livingActors(combat).filter(actor => actor.side === 'enemy');
}

function firstLivingEnemy(combat: CombatState): CombatActorState | undefined {
  return enemyActors(combat)[0];
}

function getActor(combat: CombatState, actorId: string): CombatActorState {
  const actor = combat.actors.find(item => item.id === actorId);
  if (!actor) throw Error('战斗对象不存在。');
  return actor;
}

function updateActor(combat: CombatState, actorId: string, updater: (actor: CombatActorState) => CombatActorState): CombatState {
  return {
    ...combat,
    actors: combat.actors.map(actor => (actor.id === actorId ? updater(actor) : actor)),
  };
}

function spendGauge(actor: CombatActorState, cost: number): CombatActorState {
  return {
    ...actor,
    gauge: clamp(0, OVERFLOW_CAP, actor.gauge - cost),
  };
}

function addStatus(actor: CombatActorState, status: CombatStatusEffect): CombatActorState {
  const existing = actor.statuses.filter(item => item.id !== status.id);
  return {
    ...actor,
    statuses: [...existing, status],
  };
}

function removeStatus(actor: CombatActorState, statusId: CombatStatusEffect['id']): CombatActorState {
  return {
    ...actor,
    statuses: actor.statuses.filter(status => status.id !== statusId),
  };
}

function hasStatus(actor: CombatActorState, statusId: CombatStatusEffect['id']): boolean {
  return actor.statuses.some(status => status.id === statusId);
}

function statusValue(actor: CombatActorState, statusId: CombatStatusEffect['id'], fallback = 0): number {
  return actor.statuses.find(status => status.id === statusId)?.value ?? fallback;
}

function effectiveSpeed(actor: CombatActorState): number {
  const speedDown = hasStatus(actor, 'speed_down') ? 0.72 : 1;
  return Math.max(45, Math.floor(actor.speed * speedDown));
}

function effectiveDefense(actor: CombatActorState, kind: CombatDamageKind): number {
  const base = kind === 'magical' ? actor.stats.magicalDefense : actor.stats.physicalDefense;
  const hardened = hasStatus(actor, 'hardened') ? 18 : 0;
  const defenseDown = hasStatus(actor, 'defense_down') ? 0.78 : 1;
  return Math.max(0, Math.floor((base + hardened) * defenseDown));
}

function effectiveEvasion(actor: CombatActorState): number {
  return actor.stats.evasionRate + statusValue(actor, 'evasion_up', 0);
}

function createPlayerActor(save: GameSave): CombatActorState {
  const playerSave = ensurePlayerState(save);
  const stats = getPlayerStats(playerSave);
  if (!stats || !playerSave.playerState) throw Error('尚未创建玩家状态。');
  const derived = stats.derived;
  return {
    id: 'player',
    kind: 'player',
    side: 'party',
    name: playerSave.player?.username || '主角',
    level: playerSave.playerState.level,
    currentHp: playerSave.playerState.currentHp,
    maxHp: derived.maxHp,
    currentMp: playerSave.playerState.currentMp,
    maxMp: derived.maxMp,
    gauge: 2500,
    speed: derived.speed,
    alive: playerSave.playerState.currentHp > 0,
    stats: {
      physicalAttack: derived.physicalAttack,
      physicalDefense: derived.physicalDefense,
      magicalAttack: derived.magicalAttack,
      magicalDefense: derived.magicalDefense,
      speed: derived.speed,
      hit: derived.hit,
      evasionRate: derived.evasionRate,
      criticalRate: derived.criticalRate,
      criticalDamage: derived.criticalDamage,
      statusAccuracy: derived.statusAccuracy,
      statusResistance: derived.statusResistance,
      healingPower: derived.healingPower,
    },
    skillIds: playerSave.playerState.skills.loadoutSkillIds,
    statuses: [],
  };
}

function createCompanionActors(save: GameSave): CombatActorState[] {
  return createCompanionCombatActors(save);
}

function createMonsterActors(encounter: MonsterEncounter): CombatActorState[] {
  return encounter.monsterIds.map((monsterId, index) => {
    const monster = getMonster(monsterId);
    const name = encounter.monsterIds.filter(id => id === monsterId).length > 1 ? `${monster.name}${index + 1}` : monster.name;
    return {
      id: createId('monster'),
      kind: 'monster',
      side: 'enemy',
      name,
      level: monster.level,
      currentHp: monster.maxHp,
      maxHp: monster.maxHp,
      gauge: Math.floor(Math.random() * 1800),
      speed: monster.stats.speed,
      alive: true,
      stats: monster.stats,
      skillIds: [],
      monsterId,
      statuses: [],
    };
  });
}

function syncPlayerFromCombat(save: GameSave): GameSave {
  if (!save.playerState) return syncCompanionVitalsFromCombat(save);
  if (save.combat.phase === 'defeat') return syncCompanionVitalsFromCombat(save);
  const playerActor = save.combat.actors.find(actor => actor.id === 'player');
  if (!playerActor) return syncCompanionVitalsFromCombat(save);
  return syncCompanionVitalsFromCombat({
    ...save,
    playerState: {
      ...save.playerState,
      currentHp: clamp(0, playerActor.maxHp, playerActor.currentHp),
      currentMp: clamp(0, playerActor.maxMp || save.playerState.currentMp, playerActor.currentMp ?? save.playerState.currentMp),
    },
  });
}

function damageActor(combat: CombatState, targetId: string, amount: number): CombatState {
  return updateActor(combat, targetId, actor => {
    const nextHp = Math.max(0, actor.currentHp - Math.max(0, Math.floor(amount)));
    return {
      ...actor,
      currentHp: nextHp,
      alive: nextHp > 0,
    };
  });
}

function healActor(combat: CombatState, targetId: string, amount: number): CombatState {
  return updateActor(combat, targetId, actor => ({
    ...actor,
    currentHp: Math.min(actor.maxHp, actor.currentHp + Math.max(0, Math.floor(amount))),
    alive: true,
  }));
}

function rollHit(attacker: CombatActorState, defender: CombatActorState, hitModifier = 0): boolean {
  const hitRate = clamp(0.35, 0.95, 0.82 + (attacker.stats.hit + hitModifier - effectiveEvasion(defender)) * 0.004);
  return Math.random() <= hitRate;
}

function rollCritical(attacker: CombatActorState, criticalModifier = 0): boolean {
  const criticalRate = clamp(0.03, 0.35, (attacker.stats.criticalRate + criticalModifier) / 100);
  return Math.random() <= criticalRate;
}

function computeDamage(
  attacker: CombatActorState,
  defender: CombatActorState,
  kind: CombatDamageKind,
  multiplier: number,
  criticalModifier = 0,
): { amount: number; critical: boolean } {
  if (kind === 'pure') return { amount: Math.max(1, Math.floor(multiplier)), critical: false };
  const attack = kind === 'magical' ? attacker.stats.magicalAttack : attacker.stats.physicalAttack;
  const defense = effectiveDefense(defender, kind);
  const randomWave = 0.92 + Math.random() * 0.16;
  const critical = rollCritical(attacker, criticalModifier);
  const criticalMultiplier = critical ? attacker.stats.criticalDamage / 100 : 1;
  const guardMultiplier = hasStatus(defender, 'guard') ? 0.65 : 1;
  const amount = Math.max(1, Math.floor(attack * multiplier * (100 / (100 + defense)) * randomWave * criticalMultiplier * guardMultiplier));
  return { amount, critical };
}

function applyStatusByChance(
  combat: CombatState,
  attacker: CombatActorState,
  target: CombatActorState,
  statusId: CombatStatusEffect['id'],
  label: string,
  turns: number,
  baseChance: number,
  value?: number,
): CombatState {
  const chance = clamp(0.05, 0.85, baseChance + (attacker.stats.statusAccuracy - target.stats.statusResistance) * 0.0035);
  if (Math.random() > chance) return appendLog(combat, `${target.name} 抵抗了${label}。`, 'neutral');
  return appendLog(
    updateActor(combat, target.id, actor =>
      addStatus(actor, {
        id: statusId,
        label,
        remainingTurns: turns,
        value,
      }),
    ),
    `${target.name} 受到${label}影响。`,
    statusId === 'guard' || statusId === 'evasion_up' || statusId === 'hardened' ? 'good' : 'bad',
  );
}

function decayActorStatuses(actor: CombatActorState): CombatActorState {
  return {
    ...actor,
    statuses: actor.statuses
      .map(status => ({ ...status, remainingTurns: status.remainingTurns - 1 }))
      .filter(status => status.remainingTurns > 0),
  };
}

function applyTurnStartEffects(combat: CombatState, actorId: string): CombatState {
  const actor = getActor(combat, actorId);
  if (!hasStatus(actor, 'poison')) return combat;
  const poisonDamage = Math.max(1, Math.floor(actor.maxHp * 0.05));
  const damaged = damageActor(combat, actorId, poisonDamage);
  return appendLog(damaged, `${actor.name} 受到中毒伤害 ${poisonDamage}。`, 'bad');
}

function resolveAttack(
  combat: CombatState,
  attackerId: string,
  targetId: string,
  name: string,
  kind: CombatDamageKind,
  multiplier: number,
  gaugeCost: number,
  hitModifier = 0,
  criticalModifier = 0,
): CombatState {
  const attacker = getActor(combat, attackerId);
  const defender = getActor(combat, targetId);
  let nextCombat = combat;
  if (!rollHit(attacker, defender, hitModifier)) {
    nextCombat = appendLog(combat, `${attacker.name} 使用${name}，但被 ${defender.name} 避开。`, 'neutral');
  } else {
    const result = computeDamage(attacker, defender, kind, multiplier, criticalModifier);
    nextCombat = damageActor(combat, targetId, result.amount);
    nextCombat = appendLog(
      nextCombat,
      `${attacker.name} 使用${name}，对 ${defender.name} 造成 ${result.amount} 点伤害${result.critical ? '，触发暴击' : ''}。`,
      attacker.side === 'party' ? 'good' : 'bad',
    );
  }
  return updateActor(nextCombat, attackerId, actor => decayActorStatuses(spendGauge(actor, gaugeCost)));
}

function resolveGuard(combat: CombatState, actorId: string, label = '防御', cost = GUARD_ACTION_COST): CombatState {
  return appendLog(
    updateActor(combat, actorId, actor =>
      decayActorStatuses(
        spendGauge(
          addStatus(actor, {
            id: 'guard',
            label,
            remainingTurns: 1,
            value: 0.35,
          }),
          cost,
        ),
      ),
    ),
    `${getActor(combat, actorId).name} 采取${label}。`,
    'good',
  );
}

function resolvePartySkill(combat: CombatState, actorId: string, skillId: SkillId, targetId?: string): CombatState {
  const skill = PLAYER_SKILL_RUNTIME[skillId];
  const caster = getActor(combat, actorId);
  if (caster.side !== 'party') throw Error('只有队伍成员可以使用这个技能。');
  if (!caster.skillIds.includes(skillId)) throw Error('当前没有装配该技能。');
  if ((caster.currentMp || 0) < skill.mpCost) throw Error('魔力不足。');

  let nextCombat = updateActor(combat, actorId, actor => ({
    ...actor,
    currentMp: Math.max(0, (actor.currentMp || 0) - skill.mpCost),
  }));

  if (skill.healMultiplier) {
    const target = targetId ? getActor(nextCombat, targetId) : caster;
    const healTarget = target.side === 'party' ? target : caster;
    const amount = Math.max(1, Math.floor(caster.stats.healingPower * skill.healMultiplier + caster.level * 2 + 22));
    nextCombat = healActor(nextCombat, healTarget.id, amount);
    nextCombat = appendLog(nextCombat, `${caster.name} 使用${skill.name}，为 ${healTarget.name} 回复 ${amount} 生命。`, 'good');
    return updateActor(nextCombat, actorId, actor => decayActorStatuses(spendGauge(actor, skill.gaugeCost)));
  }

  if (skillId === 'cleric_purify') {
    const target = targetId ? getActor(nextCombat, targetId) : caster;
    const purifyTarget = target.side === 'party' ? target : caster;
    nextCombat = updateActor(nextCombat, purifyTarget.id, actor => removeStatus(actor, 'poison'));
    nextCombat = appendLog(nextCombat, `${caster.name} 使用净化，移除了 ${purifyTarget.name} 的中毒。`, 'good');
    return updateActor(nextCombat, actorId, actor => decayActorStatuses(spendGauge(actor, skill.gaugeCost)));
  }

  if (skill.damageKind === 'support') {
    if (skill.statusId === 'guard') return resolveGuard(nextCombat, actorId, skill.statusLabel || skill.name, skill.gaugeCost);
    if (skill.statusId === 'hardened' || skill.statusId === 'evasion_up') {
      nextCombat = updateActor(nextCombat, actorId, actor =>
        addStatus(actor, {
          id: skill.statusId!,
          label: skill.statusLabel || skill.name,
          remainingTurns: skill.statusTurns || 1,
          value: skill.statusId === 'evasion_up' ? 14 : undefined,
        }),
      );
      nextCombat = appendLog(nextCombat, `${caster.name} 使用${skill.name}。`, 'good');
      return updateActor(nextCombat, actorId, actor => decayActorStatuses(spendGauge(actor, skill.gaugeCost)));
    }
    const target = skill.statusId === 'defense_down' || skill.statusId === 'speed_down' ? getActor(nextCombat, targetId || firstLivingEnemy(nextCombat)?.id || '') : caster;
    if (skill.statusId) {
      nextCombat = applyStatusByChance(
        nextCombat,
        caster,
        target,
        skill.statusId,
        skill.statusLabel || skill.name,
        skill.statusTurns || 1,
        0.95,
        undefined,
      );
    }
    nextCombat = appendLog(nextCombat, `${caster.name} 使用${skill.name}。`, 'good');
    return updateActor(nextCombat, actorId, actor => decayActorStatuses(spendGauge(actor, skill.gaugeCost)));
  }

  const target = getActor(nextCombat, targetId || firstLivingEnemy(nextCombat)?.id || '');
  nextCombat = resolveAttack(
    nextCombat,
    actorId,
    target.id,
    skill.name,
    skill.damageKind,
    skill.multiplier,
    skill.gaugeCost,
    0,
    skill.criticalModifier || 0,
  );
  if (skill.statusId && getActor(nextCombat, target.id).alive) {
    nextCombat = applyStatusByChance(nextCombat, caster, getActor(nextCombat, target.id), skill.statusId, skill.statusLabel || skill.name, skill.statusTurns || 1, 0.85);
  }
  return nextCombat;
}

function resolvePartyAttack(combat: CombatState, actorId: string, targetId?: string): CombatState {
  const target = getActor(combat, targetId || firstLivingEnemy(combat)?.id || '');
  const actor = getActor(combat, actorId);
  const name = actor.kind === 'player' ? '普通攻击' : '协同攻击';
  return resolveAttack(combat, actor.id, target.id, name, 'physical', actor.kind === 'player' ? 1 : 0.88, NORMAL_ACTION_COST);
}

function chooseMonsterTarget(combat: CombatState): CombatActorState {
  const target = partyActors(combat)[0];
  if (!target) throw Error('没有可攻击的队伍目标。');
  return target;
}

function resolveMonsterSupport(combat: CombatState, actor: CombatActorState, skill: MonsterSkillDefinition): CombatState {
  const statusId = skill.statusId;
  if (!statusId) return updateActor(combat, actor.id, item => spendGauge(item, skill.gaugeCost));
  const labelByStatus: Record<NonNullable<MonsterSkillDefinition['statusId']>, string> = {
    poison: '中毒',
    speed_down: '速度下降',
    evasion_up: '回避上升',
    hardened: '硬化',
  };
  return appendLog(
    updateActor(combat, actor.id, item =>
      decayActorStatuses(
        spendGauge(
          addStatus(item, {
            id: statusId,
            label: labelByStatus[statusId],
            remainingTurns: statusId === 'hardened' ? 2 : 1,
            value: statusId === 'evasion_up' ? 14 : undefined,
          }),
          skill.gaugeCost,
        ),
      ),
    ),
    `${actor.name} 使用${skill.name}。`,
    'bad',
  );
}

function resolveMonsterTurn(combat: CombatState, actorId: string): CombatState {
  let nextCombat = applyTurnStartEffects(combat, actorId);
  const actor = getActor(nextCombat, actorId);
  if (!actor.alive || !actor.monsterId) return updateActor(nextCombat, actorId, item => spendGauge(item, NORMAL_ACTION_COST));
  const monster = getMonster(actor.monsterId);
  const skill = pickMonsterSkill(monster);
  if (skill.damageKind === 'support') return resolveMonsterSupport(nextCombat, actor, skill);
  const target = chooseMonsterTarget(nextCombat);
  nextCombat = resolveAttack(
    nextCombat,
    actor.id,
    target.id,
    skill.name,
    skill.damageKind,
    skill.multiplier,
    skill.gaugeCost,
    skill.hitModifier || 0,
    skill.criticalModifier || 0,
  );
  if (skill.statusId && getActor(nextCombat, target.id).alive) {
    const statusLabel = skill.statusId === 'poison' ? '中毒' : skill.statusId === 'speed_down' ? '速度下降' : '异常';
    nextCombat = applyStatusByChance(nextCombat, actor, getActor(nextCombat, target.id), skill.statusId, statusLabel, 2, skill.statusChance || 0.25);
  }
  return nextCombat;
}

function checkCombatEnd(save: GameSave): GameSave {
  const combat = save.combat;
  if (!combat.active) return save;
  if (!enemyActors(combat).length) return finishCombatVictory(save);
  if (!partyActors(combat).length) return finishCombatDefeat(save);
  return save;
}

function nextReadyActor(combat: CombatState): CombatActorState | undefined {
  return livingActors(combat)
    .filter(actor => actor.gauge >= ACTION_THRESHOLD)
    .sort((a, b) => b.gauge - a.gauge || b.speed - a.speed || a.name.localeCompare(b.name, 'zh-Hans-CN'))[0];
}

function advanceGaugePulse(combat: CombatState): CombatState {
  return {
    ...combat,
    pulse: combat.pulse + 1,
    actors: combat.actors.map(actor =>
      actor.alive
        ? {
            ...actor,
            gauge: actor.gauge + effectiveSpeed(actor),
          }
        : actor,
    ),
  };
}

function advanceUntilPlayerAction(save: GameSave): GameSave {
  let nextSave = save;
  let steps = 0;
  while (nextSave.combat.active && nextSave.combat.phase !== 'awaiting_player' && steps < MAX_AUTO_STEPS) {
    nextSave = checkCombatEnd(nextSave);
    if (!nextSave.combat.active) return syncPlayerFromCombat(nextSave);
    const ready = nextReadyActor(nextSave.combat);
    if (!ready) {
      nextSave = {
        ...nextSave,
        combat: advanceGaugePulse(nextSave.combat),
      };
      steps += 1;
      continue;
    }
    if (ready.side === 'party') {
      nextSave = {
        ...nextSave,
        combat: appendLog(
          {
            ...nextSave.combat,
            phase: 'awaiting_player',
            pendingActorId: ready.id,
            round: nextSave.combat.round + 1,
          },
          `${ready.name} 可以行动。`,
          'system',
        ),
      };
      return syncPlayerFromCombat(nextSave);
    }
    nextSave = {
      ...nextSave,
      combat: resolveMonsterTurn(nextSave.combat, ready.id),
    };
    nextSave = syncPlayerFromCombat(checkCombatEnd(nextSave));
    steps += 1;
  }
  return syncPlayerFromCombat(nextSave);
}

function collectRewards(combat: CombatState): CombatRewards {
  const defeatedMonsters = combat.actors.filter(actor => actor.kind === 'monster' && actor.monsterId && !actor.alive);
  const drops: CombatDropReward[] = [];
  const rewards = defeatedMonsters.reduce(
    (sum, actor) => {
      const monster = getMonster(actor.monsterId!);
      drops.push(...rollMonsterDrops(monster.id));
      return {
        experience: sum.experience + monster.experience,
        gold: sum.gold + monster.gold,
        monsterIds: [...sum.monsterIds, monster.id],
      };
    },
    { experience: 0, gold: 0, monsterIds: [] as string[] },
  );
  return {
    ...rewards,
    drops,
  };
}

export function finishCombatVictory(save: GameSave): GameSave {
  const rewards = collectRewards(save.combat);
  const victoryCombat = appendLog(
    {
      ...save.combat,
      active: false,
      phase: 'victory',
      pendingActorId: undefined,
      lastRewards: rewards,
      transcriptSeed: `战斗胜利。击败 ${rewards.monsterIds.length} 个敌人，获得 ${rewards.experience} 经验、${rewards.gold} 金币。`,
    },
    `战斗胜利，获得 ${rewards.experience} 经验与 ${rewards.gold} 金币。`,
    'reward',
  );
  const withCombat = syncPlayerFromCombat({ ...save, combat: victoryCombat });
  const withInventory = addInventoryRewards(withCombat, rewards.gold, rewards.drops, '战斗胜利');
  const withPlayerExperience = addExperience(withInventory, rewards.experience, {
    kind: 'monster',
    id: rewards.monsterIds.join(','),
    label: '战斗胜利',
    level: Math.max(1, ...rewards.monsterIds.map(monsterId => getMonster(monsterId).level)),
  }).save;
  return addCompanionExperience(withPlayerExperience, rewards.experience, '战斗胜利');
}

export function finishCombatDefeat(save: GameSave): GameSave {
  const playerSave = ensurePlayerState(syncPlayerFromCombat(save));
  const player = playerSave.playerState!;
  const playerName = playerSave.player?.username || '主角';
  const stats = getPlayerStats(playerSave);
  const required = getNextLevelExperience(player.level);
  const lostExperience = Math.min(player.experience, Math.max(5, Math.floor(required * 0.08)));
  const revivedAtLocationId = playerSave.watch.anchorLocationId || (playerSave.map.unlockedLocationIds.includes('aruma_church') ? 'aruma_church' : 'initial_grassland');
  const companionDeathIds = playerSave.combat.actors
    .filter(actor => actor.kind === 'companion' && actor.permanentDeathIfDefeated && !actor.alive)
    .map(actor => actor.id);
  const defeatPenalty = {
    lostExperience,
    revivedAtLocationId,
    companionDeathIds,
  };
  const defeatCombat = appendLog(
    {
      ...playerSave.combat,
      active: false,
      phase: 'defeat',
      pendingActorId: undefined,
      defeatPenalty,
      transcriptSeed: `战斗失败。${playerName} 失去 ${lostExperience} 经验，并在 ${revivedAtLocationId} 复活。同行伙伴若死亡则永久死亡。`,
    },
    `${playerName} 倒下了，失去 ${lostExperience} 经验，并回到复活锚点。`,
    'bad',
  );
  const defeatedSave = {
    ...playerSave,
    combat: defeatCombat,
    map: {
      ...playerSave.map,
      currentLocationId: revivedAtLocationId,
      visitedLocationIds: Array.from(new Set([...playerSave.map.visitedLocationIds, revivedAtLocationId])),
    },
    playerState: {
      ...player,
      experience: Math.max(0, player.experience - lostExperience),
      currentHp: Math.max(1, Math.floor((stats?.derived.maxHp || player.currentHp || 1) * 0.5)),
      currentMp: Math.max(0, Math.floor((stats?.derived.maxMp || player.currentMp || 0) * 0.35)),
    },
  };
  return markCompanionsDead(defeatedSave, companionDeathIds);
}

function resolveEscape(save: GameSave): GameSave {
  const combat = applyTurnStartEffects(save.combat, 'player');
  const player = getActor(combat, 'player');
  if (!player.alive) return finishCombatDefeat({ ...save, combat });
  const enemyAverageSpeed =
    enemyActors(combat).reduce((sum, enemy) => sum + enemy.speed, 0) / Math.max(1, enemyActors(combat).length);
  const chance = clamp(0.28, 0.88, 0.48 + (player.speed - enemyAverageSpeed) * 0.002 + player.stats.evasionRate * 0.003);
  const escaped = Math.random() <= chance;
  if (escaped) {
    return syncPlayerFromCombat({
      ...save,
      combat: appendLog(
        {
          ...combat,
          active: false,
          phase: 'escaped',
          pendingActorId: undefined,
          transcriptSeed: `${player.name} 脱离战斗，没有获得奖励。`,
        },
        `${player.name} 脱离了战斗。`,
        'system',
      ),
    });
  }
  const failedCombat = appendLog(
    updateActor(combat, 'player', actor => decayActorStatuses(spendGauge(actor, ESCAPE_ACTION_COST))),
    '逃跑失败。',
    'bad',
  );
  return advanceUntilPlayerAction({
    ...save,
    combat: {
      ...failedCombat,
      phase: 'resolving',
      pendingActorId: undefined,
    },
  });
}

export function startCombat(save: GameSave, encounter: MonsterEncounter): GameSave {
  if (save.worldMode !== 'eight_bit') throw Error('只有在 8bit 世界才能进入战斗。');
  if (save.combat.active) throw Error('已经处于战斗中。');
  const playerSave = ensurePlayerState(save);
  const combat: CombatState = appendLog(
    {
      active: true,
      phase: 'idle',
      encounterId: encounter.id,
      locationId: encounter.locationId,
      round: 0,
      pulse: 0,
      actors: [createPlayerActor(playerSave), ...createCompanionActors(playerSave), ...createMonsterActors(encounter)],
      log: [],
    },
    `遭遇 ${encounter.name}。`,
    'system',
  );
  return advanceUntilPlayerAction({
    ...playerSave,
    combat,
  });
}

export function startRandomEncounter(save: GameSave, locationId = save.map.currentLocationId): GameSave {
  return startCombat(save, rollEncounter(locationId));
}

export function submitCombatCommand(save: GameSave, command: CombatCommand): GameSave {
  if (!save.combat.active || save.combat.phase !== 'awaiting_player') throw Error('当前没有等待玩家操作的战斗。');
  const pendingActorId = save.combat.pendingActorId;
  if (!pendingActorId) throw Error('缺少当前行动者。');
  const commandedActorId = command.actorId || pendingActorId;
  if (commandedActorId !== pendingActorId) throw Error('当前还没有轮到该角色行动。');
  const pendingActor = getActor(save.combat, pendingActorId);
  if (pendingActor.side !== 'party') throw Error('当前没有等待队伍角色行动。');
  let nextCombat = applyTurnStartEffects(save.combat, pendingActorId);
  const actor = getActor(nextCombat, pendingActorId);
  if (!actor.alive) return finishCombatDefeat({ ...save, combat: nextCombat });
  const targetId = command.targetId || firstLivingEnemy(nextCombat)?.id;

  if (command.kind === 'attack') {
    if (!targetId) throw Error('没有可攻击目标。');
    nextCombat = resolvePartyAttack(nextCombat, pendingActorId, targetId);
  } else if (command.kind === 'guard') {
    nextCombat = resolveGuard(nextCombat, pendingActorId);
  } else if (command.kind === 'skill') {
    if (!command.skillId) throw Error('缺少技能。');
    nextCombat = resolvePartySkill(nextCombat, pendingActorId, command.skillId, targetId);
  } else if (command.kind === 'escape') {
    if (pendingActorId !== 'player') throw Error('只有玩家本人行动时可以逃跑。');
    return resolveEscape(save);
  }

  const resolvingSave = checkCombatEnd({
    ...save,
    combat: {
      ...nextCombat,
      phase: 'idle',
      pendingActorId: undefined,
    },
  });
  if (!resolvingSave.combat.active) return syncPlayerFromCombat(resolvingSave);
  return advanceUntilPlayerAction(resolvingSave);
}

export function canSweepCombat(save: GameSave): boolean {
  if (!save.combat.active) return false;
  const monsterIds = Array.from(new Set(save.combat.actors.flatMap(actor => (actor.monsterId ? [actor.monsterId] : []))));
  if (!monsterIds.length) return false;
  return monsterIds.every(monsterId => {
    const role = getMonster(monsterId).role;
    return role !== 'elite' && role !== 'boss';
  });
}

function getLowestHpEnemyId(combat: CombatState): string | undefined {
  return enemyActors(combat).sort((left, right) => left.currentHp / left.maxHp - right.currentHp / right.maxHp)[0]?.id;
}

export function sweepCombat(save: GameSave): GameSave {
  if (!canSweepCombat(save)) throw Error('剧情精英、首领或不可扫荡战斗不能扫荡。');
  let nextSave = save;
  let steps = 0;
  while (nextSave.combat.active && steps < MAX_AUTO_STEPS) {
    if (nextSave.combat.phase === 'awaiting_player' && nextSave.combat.pendingActorId) {
      const actor = getActor(nextSave.combat, nextSave.combat.pendingActorId);
      const targetId = getLowestHpEnemyId(nextSave.combat);
      nextSave = submitCombatCommand(nextSave, {
        kind: actor.currentHp < actor.maxHp * 0.28 ? 'guard' : 'attack',
        actorId: actor.id,
        targetId,
      });
    } else {
      nextSave = advanceUntilPlayerAction(nextSave);
    }
    steps += 1;
  }
  if (nextSave.combat.active) throw Error('扫荡超过安全步数，已停止。');
  return nextSave;
}

export function getCombatSummary(save: GameSave): string {
  const combat = save.combat;
  const playerName = save.player?.username || combat.actors.find(actor => actor.id === 'player')?.name || '主角';
  if (!combat.active) {
    if (combat.phase === 'victory') return '上一场战斗胜利。';
    if (combat.phase === 'defeat') return `上一场战斗失败，${playerName} 已在锚点复活。`;
    if (combat.phase === 'escaped') return '上一场战斗已经脱离。';
    return '当前没有战斗。';
  }
  const enemies = enemyActors(combat).map(enemy => `${enemy.name} ${enemy.currentHp}/${enemy.maxHp}`).join('、');
  const player = combat.actors.find(actor => actor.id === 'player');
  return `战斗中。${playerName} 生命 ${player?.currentHp || 0}/${player?.maxHp || 0}；敌人: ${enemies}`;
}
