import { ensurePlayerState, getPlayerStats } from './player';
import { getEquippedItemCount } from './equipment';

export interface InventoryItemDefinition {
  itemId: string;
  name: string;
  kind: InventoryItemKind;
  description: string;
  usable?: boolean;
  effects?: {
    hp?: number;
    mp?: number;
  };
}

export interface InventoryItemView extends InventoryStack {
  description: string;
  usable: boolean;
  equippedCount: number;
  availableCount: number;
  effects?: InventoryItemDefinition['effects'];
}

export interface InventoryUseResult {
  save: GameSave;
  message: string;
}

