export const STARTER_ITEMS: InventoryStack[] = [
  { itemId: 'small_heal_potion', name: '小回复药', kind: 'consumable', count: 2 },
  { itemId: 'wooden_sword', name: '木剑', kind: 'equipment', count: 1 },
  { itemId: 'patched_cloth', name: '补丁布衣', kind: 'equipment', count: 1 },
];

const ITEM_BY_ID = new Map(ITEM_DEFINITIONS.map(item => [item.itemId, item]));

export function getItemDefinition(itemId: string): InventoryItemDefinition | undefined {
  return ITEM_BY_ID.get(itemId);
}

function normalizeStack(raw: InventoryStack): InventoryStack {
  const definition = getItemDefinition(raw.itemId);
  return {
    itemId: raw.itemId,
    name: definition?.name || raw.name || raw.itemId,
    kind: definition?.kind || raw.kind || 'material',
    count: Math.max(1, Math.floor(raw.count)),
  };
}

export function createInitialInventoryState(): InventoryState {
  return {
    gold: 0,
    items: STARTER_ITEMS.map(item => ({ ...item })),
    rewardLog: [],
  };
}

export function normalizeInventoryState(raw: unknown): InventoryState {
  const fallback = createInitialInventoryState();
  if (!raw || typeof raw !== 'object') return fallback;
  const candidate = raw as Partial<InventoryState>;
  return {
    gold: Math.max(0, Math.floor(candidate.gold || 0)),
    items: (candidate.items || [])
      .filter(item => item && item.itemId && item.count > 0)
      .map(item => normalizeStack(item)),
    rewardLog: (candidate.rewardLog || []).slice(0, 20),
  };
}

function mergeStacks(left: InventoryStack[], right: InventoryStack[]): InventoryStack[] {
  const byId = new Map<string, InventoryStack>();
  left.forEach(item => byId.set(item.itemId, { ...normalizeStack(item) }));
  right.forEach(item => {
    const normalized = normalizeStack(item);
    const existing = byId.get(normalized.itemId);
    byId.set(normalized.itemId, {
      ...normalized,
      count: (existing?.count || 0) + normalized.count,
    });
  });
  return Array.from(byId.values()).sort((a, b) => a.name.localeCompare(b.name, 'zh-Hans-CN'));
}

export function getInventoryItems(save: GameSave): InventoryItemView[] {
  return normalizeInventoryState(save.inventory).items.map(item => {
    const definition = getItemDefinition(item.itemId);
    const equippedCount = item.kind === 'equipment' ? getEquippedItemCount(save, item.itemId) : 0;
    const availableCount = Math.max(0, item.count - equippedCount);
    return {
      ...item,
      count: item.kind === 'equipment' ? availableCount : item.count,
      name: definition?.name || item.name,
      kind: definition?.kind || item.kind,
      description: definition?.description || '未登记的物品。后续数据表会补全。',
      usable: Boolean(definition?.usable),
      equippedCount,
      availableCount,
      effects: definition?.effects,
    };
  }).filter(item => item.kind !== 'equipment' || item.availableCount > 0);
}

export function addInventoryItem(save: GameSave, itemId: string, count = 1): GameSave {
  const definition = getItemDefinition(itemId);
  const item: InventoryStack = {
    itemId,
    name: definition?.name || itemId,
    kind: definition?.kind || 'material',
    count: Math.max(1, Math.floor(count)),
  };
  const inventory = normalizeInventoryState(save.inventory);
  return {
    ...save,
    inventory: {
      ...inventory,
      items: mergeStacks(inventory.items, [item]),
    },
  };
}

export function purchaseInventoryItem(save: GameSave, itemId: string, unitPrice: number, count = 1, label = '购买物品'): GameSave {
  const amount = Math.max(1, Math.floor(count));
  const price = Math.max(0, Math.floor(unitPrice)) * amount;
  const definition = getItemDefinition(itemId);
  if (!definition) throw Error('商品未登记。');

  const inventory = normalizeInventoryState(save.inventory);
  if (inventory.gold < price) throw Error('金币不足。');

  const item = normalizeStack({
    itemId,
    name: definition.name,
    kind: definition.kind,
    count: amount,
  });
  const log: InventoryRewardLogEntry = {
    id: createId('reward'),
    label: `${label} -${price}G`,
    gold: 0,
    items: [item],
    createdAtIso: nowIso(),
  };

  return {
    ...save,
    inventory: {
      gold: inventory.gold - price,
      items: mergeStacks(inventory.items, [item]),
      rewardLog: [log, ...inventory.rewardLog].slice(0, 20),
    },
  };
}

export function removeInventoryItem(save: GameSave, itemId: string, count = 1): GameSave {
  const amount = Math.max(1, Math.floor(count));
  const inventory = normalizeInventoryState(save.inventory);
  const existing = inventory.items.find(item => item.itemId === itemId);
  if (!existing || existing.count < amount) throw Error('背包里没有足够的物品。');
  return {
    ...save,
    inventory: {
      ...inventory,
      items: inventory.items
        .map(item => (item.itemId === itemId ? { ...item, count: item.count - amount } : item))
        .filter(item => item.count > 0),
    },
  };
}

export function useInventoryItem(save: GameSave, itemId: string): InventoryUseResult {
  if (save.combat.active) throw Error('战斗中的道具指令会在战斗模块扩展中接入；当前只能脱离战斗后使用。');

  const definition = getItemDefinition(itemId);
  if (!definition?.usable || !definition.effects) throw Error('这个物品当前不能直接使用。');

  const playerSave = ensurePlayerState(save);
  const stats = getPlayerStats(playerSave);
  if (!stats || !playerSave.playerState) throw Error('还没有可恢复的玩家状态。');

  const player = playerSave.playerState;
  const nextHp = Math.min(stats.derived.maxHp, player.currentHp + (definition.effects.hp || 0));
  const nextMp = Math.min(stats.derived.maxMp, player.currentMp + (definition.effects.mp || 0));
  if (nextHp === player.currentHp && nextMp === player.currentMp) throw Error('现在还不需要使用这个物品。');

  const consumedSave = removeInventoryItem(playerSave, itemId, 1);
  return {
    save: {
      ...consumedSave,
      playerState: {
        ...player,
        currentHp: nextHp,
        currentMp: nextMp,
      },
    },
    message: `${definition.name} 已使用。`,
  };
}

export function addInventoryRewards(save: GameSave, gold: number, drops: CombatDropReward[], label: string): GameSave {
  const inventory = normalizeInventoryState(save.inventory);
  const items = drops.map(drop => normalizeStack({
    itemId: drop.itemId,
    name: drop.name,
    kind: drop.kind,
    count: Math.max(1, Math.floor(drop.count)),
  }));
  const log: InventoryRewardLogEntry = {
    id: createId('reward'),
    label,
    gold: Math.max(0, Math.floor(gold)),
    items,
    createdAtIso: nowIso(),
  };
  return {
    ...save,
    inventory: {
      gold: inventory.gold + log.gold,
      items: mergeStacks(inventory.items, items),
      rewardLog: [log, ...inventory.rewardLog].slice(0, 20),
    },
  };
}
