import type { GameAction } from './actions';
import { getAvailableTravelTargets, getCurrentLocation } from './map';
import { getEncounterTable } from './monsters';
import { getNpcViews } from './npcs';
import { getQuestViews, type QuestDefinition, type QuestObjectiveDefinition, type QuestView } from './quests';
import type { GameSave, QuestObjectiveState } from './types';

export type SceneMarkerTone = 'red' | 'gold' | 'blue' | 'purple' | 'orange' | 'green' | 'gray' | 'white';
export type SceneContactKind = 'route' | 'npc' | 'quest' | 'danger' | 'objective';
export type SceneConfirmKind =
  | 'travel'
  | 'npc_contact'
  | 'quest_accept'
  | 'quest_turn_in'
  | 'quest_progress'
  | 'combat_start';

export interface SceneConfirmEvent {
  id: string;
  kind: SceneConfirmKind;
  title: string;
  body: string;
  confirmLabel: string;
  cancelLabel: string;
  markerTone: SceneMarkerTone;
  priority: number;
  action: GameAction;
  locationId?: string;
  relatedNpcId?: string;
  questId?: string;
  objectiveId?: string;
  worldbookScanTags: string[];
}

export interface SceneContactTarget {
  id: string;
  kind: SceneContactKind;
  title: string;
  subtitle: string;
  description: string;
  markerTone: SceneMarkerTone;
  priority: number;
  confirmEventId?: string;
  locationId?: string;
  relatedNpcId?: string;
  questId?: string;
  objectiveId?: string;
  worldbookScanTags: string[];
}

function scanTags(input: {
  locationId?: string;
  npcId?: string;
  questId?: string;
  eventKind?: string;
  extra?: string[];
}): string[] {
  return Array.from(
    new Set(
      [
        '[8bit:runtime]',
        '[8bit:v1_0]',
        input.locationId ? `[8bit:location:${input.locationId}]` : '',
        input.locationId ? `v1_0_loc_${input.locationId}` : '',
        input.npcId ? `[8bit:npc:${input.npcId}]` : '',
        input.npcId ? `v1_0_npc_${input.npcId}` : '',
        input.questId ? `[8bit:quest:${input.questId}]` : '',
        input.questId ? `v1_0_${input.questId}` : '',
        input.eventKind ? `[8bit:event:${input.eventKind}]` : '',
        ...(input.extra || []),
      ].filter(Boolean),
    ),
  );
}

function questGiverIsHere(definition: QuestDefinition, npcNamesHere: Set<string>): boolean {
  if (!definition.giver) return false;
  return npcNamesHere.has(definition.giver);
}

function questBelongsToCurrentLocation(view: QuestView, currentLocationId: string, npcNamesHere: Set<string>): boolean {
  const definition = view.definition;
  if (definition.locationId === currentLocationId) return true;
  if (questGiverIsHere(definition, npcNamesHere)) return true;
  return definition.objectives.some(objective => objective.kind === 'travel' && objective.targetId === currentLocationId);
}

function getObjectiveState(view: QuestView, objective: QuestObjectiveDefinition): QuestObjectiveState | undefined {
  return view.record.objectiveStates.find(item => item.objectiveId === objective.id);
}

function previousObjectivesCompleted(view: QuestView, objective: QuestObjectiveDefinition): boolean {
  const objectiveIndex = view.definition.objectives.findIndex(item => item.id === objective.id);
  if (objectiveIndex <= 0) return true;
  return view.definition.objectives.slice(0, objectiveIndex).every(previous => getObjectiveState(view, previous)?.completed);
}

function createTravelEvent(target: ReturnType<typeof getAvailableTravelTargets>[number]): SceneConfirmEvent {
  return {
    id: `scene_evt_travel_${target.id}`,
    kind: 'travel',
    title: `前往${target.name}`,
    body: `从当前位置出发前往${target.name}。确认后会完成地图移动，并把路上的经过写入正文日志。`,
    confirmLabel: '前往',
    cancelLabel: '先不去',
    markerTone: 'white',
    priority: 20,
    action: { type: 'MAP_TRAVEL', locationId: target.id },
    locationId: target.id,
    worldbookScanTags: scanTags({ locationId: target.id, eventKind: 'map_travel', extra: [target.name, target.region] }),
  };
}

function createNpcContactEvent(npcView: ReturnType<typeof getNpcViews>[number]): SceneConfirmEvent {
  const npc = npcView.definition;
  const locationId = npcView.effectiveLocationId || npc.locationId;
  return {
    id: `scene_evt_npc_contact_${npc.id}`,
    kind: 'npc_contact',
    title: `接近${npc.name}`,
    body: `${npcView.inParty ? `${npc.name}当前已经在队伍中。` : ''}靠近${npc.name}并让正文承认这次接触。确认后不会固定回复一句话，而是进入可自由输入的人物交谈状态。`,
    confirmLabel: '接近',
    cancelLabel: '先观察',
    markerTone: npcView.known ? 'blue' : 'gold',
    priority: npcView.known ? 35 : 25,
    action: { type: 'NPC_CONTACT', npcId: npc.id },
    locationId,
    relatedNpcId: npc.id,
    worldbookScanTags: scanTags({
      locationId,
      npcId: npc.id,
      eventKind: 'npc_contact',
      extra: [npc.name, npc.title, ...(npcView.inParty ? ['[8bit:party]', '[8bit:event:companion_recruit]'] : [])],
    }),
  };
}

function createQuestAcceptEvent(view: QuestView): SceneConfirmEvent {
  const quest = view.definition;
  return {
    id: `scene_evt_quest_accept_${quest.id}`,
    kind: 'quest_accept',
    title: `接取《${quest.name}》`,
    body: `${quest.summary} 确认后，任务会进入进行中，并由正文写出委托、人物反应和可继续追问的任务开端。`,
    confirmLabel: '接下',
    cancelLabel: '再问问',
    markerTone: quest.kind === 'main' ? 'red' : 'gold',
    priority: quest.kind === 'main' ? 5 : 30,
    action: { type: 'QUEST_ACCEPT', questId: quest.id },
    locationId: quest.locationId,
    questId: quest.id,
    worldbookScanTags: scanTags({ locationId: quest.locationId, questId: quest.id, eventKind: 'quest_accept', extra: [quest.name, quest.chapter] }),
  };
}

function createQuestTurnInEvent(view: QuestView): SceneConfirmEvent {
  const quest = view.definition;
  return {
    id: `scene_evt_quest_turn_in_${quest.id}`,
    kind: 'quest_turn_in',
    title: `交付《${quest.name}》`,
    body: `《${quest.name}》的目标已经满足。确认后，会完成任务结算，并把交接、人物反应和已确认的结果写入正文。`,
    confirmLabel: '交付',
    cancelLabel: '稍后',
    markerTone: 'green',
    priority: quest.kind === 'main' ? 4 : 18,
    action: { type: 'QUEST_TURN_IN', questId: quest.id },
    locationId: quest.locationId,
    questId: quest.id,
    worldbookScanTags: scanTags({ locationId: quest.locationId, questId: quest.id, eventKind: 'quest_turn_in', extra: [quest.name, quest.chapter] }),
  };
}

function createQuestObjectiveEvent(
  view: QuestView,
  objective: QuestObjectiveDefinition,
  currentLocationId: string,
): SceneConfirmEvent | null {
  const quest = view.definition;
  const base = {
    questId: quest.id,
    objectiveId: objective.id,
    locationId: currentLocationId,
    worldbookScanTags: scanTags({
      locationId: currentLocationId,
      questId: quest.id,
      eventKind: 'quest_progress',
      extra: [quest.name, objective.label],
    }),
  };

  if (objective.kind === 'event' && objective.targetId) {
    return {
      ...base,
      id: `scene_evt_quest_progress_${quest.id}_${objective.id}`,
      kind: 'quest_progress',
      title: objective.label,
      body: `这是《${quest.name}》的可确认过程点。确认后只推进这个目标，并把调查、记录或行动过程写入正文。`,
      confirmLabel: '确认进展',
      cancelLabel: '先等等',
      markerTone: 'purple',
      priority: quest.kind === 'main' ? 12 : 42,
      action: { type: 'QUEST_PROGRESS', event: { kind: 'event', targetId: objective.targetId, locationId: currentLocationId } },
    };
  }

  if (objective.kind === 'anchor' && objective.targetId === currentLocationId) {
    return {
      ...base,
      id: `scene_evt_quest_anchor_${quest.id}_${objective.id}`,
      kind: 'quest_progress',
      title: objective.label,
      body: `在当前地点确认锚点相关目标。确认后登记锚点状态，并写成场景内仪式或确认过程。`,
      confirmLabel: '确认锚点',
      cancelLabel: '稍后',
      markerTone: 'blue',
      priority: 14,
      action: { type: 'QUEST_PROGRESS', event: { kind: 'anchor_set', locationId: currentLocationId } },
    };
  }

  return null;
}

function createCombatEvent(save: GameSave): SceneConfirmEvent | null {
  if (save.worldMode !== 'eight_bit' || save.combat.active) return null;
  const table = getEncounterTable(save.map.currentLocationId);
  if (!table.length) return null;
  const current = getCurrentLocation(save);
  const monsterTags = table.map(entry => `[8bit:monster:${entry.monsterId}]`);
  return {
    id: `scene_evt_combat_${current.id}`,
    kind: 'combat_start',
    title: '危险在附近活动',
    body: `当前地点存在遭遇表。确认后会进入战斗；普通战斗的胜负、伤害和掉落都会在战斗结束时结算，结束后可手动选择是否写成正文。`,
    confirmLabel: '靠近危险',
    cancelLabel: '保持距离',
    markerTone: 'red',
    priority: 55,
    action: { type: 'COMBAT_START_RANDOM', locationId: current.id },
    locationId: current.id,
    worldbookScanTags: scanTags({ locationId: current.id, eventKind: 'combat_start', extra: [current.name, ...monsterTags] }),
  };
}

const CONTACT_KIND_LABELS: Record<SceneContactKind, string> = {
  route: '路线',
  npc: '人物',
  quest: '任务',
  danger: '危险',
  objective: '任务过程',
};

const CONFIRM_KIND_LABELS: Record<SceneConfirmKind, string> = {
  travel: '移动到新地点',
  npc_contact: '接近人物',
  quest_accept: '接取任务',
  quest_turn_in: '交付任务',
  quest_progress: '推进目标',
  combat_start: '进入战斗',
};

export function getConfirmableEvents(save: GameSave): SceneConfirmEvent[] {
  const current = getCurrentLocation(save);
  const npcViews = getNpcViews(save);
  const npcNamesHere = new Set(npcViews.flatMap(view => [view.definition.name, view.definition.title]));
  const questViews = getQuestViews(save).filter(view => questBelongsToCurrentLocation(view, current.id, npcNamesHere));
  const events: SceneConfirmEvent[] = [
    ...getAvailableTravelTargets(save).map(createTravelEvent),
    ...npcViews.map(createNpcContactEvent),
    ...questViews.filter(view => view.canAccept).map(createQuestAcceptEvent),
    ...questViews.filter(view => view.canTurnIn).map(createQuestTurnInEvent),
  ];

  questViews
    .filter(view => view.record.status === 'active')
    .forEach(view => {
      view.definition.objectives.forEach(objective => {
        const objectiveState = getObjectiveState(view, objective);
        if (objectiveState?.completed) return;
        if (!previousObjectivesCompleted(view, objective)) return;
        const event = createQuestObjectiveEvent(view, objective, current.id);
        if (event) events.push(event);
      });
    });

  const combatEvent = createCombatEvent(save);
  if (combatEvent) events.push(combatEvent);

  return events.sort((left, right) => left.priority - right.priority || left.title.localeCompare(right.title, 'zh-Hans-CN'));
}

export function getContactTargets(save: GameSave): SceneContactTarget[] {
  const events = getConfirmableEvents(save);
  return events.map(event => {
    const kind: SceneContactKind =
      event.kind === 'travel'
        ? 'route'
        : event.kind === 'npc_contact'
          ? 'npc'
          : event.kind === 'combat_start'
            ? 'danger'
            : event.kind === 'quest_progress'
              ? 'objective'
              : 'quest';
    return {
      id: `scene_contact_${event.id}`,
      kind,
      title: event.title,
      subtitle: `${CONTACT_KIND_LABELS[kind]} · ${CONFIRM_KIND_LABELS[event.kind]}`,
      description: event.body,
      markerTone: event.markerTone,
      priority: event.priority,
      confirmEventId: event.id,
      locationId: event.locationId,
      relatedNpcId: event.relatedNpcId,
      questId: event.questId,
      objectiveId: event.objectiveId,
      worldbookScanTags: event.worldbookScanTags,
    };
  });
}
